    /// A committed subset small-file rewrite must delete the old current
    /// snapshot's catalog rows at the commit — both its manifest
    /// (`cayenne_snapshot_file`) and its per-file stats cache
    /// (`cayenne_snapshot_file_statistics`). Without the prune, every subset pass
    /// on a repeatedly-compacted table leaks those rows unbounded, because the
    /// subset path only flips the current pointer and never clears the snapshot
    /// it leaves behind. Safe to prune to the single new snapshot because the
    /// subset path runs only when there are no protected snapshots.
    #[tokio::test]
    async fn subset_rewrite_deletes_old_snapshot_manifest_and_stats_rows() {
        use arrow::array::{Int64Array, StringArray};
        use arrow::datatypes::{DataType, Field, Schema};

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Utf8, false),
        ]));
        let batch_of = |start: i64, n: i64| {
            let ids: Vec<i64> = (start..start + n).collect();
            let values: Vec<String> = ids.iter().map(|i| format!("v_{i:0400}")).collect();
            RecordBatch::try_new(
                Arc::clone(&schema),
                vec![
                    Arc::new(Int64Array::from(ids)),
                    Arc::new(StringArray::from(values)),
                ],
            )
            .expect("batch built")
        };

        let vortex_config = VortexConfig {
            target_vortex_file_size_mb: 1,
            compaction_trigger_files: 1_000,
            compaction_background_interval_ms: 0,
            compaction_max_files_per_pick: 2,
            inline_max_rows: 0,
            deletion_mode: crate::metadata::DeletionMode::Key,
            ..VortexConfig::default()
        };
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_cayenne_table_with_config(
            "subset_manifest_gc",
            Arc::clone(&schema),
            vortex_config,
            vec!["id".to_string()],
            ctx.runtime_env(),
        )
        .await;

        for i in 0..4 {
            insert_batch(&provider, batch_of(i * 50, 50)).await;
        }

        let source_snapshot_id = provider.get_current_snapshot_id();
        let generation_before = provider.current_dir_generation.load(Ordering::Relaxed);
        let files = provider
            .list_snapshot_files_with_sizes(&source_snapshot_id)
            .await
            .expect("listed current snapshot files");
        assert!(
            files.len() >= 3,
            "need a proper subset to rewrite, listed {} file(s)",
            files.len()
        );

        // Author the source snapshot's manifest and seed a stats-cache row so the
        // precondition is a populated old snapshot; the fix must delete both.
        provider.rebuild_live_snapshot_manifests().await;
        let table_id = provider.table_metadata.table_id.clone();
        provider
            .catalog
            .upsert_snapshot_file_statistics(&crate::metadata::SnapshotFileStatistics {
                table_id: table_id.clone(),
                snapshot_id: source_snapshot_id.clone(),
                file_path: files[0].0.clone(),
                file_size_bytes: i64::try_from(files[0].1).unwrap_or(i64::MAX),
                num_rows: 50,
                statistics_blob: Vec::new(),
            })
            .await
            .expect("seed source stats-cache row");

        assert!(
            !provider
                .catalog
                .get_snapshot_files(&table_id, &source_snapshot_id)
                .await
                .expect("read source manifest")
                .is_empty(),
            "precondition: the source snapshot must have manifest rows before the rewrite"
        );
        assert!(
            provider
                .catalog
                .get_snapshot_file_statistics(&table_id, &source_snapshot_id, &files[0].0)
                .await
                .expect("read source stats cache")
                .is_some(),
            "precondition: the source snapshot must have a stats-cache row before the rewrite"
        );

        let candidate = subset_candidate_of_first_two(&files);
        assert!(
            provider.can_subset_rewrite_current_small_files(&candidate, &files),
            "fixture must land on the subset path"
        );

        let committed = provider
            .rewrite_current_snapshot_small_file_subset(
                &candidate,
                &files,
                &source_snapshot_id,
                generation_before,
            )
            .await
            .expect("subset rewrite succeeds");
        assert!(committed, "the subset rewrite must commit");

        let new_snapshot_id = provider.get_current_snapshot_id();
        assert_ne!(
            new_snapshot_id, source_snapshot_id,
            "a committed subset rewrite must publish a new snapshot"
        );

        // The leak this fix closes: the old current snapshot's catalog rows must
        // be gone after the commit.
        assert!(
            provider
                .catalog
                .get_snapshot_files(&table_id, &source_snapshot_id)
                .await
                .expect("read source manifest after commit")
                .is_empty(),
            "the source snapshot's manifest rows must be deleted at the subset commit"
        );
        assert!(
            provider
                .catalog
                .get_snapshot_file_statistics(&table_id, &source_snapshot_id, &files[0].0)
                .await
                .expect("read source stats cache after commit")
                .is_none(),
            "the source snapshot's stats-cache rows must be deleted at the subset commit"
        );

        // The new snapshot keeps its freshly authored manifest rows.
        assert!(
            !provider
                .catalog
                .get_snapshot_files(&table_id, &new_snapshot_id)
                .await
                .expect("read new manifest after commit")
                .is_empty(),
            "the new snapshot must keep its authored manifest rows"
        );
    }

    #[test]
    fn subset_write_amp_x100_is_total_over_candidate_percent() {
        // Full rewrite of 10 MiB when candidate is 1 MiB → 1000% amp (10×).
        assert_eq!(subset_write_amp_x100(10 * 1024 * 1024, 1024 * 1024), 1000);
        // Equal sizes → 100 (1×, no amp).
        assert_eq!(subset_write_amp_x100(500, 500), 100);
        // Defensive: zero candidate → 0 (no panic).
        assert_eq!(subset_write_amp_x100(1_000, 0), 0);
        // Zero total is a no-op rewrite ratio of 0.
        assert_eq!(subset_write_amp_x100(0, 100), 0);
    }

    #[test]
    fn protected_snapshot_size_tier_classifies_by_geometric_ceilings() {
        let base = 8 * 1024 * 1024; // 8 MiB
        let growth = 8;

        // Tier 0: everything at or below the base ceiling.
        assert_eq!(protected_snapshot_size_tier(0, base, growth), 0);
        assert_eq!(protected_snapshot_size_tier(1, base, growth), 0);
        assert_eq!(protected_snapshot_size_tier(base, base, growth), 0);

        // Just over the base ceiling rolls into tier 1.
        assert_eq!(protected_snapshot_size_tier(base + 1, base, growth), 1);
        assert_eq!(protected_snapshot_size_tier(base * growth, base, growth), 1);

        // Just over tier 1's ceiling rolls into tier 2.
        assert_eq!(
            protected_snapshot_size_tier(base * growth + 1, base, growth),
            2
        );
        assert_eq!(
            protected_snapshot_size_tier(base * growth * growth, base, growth),
            2
        );
    }

    #[test]
    fn protected_snapshot_size_tier_handles_degenerate_growth() {
        let base = 8 * 1024 * 1024;
        // growth <= 1 cannot form ceilings: everything collapses to tier 0.
        assert_eq!(protected_snapshot_size_tier(base * 100, base, 1), 0);
        assert_eq!(protected_snapshot_size_tier(base * 100, base, 0), 0);
    }

    #[test]
    fn protected_snapshot_size_tier_saturates_on_overflow() {
        // A near-u64::MAX input must not panic; it maps to the top tier.
        let tier = protected_snapshot_size_tier(u64::MAX, 1, 2);
        assert!(tier >= 63, "expected a high tier, got {tier}");
    }

    fn sized(id: &str, bytes: u64) -> (String, i64, u64) {
        (id.to_string(), 0, bytes)
    }

    #[test]
    fn select_merge_tier_picks_lowest_tier_with_enough_runs() {
        let base = 8 * 1024 * 1024;
        let growth = 8;
        // Two tier-0 runs (small) and two tier-1 runs (large). With min_runs=2
        // the LOWEST qualifying tier (tier 0) is selected.
        let inputs = vec![
            sized("a", 1024),     // tier 0
            sized("b", 2048),     // tier 0
            sized("c", base * 4), // tier 1
            sized("d", base * 5), // tier 1
        ];
        let selected =
            select_protected_snapshot_merge_tier(&inputs, 2, 32, base, growth, None).into_inputs();
        let ids: Vec<&str> = selected.iter().map(|(id, _)| id.as_str()).collect();
        assert_eq!(ids, vec!["a", "b"]);
    }

    #[test]
    fn select_merge_tier_returns_empty_when_no_tier_qualifies() {
        let base = 8 * 1024 * 1024;
        let growth = 8;
        // One run per tier — no tier reaches min_runs = 2.
        let inputs = vec![sized("a", 1024), sized("b", base * 4)];
        assert_eq!(
            select_protected_snapshot_merge_tier(&inputs, 2, 32, base, growth, None),
            ProtectedMergeSelection::NoQualifyingTier
        );
    }

    #[test]
    fn select_merge_tier_respects_max_width_and_keeps_oldest_first() {
        let base = 8 * 1024 * 1024;
        let growth = 8;
        // Four tier-0 runs; max_width = 2 caps the merge to the two oldest.
        let inputs = vec![
            sized("a", 100),
            sized("b", 200),
            sized("c", 300),
            sized("d", 400),
        ];
        let selected =
            select_protected_snapshot_merge_tier(&inputs, 2, 2, base, growth, None).into_inputs();
        let ids: Vec<&str> = selected.iter().map(|(id, _)| id.as_str()).collect();
        assert_eq!(ids, vec!["a", "b"]);
    }

    #[test]
    fn select_merge_tier_rejects_degenerate_inputs() {
        let base = 8 * 1024 * 1024;
        let growth = 8;
        // Fewer than two inputs, or a sub-2 floor, can never merge.
        assert_eq!(
            select_protected_snapshot_merge_tier(&[sized("a", 1)], 2, 32, base, growth, None),
            ProtectedMergeSelection::NoQualifyingTier
        );
        assert_eq!(
            select_protected_snapshot_merge_tier(
                &[sized("a", 1), sized("b", 2)],
                1,
                32,
                base,
                growth,
                None
            ),
            ProtectedMergeSelection::NoQualifyingTier
        );
    }

    #[test]
    fn select_merge_tier_takes_only_the_runs_that_fit_the_pass_budget() {
        // Regression test for #12013: eight same-tier 1 GiB runs were unioned in one
        // pass, OOM-killing a small-RAM host. A 3 GiB budget takes the three oldest;
        // later passes consolidate the rest.
        let base = 8 * 1024 * 1024;
        let growth = 8;
        let gib = 1024 * 1024 * 1024;
        let inputs: Vec<(String, i64, u64)> = (0..8)
            .map(|i| sized(&format!("s{i}"), gib))
            .collect::<Vec<_>>();

        let selected =
            select_protected_snapshot_merge_tier(&inputs, 2, 32, base, growth, Some(3 * gib))
                .into_inputs();
        let ids: Vec<&str> = selected.iter().map(|(id, _)| id.as_str()).collect();
        assert_eq!(ids, vec!["s0", "s1", "s2"], "oldest-first, budget-bounded");

        // An unbounded pool keeps the prior behavior: the whole tier, up to max_width.
        let unbounded = select_protected_snapshot_merge_tier(&inputs, 2, 32, base, growth, None)
            .into_inputs()
            .len();
        assert_eq!(unbounded, 8);
    }

    #[test]
    fn select_merge_tier_declines_when_two_runs_cannot_fit_the_pass_budget() {
        // A tier whose runs are too large to pair within the budget is settled: one
        // run is not a merge, and every higher tier is larger, so the pass declines.
        let base = 8 * 1024 * 1024;
        let growth = 8;
        let gib = 1024 * 1024 * 1024;
        let inputs: Vec<(String, i64, u64)> = (0..4)
            .map(|i| sized(&format!("s{i}"), 4 * gib))
            .collect::<Vec<_>>();

        // Reported as a budget stall rather than "nothing accumulated", so the caller
        // can escalate the read amplification it implies.
        assert_eq!(
            select_protected_snapshot_merge_tier(&inputs, 2, 32, base, growth, Some(6 * gib)),
            ProtectedMergeSelection::OverPassBudget {
                tier_runs: 4,
                oldest_pair_bytes: 8 * gib,
            }
        );
        // Exactly two fitting is enough to make progress.
        let pair =
            select_protected_snapshot_merge_tier(&inputs, 2, 32, base, growth, Some(8 * gib))
                .into_inputs();
        let ids: Vec<&str> = pair.iter().map(|(id, _)| id.as_str()).collect();
        assert_eq!(ids, vec!["s0", "s1"]);
    }

    #[test]
    fn select_merge_tier_reports_the_oldest_pair_not_the_smallest() {
        // A tier spans a byte range, so the oldest pair can be larger than a later
        // pair. The walk is oldest-first and declines rather than hunting for a
        // fitting pair (see `OverPassBudget`); the reported bytes are the oldest pair,
        // which is what the skip log must quote.
        let base = 8 * 1024 * 1024;
        let growth = 8;
        let gib = 1024 * 1024 * 1024;
        // All tier 3 (> 8 MiB * 8^2 = 512 MiB): 4 GiB, 4 GiB, then two 1 GiB runs.
        let inputs = vec![
            sized("old_a", 4 * gib),
            sized("old_b", 4 * gib),
            sized("new_a", gib),
            sized("new_b", gib),
        ];
        assert_eq!(
            select_protected_snapshot_merge_tier(&inputs, 2, 32, base, growth, Some(3 * gib)),
            ProtectedMergeSelection::OverPassBudget {
                tier_runs: 4,
                oldest_pair_bytes: 8 * gib,
            },
            "the two 1 GiB runs would fit, but the walk is oldest-first by design"
        );
    }

    #[test]
    fn protected_merge_input_budget_scales_with_the_pool_and_is_none_when_unbounded() {
        use datafusion::execution::memory_pool::MemoryLimit;

        assert_eq!(
            protected_merge_input_budget_for_pool(&MemoryLimit::Finite(1_000)),
            Some(1_000 * PROTECTED_MERGE_INPUT_BYTES_PER_POOL_BYTE)
        );
        // An unbounded/unknown pool has no ceiling to derive a budget from, so
        // selection stays unbounded — never clamped to zero.
        assert_eq!(
            protected_merge_input_budget_for_pool(&MemoryLimit::Infinite),
            None
        );
        assert_eq!(
            protected_merge_input_budget_for_pool(&MemoryLimit::Unknown),
            None
        );
        // A pool near usize::MAX must saturate, not wrap.
        assert_eq!(
            protected_merge_input_budget_for_pool(&MemoryLimit::Finite(usize::MAX)),
            Some(u64::MAX)
        );
    }

