    /// Waits, holding the caller's compaction lock, for the detached post-write
    /// compaction pass to reach that lock, find it held, and exit.
    ///
    /// `flush_pending_maintenance` drains the maintenance lane but only
    /// *schedules* this pass, and the task opens with a yield — so it can first
    /// reach for the lock after the caller releases it and consume the tier the
    /// caller is arranging. `drain_in_flight_maintenance` cannot be used here:
    /// it ends by taking the same lock.
    ///
    /// The flag is set before the task spawns and cleared on any exit, so once
    /// it reads false with the lock still held, no scheduled pass remains.
    async fn park_post_write_compaction(provider: &CayenneTableProvider) {
        for _ in 0..1_000 {
            if !provider
                .post_write_compaction_scheduled
                .load(std::sync::atomic::Ordering::Acquire)
            {
                return;
            }
            tokio::time::sleep(std::time::Duration::from_millis(1)).await;
        }
        panic!(
            "the detached post-write compaction pass never parked; it would race the \
             assertions below for the protected tier"
        );
    }

    /// Brings a freshly-written table to the state the budget assertions below
    /// describe: every insert registered as a protected snapshot, and no pending
    /// mem-tier delete left to cap the merge fence.
    ///
    /// Both matter because `compact_protected_snapshots_subset` has two
    /// independent reasons to decline. Without this, a pass that declined
    /// because the fence excluded every input looks exactly like one that
    /// declined on the pass budget — which makes the finite case pass
    /// vacuously and the unbounded control fail outright, since a CDC upsert
    /// stamps each snapshot with a delete sequence above the durable max until
    /// a checkpoint folds it down.
    ///
    /// Returns the settled protected-snapshot count.
    async fn settle_protected_tier(provider: &CayenneTableProvider, min_runs: usize) -> usize {
        // Protected-snapshot registration can lag the awaited insert under
        // parallel test load (see `subset_compaction_excludes_inputs_above_delete_fence`).
        let mut count = 0;
        for _ in 0..100 {
            count = provider.protected_snapshots.load_full().len();
            if count >= min_runs {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }

        // Fold the upserts' still-pending deletes into the durable index so the
        // fence stops capping below every snapshot's threshold. Left pending,
        // the eligibility filter drops all of them and the pass declines for a
        // reason these assertions do not mean to exercise.
        if provider.min_pending_mem_tier_delete_sequence().is_some() {
            provider
                .checkpoint_mem_tier()
                .await
                .expect("checkpoint the mem tier so no pending delete caps the fence");
        }
        assert_eq!(
            provider.min_pending_mem_tier_delete_sequence(),
            None,
            "precondition: a pending mem-tier delete would cap the merge fence below \
             every snapshot threshold, so the pass would decline on the fence rather \
             than on the pass budget"
        );

        count
    }

    /// End-to-end regression for #12013 on the real compaction path: under a finite
    /// pool the subset merge must decline a tier whose runs cannot be paired within
    /// the per-pass budget, instead of unioning up to
    /// [`PROTECTED_MERGE_MAX_WIDTH`] of them and driving the host OOM. The
    /// unbounded-pool control shows the bound is gated on a finite pool.
    ///
    /// The only size assumption is that the budget sits below the two smallest runs,
    /// checked as a precondition against the real on-disk sizes. Smallest, not oldest
    /// (which is what selection takes and the WARN reports): the smallest pair is the
    /// minimum possible pair sum, so exceeding the budget proves no pair can fit.
    #[tokio::test]
    async fn subset_compaction_declines_when_no_two_runs_fit_the_pass_memory_budget() {
        use arrow::datatypes::{DataType, Field, Schema};
        use datafusion::execution::memory_pool::GreedyMemoryPool;
        use datafusion_execution::runtime_env::RuntimeEnvBuilder;

        // 4× this is the per-pass budget: far below one Vortex snapshot, so no pair
        // of runs can fit. The precondition below checks that against real sizes.
        const POOL_BYTES: usize = 512;
        const TRIGGER: usize = 4;
        const ROWS: i64 = 6;

        let config = || VortexConfig {
            // File-backed protected snapshots (not absorbed by the inline memtable).
            inline_max_rows: 0,
            compaction_trigger_protected_snapshots: TRIGGER,
            // Only our explicit call runs; never race the background tick.
            compaction_background_interval_ms: 3_600_000,
            ..VortexConfig::default()
        };
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let expected: Vec<(i64, i64)> = (0..ROWS).map(|i| (i, i * 10)).collect();

        // Finite pool: the per-pass budget binds and the merge declines.
        let finite_rt = Arc::new(
            RuntimeEnvBuilder::new()
                .with_memory_pool(Arc::new(GreedyMemoryPool::new(POOL_BYTES)))
                .build()
                .expect("finite-pool runtime env"),
        );
        let (finite, _catalog, _tmp) =
            create_cdc_upsert_table_with_vortex_config("subset_budget_finite", finite_rt, config())
                .await;
        // Six one-row upserts publish six small, same-tier protected snapshots.
        // Hold the compaction lock across them so the debounced post-write pass
        // cannot merge the tier this test is arranging (same rationale as
        // `subset_compaction_excludes_inputs_above_delete_fence`) — a tier it
        // already consolidated has nothing left for the assertions below to
        // decline or merge.
        {
            let setup_guard = finite.compaction_lock.lock().await;
            for i in 0..ROWS {
                insert_batch(
                    &finite,
                    id_value_batch(Arc::clone(&schema), &[i], &[i * 10]),
                )
                .await;
            }
            finite
                .flush_pending_maintenance()
                .await
                .expect("drain pending post-write maintenance");
            park_post_write_compaction(&finite).await;
            drop(setup_guard);
        }

        let before = settle_protected_tier(&finite, TRIGGER).await;
        assert!(
            before >= TRIGGER,
            "precondition: need >= {TRIGGER} protected snapshots to arm the tier, got {before}"
        );

        // Precondition: the budget sits below the two smallest runs, so a declining
        // pass is the budget's doing and not an unarmed tier.
        let budget = finite
            .protected_merge_input_budget_bytes()
            .expect("a finite pool must yield a budget");
        let mut sizes: Vec<u64> = Vec::new();
        for id in finite.protected_snapshots.load_full().keys() {
            let bytes = finite
                .list_snapshot_files_with_sizes(id)
                .await
                .expect("list snapshot files")
                .iter()
                .map(|(_, sz)| *sz)
                .sum();
            sizes.push(bytes);
        }
        sizes.sort_unstable();
        let two_smallest: u64 = sizes.iter().take(2).sum();
        assert!(
            two_smallest > budget,
            "precondition: the two smallest runs ({two_smallest} B) must exceed the \
             {budget} B pass budget; lower POOL_BYTES"
        );

        let merged = finite
            .compact_protected_snapshots_subset(usize::MAX)
            .await
            .expect("a declined pass is a no-op, never an error");
        assert!(
            !merged,
            "the pass must decline: no two runs fit the {budget} B budget"
        );
        assert_eq!(
            finite.protected_snapshots.load_full().len(),
            before,
            "a declined pass must leave the protected set untouched"
        );
        let finite_ctx = SessionContext::new();
        assert_eq!(
            collect_id_value_pairs(&finite_ctx, &finite, "subset_budget_finite").await,
            expected,
            "declining must never lose rows"
        );

        // Unbounded-pool control: no ceiling to derive a budget from, so the tier
        // merges as it did before the fix.
        let unbounded_ctx = SessionContext::new();
        let (unbounded, _catalog2, _tmp2) = create_cdc_upsert_table_with_vortex_config(
            "subset_budget_unbounded",
            unbounded_ctx.runtime_env(),
            config(),
        )
        .await;
        {
            let setup_guard = unbounded.compaction_lock.lock().await;
            for i in 0..ROWS {
                insert_batch(
                    &unbounded,
                    id_value_batch(Arc::clone(&schema), &[i], &[i * 10]),
                )
                .await;
            }
            unbounded
                .flush_pending_maintenance()
                .await
                .expect("drain pending post-write maintenance");
            park_post_write_compaction(&unbounded).await;
            drop(setup_guard);
        }
        let unbounded_before = settle_protected_tier(&unbounded, TRIGGER).await;
        assert!(
            unbounded_before >= TRIGGER,
            "precondition: the control needs >= {TRIGGER} protected snapshots to arm the \
             tier, got {unbounded_before}"
        );
        assert_eq!(
            unbounded.protected_merge_input_budget_bytes(),
            None,
            "an unbounded pool must leave selection unbounded"
        );
        assert!(
            unbounded
                .compact_protected_snapshots_subset(usize::MAX)
                .await
                .expect("control compaction should not error"),
            "the same tier must still merge on an unbounded pool"
        );
        assert_eq!(
            collect_id_value_pairs(&unbounded_ctx, &unbounded, "subset_budget_unbounded").await,
            expected,
            "the control merge must preserve all rows"
        );
    }

    /// End-to-end coverage for the fast protected-snapshot compaction
    /// (`compact_protected_snapshots_subset`). The other tests cover only the
    /// pure tier-selection math; this exercises the real rewrite + CAS swap +
    /// in-memory reconciliation. It builds more than the trigger floor of small
    /// (tier-0) protected snapshots via upsert-table inserts, runs the subset
    /// compaction, and asserts it (a) merges — reducing the protected-snapshot
    /// count, (b) preserves every visible row, and (c) leaves the merged
    /// snapshot's in-memory threshold equal to its persisted sequence number
    /// (reload-stable: the partial-deletion filter must behave identically
    /// before and after a restart).
    #[tokio::test]
    async fn protected_snapshot_subset_compaction_merges_and_preserves_rows() {
        use arrow::datatypes::{DataType, Field, Schema};

        const TRIGGER: usize = 4;
        let ctx = SessionContext::new();

        let temp_dir = tempfile::tempdir().expect("temp dir");
        let metadata_dir = format!("{}/metadata", temp_dir.path().to_str().expect("str path"));
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("str path"));
        std::fs::create_dir_all(&metadata_dir).expect("metadata dir created");
        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let options = CreateTableOptions {
            table_name: "compact_subset".to_string(),
            schema: Arc::clone(&schema),
            primary_key: vec!["id".to_string()],
            on_conflict: Some(OnConflict::Upsert(
                datafusion_table_providers::util::column_reference::ColumnReference::new(vec![
                    "id".to_string(),
                ]),
            )),
            base_path: data_dir,
            partition_column: None,
            vortex_config: VortexConfig {
                // Disable the inline memtable so each upsert-table write lands in
                // a file-backed protected snapshot (the compaction's domain)
                // instead of being absorbed inline.
                inline_max_rows: 0,
                // Deterministic, low trigger floor so a handful of snapshots merge.
                compaction_trigger_protected_snapshots: TRIGGER,
                // Pin the background compactor far out so only our explicit call
                // runs — the test must not race the 30s background tick.
                compaction_background_interval_ms: 3_600_000,
                ..VortexConfig::default()
            },
        };
        let provider = CayenneTableProviderBuilder::new(Arc::clone(&catalog), ctx.runtime_env())
            .create(options)
            .await
            .expect("table created");

        let compaction_setup_guard = provider.compaction_lock.lock().await;

        // Each insert into an upsert table publishes a new protected snapshot.
        // Create more than the trigger floor of small (tier-0) snapshots.
        let n = i64::try_from(TRIGGER).expect("TRIGGER fits in i64") + 2;
        for i in 0..n {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[i], &[i * 10]),
            )
            .await;
        }

        let before = provider.protected_snapshots.load_full().len();
        assert!(
            before >= TRIGGER,
            "expected >= {TRIGGER} protected snapshots before compaction, got {before}"
        );

        let expected: Vec<(i64, i64)> = (0..n).map(|i| (i, i * 10)).collect();
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "compact_subset").await,
            expected,
            "sanity: all inserted rows visible before compaction"
        );

        drop(compaction_setup_guard);

        let merged = provider
            .compact_protected_snapshots_subset(usize::MAX)
            .await
            .expect("compaction should not error");
        assert!(merged, "a tier with >= {TRIGGER} runs should have merged");

        // (a) Inputs replaced by a single merged snapshot → count drops.
        let after = provider.protected_snapshots.load_full().len();
        assert!(
            after < before,
            "compaction must reduce the protected-snapshot count: {before} -> {after}"
        );

        // (b) Every visible row preserved through the merge.
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "compact_subset").await,
            expected,
            "compaction must preserve all visible rows"
        );

        // (c) Reload-stable thresholds: every in-memory protected-snapshot
        // threshold must equal its persisted sequence number, or a scan would
        // return different rows before vs after a restart.
        let in_mem = provider.protected_snapshots.load_full();
        let persisted = catalog
            .get_all_snapshot_sequences(&provider.table_metadata.table_id)
            .await
            .expect("persisted snapshot sequences");
        for (id, threshold) in in_mem.iter() {
            assert_eq!(
                persisted.get(id),
                Some(threshold),
                "protected snapshot {id}: in-memory threshold {threshold} must equal persisted {:?}",
                persisted.get(id),
            );
        }
    }

    /// Build a position-delete CDC upsert table whose every insert publishes its
    /// own protected snapshot, with the background compactor pinned far out so
    /// only explicit calls run.
    async fn create_position_delete_protected_snapshot_table(
        table_name: &str,
        runtime_env: Arc<RuntimeEnv>,
    ) -> (CayenneTableProvider, Arc<dyn MetadataCatalog>, TempDir) {
        create_cdc_upsert_table_with_vortex_config(
            table_name,
            runtime_env,
            VortexConfig {
                deletion_mode: crate::metadata::DeletionMode::Position,
                // Disable the inline memtable so each write lands in a
                // file-backed protected snapshot.
                inline_max_rows: 0,
                compaction_background_interval_ms: 3_600_000,
                ..VortexConfig::default()
            },
        )
        .await
    }

    /// Publish one more protected snapshot and return its id — standing in for
    /// the mem-tier checkpoint that lands during a rewrite's off-lock re-encode.
    async fn publish_one_more_protected_snapshot(
        provider: &CayenneTableProvider,
        before: &std::collections::HashSet<String>,
        id: i64,
    ) -> String {
        let schema = provider.table_schema();
        insert_batch(provider, id_value_batch(schema, &[id], &[id * 10])).await;
        let mut added = provider
            .protected_snapshot_ids()
            .difference(before)
            .cloned()
            .collect::<Vec<_>>();
        assert_eq!(
            added.len(),
            1,
            "expected exactly one protected snapshot to be published"
        );
        added.pop().expect("the one added snapshot id")
    }

    /// Regression for issue #11477: a full rewrite's commit must not drop a
    /// protected snapshot its scan never folded in.
    ///
    /// A position-delete rewrite holds `write_lock` across the whole pass, which
    /// excludes writers — but NOT the mem-tier checkpoint, which takes
    /// `write_lock` only for its capture and publishes its protected snapshot
    /// under `listing_fence.write()` alone. Such a snapshot lands after the scan,
    /// so its rows are absent from the consolidated output; clearing its
    /// reference (durably via `cayenne_snapshot_sequence`, and in memory) loses
    /// those rows permanently, and the durable half survives a restart.
    ///
    /// This drives both commit halves with a `folded` set captured BEFORE a later
    /// snapshot is published — exactly the shape the rewrite produces when a
    /// checkpoint interleaves.
    #[tokio::test]
    async fn position_rewrite_commit_retains_a_snapshot_published_after_the_scan() {
        let ctx = SessionContext::new();
        let (provider, catalog, _tmp) = create_position_delete_protected_snapshot_table(
            "position_rewrite_late_snapshot",
            ctx.runtime_env(),
        )
        .await;
        let schema = provider.table_schema();

        // Protected snapshots visible to the rewrite's scan.
        for i in 0..2i64 {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[i], &[i * 10]),
            )
            .await;
        }
        let folded = provider.protected_snapshot_ids();
        assert!(
            !folded.is_empty(),
            "the scan must observe at least one protected snapshot"
        );

        let late = publish_one_more_protected_snapshot(&provider, &folded, 99).await;

        let new_snapshot_id = uuid::Uuid::now_v7().to_string();
        provider
            .commit_snapshot_rewrite(
                &new_snapshot_id,
                &RewriteScope::AllTombstonesFoldedSnapshots {
                    folded: folded.clone(),
                },
            )
            .await
            .expect("fenced compaction commit succeeds");
        provider.clear_deletion_caches_retaining_unfolded_snapshots(&folded);

        // Durable half: the late snapshot's sequence row must survive, or its
        // rows are gone after a restart.
        let persisted = catalog
            .get_all_snapshot_sequences(&provider.table_metadata.table_id)
            .await
            .expect("persisted snapshot sequences");
        assert!(
            persisted.contains_key(&late),
            "DATA LOSS: the protected snapshot published after the scan was cleared \
             from the catalog; persisted ids: {:?}",
            persisted.keys().collect::<Vec<_>>()
        );
        for id in &folded {
            assert!(
                !persisted.contains_key(id),
                "folded snapshot {id} was materialized by the rewrite and must be cleared"
            );
        }

        // In-memory half: same subset semantics, or scans stop reading its rows
        // until a restart reloads the catalog.
        let in_mem = provider.protected_snapshots.load_full();
        assert!(
            in_mem.contains_key(&late),
            "DATA LOSS: the protected snapshot published after the scan was cleared \
             from the in-memory map; retained ids: {:?}",
            in_mem.keys().collect::<Vec<_>>()
        );
        for id in &folded {
            assert!(
                !in_mem.contains_key(id),
                "folded snapshot {id} must be dropped from the in-memory map"
            );
        }
    }

    /// The contrast that makes the test above load-bearing: [`RewriteScope::All`]
    /// clears EVERY protected snapshot, including one published after the scan.
    ///
    /// That is the behaviour the position-delete arm used to have, and it is why
    /// `All` is only correct for a caller that guarantees no concurrent writer
    /// *and* no concurrent checkpoint (`sort_and_rewrite_data`). Pinning it here
    /// means routing the position arm back to `All` fails a test rather than
    /// silently losing rows again.
    #[tokio::test]
    async fn wholesale_rewrite_commit_drops_every_protected_snapshot() {
        let ctx = SessionContext::new();
        let (provider, catalog, _tmp) = create_position_delete_protected_snapshot_table(
            "wholesale_rewrite_clears_all",
            ctx.runtime_env(),
        )
        .await;
        let schema = provider.table_schema();

        insert_batch(&provider, id_value_batch(Arc::clone(&schema), &[0], &[0])).await;
        let scanned = provider.protected_snapshot_ids();
        let late = publish_one_more_protected_snapshot(&provider, &scanned, 99).await;

        let new_snapshot_id = uuid::Uuid::now_v7().to_string();
        provider
            .commit_snapshot_rewrite(&new_snapshot_id, &RewriteScope::All)
            .await
            .expect("wholesale compaction commit succeeds");
        provider.clear_all_deletion_caches();

        let persisted = catalog
            .get_all_snapshot_sequences(&provider.table_metadata.table_id)
            .await
            .expect("persisted snapshot sequences");
        assert!(
            persisted.is_empty(),
            "`All` clears every snapshot-sequence row, including {late}"
        );
        assert!(
            provider.protected_snapshots.load_full().is_empty(),
            "`All` clears the whole in-memory protected map"
        );
    }

    /// OVERWRITE-GUARD regression (issue #11823): an overwrite that commits
    /// between the subset-merge's catalog CAS and its fenced in-memory publish
    /// wipes the protected map (and, in production, the catalog rows);
    /// publishing the merged snapshot into the emptied map anyway would make
    /// scans read the whole pre-overwrite row set ALONGSIDE the overwrite's
    /// data — the silent over-count behind the #11823 correctness-gate failure.
    /// The pass must detect the snapshot flip, discard its output, and return
    /// `false`.
    /// A table with no cold tier must not pay a `cayenne_cold_tier_file` round trip
    /// for its keyset rebuild. The rebuild's `fold_cold` is true for every table that
    /// is not bloom-served — which includes every warm-only table — so the fenced
    /// cold-manifest resolve has to opt OUT on the tier being disabled rather than in.
    ///
    /// `cold_manifest` is the observable: [`CayenneTableProvider::cold_manifest_under_held_fence`]
    /// publishes into it on every read it performs, so a populated cache after an
    /// upsert (which rebuilds the keyset) is exactly the SELECT this asserts did not
    /// happen. Scoped to that resolve — the once-per-table `maybe_install_warm_pk_caches`
    /// probe lists the manifest directly and is unaffected either way.
    #[tokio::test]
    async fn warm_only_table_never_reads_the_cold_manifest() {
        use arrow::datatypes::{DataType, Field, Schema};

        let ctx = SessionContext::new();
        let (provider, _catalog, _tmp) = create_cdc_upsert_table_with_vortex_config(
            "warm_only_no_cold_read",
            ctx.runtime_env(),
            VortexConfig::default(),
        )
        .await;
        assert!(
            !provider.table_metadata.vortex_config.cold_tier_enabled(),
            "fixture must have no cold tier, or this asserts nothing"
        );
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));

        // Two upserts of the same key: the first builds the keyset, the second
        // exercises it, so the rebuild path has definitely run.
        for value in [10, 20] {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[1], &[value]),
            )
            .await;
        }
        assert_eq!(
            query_count_star(&ctx, &provider, "warm_only_no_cold_read").await,
            1,
            "the upsert collapsed both writes onto one key (the keyset rebuild ran)"
        );
        assert!(
            provider.cold_manifest.load().is_none(),
            "a warm-only table's keyset rebuild must not resolve (and therefore must \
             not read) the cold-tier manifest"
        );
    }

    #[tokio::test]
    async fn subset_compaction_discards_output_when_snapshot_replaced_mid_pass() {
        use arrow::datatypes::{DataType, Field, Schema};

        const TRIGGER: usize = 4;
        let ctx = SessionContext::new();
        let (provider, _catalog, _tmp) = create_cdc_upsert_table_with_vortex_config(
            "subset_mid_pass_overwrite",
            ctx.runtime_env(),
            VortexConfig {
                inline_max_rows: 0,
                compaction_trigger_protected_snapshots: TRIGGER,
                compaction_background_interval_ms: 3_600_000,
                ..VortexConfig::default()
            },
        )
        .await;
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));

        // Hold the compaction lock across setup so write-driven maintenance
        // lanes skip instead of merging the snapshots the test needs (see
        // `build_seq_prefix_fixture` for the full rationale).
        let compaction_setup_guard = provider.compaction_lock.lock().await;
        let n = i64::try_from(TRIGGER).expect("TRIGGER fits in i64") + 2;
        for i in 0..n {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[i], &[i * 10]),
            )
            .await;
        }
        provider
            .flush_pending_maintenance()
            .await
            .expect("drain pending post-write maintenance");
        assert!(
            provider.protected_snapshots.load_full().len() >= TRIGGER,
            "fixture must produce enough protected snapshots to merge"
        );
        drop(compaction_setup_guard);

        // The mid-pass overwrite publishes a fresh EMPTY snapshot (the dir must
        // exist for the listing swap): its in-memory flip empties the protected
        // map, clears the deletion caches, and rotates `current_snapshot_id` —
        // exactly the state the guard must not publish the merged output into.
        let overwrite_snapshot_id = uuid::Uuid::now_v7().to_string();
        std::fs::create_dir_all(provider.snapshot_dir_path_for(&overwrite_snapshot_id))
            .expect("create empty overwrite snapshot dir");
        let hook_fired = Arc::new(std::sync::atomic::AtomicBool::new(false));
        {
            let provider_in_hook = provider.clone_for_write();
            let overwrite_id = overwrite_snapshot_id.clone();
            let fired = Arc::clone(&hook_fired);
            *provider.test_pre_publish_hook.lock() = Some(Box::new(move || {
                Box::pin(async move {
                    provider_in_hook
                        .publish_overwrite_snapshot(&overwrite_id, None)
                        .await
                        .expect("mid-pass overwrite publish");
                    fired.store(true, Ordering::SeqCst);
                })
            }));
        }

        let merged = provider
            .compact_protected_snapshots_subset(usize::MAX)
            .await
            .expect("subset pass must not error when the guard fires");
        assert!(
            hook_fired.load(Ordering::SeqCst),
            "the pass must reach the post-CAS window (mid-pass hook consumed)"
        );
        assert!(
            !merged,
            "the guard must report no merge when the snapshot was replaced mid-pass"
        );

        // The merged snapshot must NOT be re-inserted into the overwrite-emptied
        // protected map, and the overwrite's snapshot flip must stand.
        assert!(
            provider.protected_snapshots.load_full().is_empty(),
            "guard must not publish the merged snapshot into the overwrite-emptied protected map"
        );
        assert_eq!(
            provider.get_current_snapshot_id(),
            overwrite_snapshot_id,
            "the overwrite's snapshot flip must stand"
        );
        // Resurrection check: only the overwrite's (empty) data is visible — a
        // broken guard would surface all pre-overwrite rows here.
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "subset_mid_pass_overwrite").await,
            Vec::<(i64, i64)>::new(),
            "no pre-overwrite rows may survive the mid-pass overwrite"
        );
    }

    /// Engagement test for the size-aware PARALLEL merge encode: a subset
    /// merge whose selected inputs exceed one target file must shard its
    /// output across multiple concurrently-encoded files (bounded by the
    /// write concurrency), while preserving every visible row. The sibling
    /// test above covers the floor: a merge smaller than one target file
    /// stays a single output file (read fan-out unchanged).
    #[tokio::test]
    async fn protected_snapshot_subset_compaction_parallelizes_large_merges() {
        use arrow::array::{Int64Array, StringArray};
        use arrow::datatypes::{DataType, Field, Schema};

        const TRIGGER: usize = 4;
        /// Rows per snapshot × ~4 KiB payload ≈ 800 KiB raw per snapshot; six
        /// snapshots ≈ 4.8 MiB raw. The shard gate sizes the fan-out from
        /// ON-DISK bytes (`list_snapshot_files_with_sizes`), so the payload is
        /// pseudo-random (near-incompressible — see [`entropy_payload`]) to
        /// keep on-disk ≈ raw, and the test still does not *assume* a
        /// compression ratio: it measures the merged inputs' on-disk total
        /// and asserts it clears two 1 MiB target files before relying on the
        /// widened path. (A repetitive payload compresses ~6:1 here, leaving
        /// the gate at one shard — the multi-file output would then come from
        /// serial file rolling and the test would pass without exercising the
        /// parallel path at all.)
        const ROWS_PER_SNAPSHOT: i64 = 200;
        const PAYLOAD_BYTES: usize = 4096;
        // Mirrors `target_vortex_file_size_mb: 1` in the fixture config.
        const TARGET_FILE_SIZE_BYTES: u64 = 1024 * 1024;

        let ctx = SessionContext::new();
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let metadata_dir = format!("{}/metadata", temp_dir.path().to_str().expect("str path"));
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("str path"));
        tokio::fs::create_dir_all(&metadata_dir)
            .await
            .expect("metadata dir created");
        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("payload", DataType::Utf8, false),
        ]));
        let options = CreateTableOptions {
            table_name: "compact_subset_parallel".to_string(),
            schema: Arc::clone(&schema),
            primary_key: vec!["id".to_string()],
            on_conflict: Some(OnConflict::Upsert(
                datafusion_table_providers::util::column_reference::ColumnReference::new(vec![
                    "id".to_string(),
                ]),
            )),
            base_path: data_dir.clone(),
            partition_column: None,
            vortex_config: VortexConfig {
                inline_max_rows: 0,
                // 1 MiB target files so the merged tier spans several of them.
                target_vortex_file_size_mb: 1,
                compaction_trigger_protected_snapshots: TRIGGER,
                compaction_background_interval_ms: 3_600_000,
                // The parallel-merge path requires a NON-position deletion
                // mode: the default (`auto`) resolves to `position` for PK
                // tables, which the gate deliberately keeps single-writer
                // (file-path-scoped tombstones). Pin `key` so this test
                // exercises the widened path; the sibling test below pins
                // that position-mode tables stay serial.
                deletion_mode: crate::metadata::DeletionMode::Key,
                ..VortexConfig::default()
            },
        };
        let provider = CayenneTableProviderBuilder::new(Arc::clone(&catalog), ctx.runtime_env())
            .create(options)
            .await
            .expect("table created");

        let compaction_setup_guard = provider.compaction_lock.lock().await;

        let snapshots = i64::try_from(TRIGGER).expect("TRIGGER fits in i64") + 2;
        let mut expected_rows: usize = 0;
        for snapshot in 0..snapshots {
            let start = snapshot * ROWS_PER_SNAPSHOT;
            let ids: Vec<i64> = (start..start + ROWS_PER_SNAPSHOT).collect();
            let payloads: Vec<String> = ids
                .iter()
                .map(|id| format!("{id:08}_{}", entropy_payload(*id, PAYLOAD_BYTES)))
                .collect();
            let batch = RecordBatch::try_new(
                Arc::clone(&schema),
                vec![
                    Arc::new(Int64Array::from(ids)),
                    Arc::new(StringArray::from(payloads)),
                ],
            )
            .expect("payload batch");
            expected_rows += batch.num_rows();
            insert_batch(&provider, batch).await;
        }

        let before: std::collections::HashSet<String> = provider
            .protected_snapshots
            .load_full()
            .keys()
            .cloned()
            .collect();
        assert!(
            before.len() >= TRIGGER,
            "expected >= {TRIGGER} protected snapshots before compaction"
        );
        // Record each input snapshot's ON-DISK size before compaction (the
        // inputs may be cleaned up after the merge). The shard gate sizes the
        // fan-out from these on-disk bytes, so the engagement precondition
        // below must be pinned against them — not the raw payload bytes.
        let mut on_disk_bytes: std::collections::HashMap<String, u64> =
            std::collections::HashMap::with_capacity(before.len());
        for id in &before {
            let dir = std::path::Path::new(&data_dir)
                .join(&provider.table_metadata.table_id)
                .join(id);
            on_disk_bytes.insert(id.clone(), sum_vortex_file_bytes(&dir).await);
        }
        drop(compaction_setup_guard);

        let merged = provider
            .compact_protected_snapshots_subset(usize::MAX)
            .await
            .expect("compaction should not error");
        assert!(merged, "a tier with >= {TRIGGER} runs should have merged");

        // Find the NEW merged snapshot and count its vortex shard files.
        let after = provider.protected_snapshots.load_full();
        let new_snapshot = after
            .keys()
            .find(|id| !before.contains(*id))
            .expect("the merge must publish a new protected snapshot")
            .clone();

        // Engagement precondition: the snapshots this merge consumed must
        // exceed two target files ON DISK, or `snapshot_shard_count`
        // (`floor(bytes / target_file_size)`, min 1) never earns a second
        // shard and the `shard_files > 1` assertion below tests nothing. If
        // a future encoding change compresses this fixture below the bar,
        // fail HERE with the cause instead of as a mysterious single-file
        // merge.
        let merged_input_bytes: u64 = before
            .iter()
            .filter(|id| !after.contains_key(id.as_str()))
            .map(|id| on_disk_bytes[id])
            .sum();
        assert!(
            merged_input_bytes > 2 * TARGET_FILE_SIZE_BYTES,
            "fixture precondition: merged inputs must exceed two 1 MiB target \
             files on disk to earn >1 encoder shard (got {merged_input_bytes} \
             bytes) — grow ROWS_PER_SNAPSHOT/PAYLOAD_BYTES or make the \
             payload less compressible"
        );
        let snapshot_dir = std::path::Path::new(&data_dir)
            .join(&provider.table_metadata.table_id)
            .join(&new_snapshot);
        // NOTE: >1 files alone does not prove PARALLEL encode (a serial
        // writer also rolls files past the target size) — the widened-shape
        // decision is pinned by the pure `subset_merge_write_shape` unit
        // test. This bounds the fan-out and smoke-tests the multi-file merge
        // output end-to-end.
        let shard_files = count_vortex_files(&snapshot_dir).await;
        assert!(
            shard_files > 1,
            "a merge spanning multiple target files must produce multiple \
             output files (got {shard_files})"
        );
        // Upper bound: at most DEFAULT_WRITE_CONCURRENCY shard writers, each
        // of which may additionally roll its stream at the target file size —
        // so the ceiling is shards + (input bytes ÷ target size) roll-overs.
        // Generous on purpose: it catches pathological per-batch/per-row file
        // explosion without re-deriving the writer's exact roll math.
        let max_expected_files = DEFAULT_WRITE_CONCURRENCY
            + usize::try_from(merged_input_bytes / TARGET_FILE_SIZE_BYTES)
                .expect("file-count bound fits usize");
        assert!(
            shard_files <= max_expected_files,
            "output file count must stay bounded by write concurrency plus \
             target-size roll-overs (got {shard_files} > {max_expected_files})"
        );

        // Every row survives the parallel merge — content, not just count:
        // collect the id column, sort, and compare against the exact expected
        // id set (a pathological regression could drop some ids and duplicate
        // others while keeping the total stable).
        let scan_ctx = SessionContext::new();
        let plan = provider
            .scan(&scan_ctx.state(), Some(&vec![0]), &[], None)
            .await
            .expect("scan plan");
        let batches = datafusion::physical_plan::collect(plan, scan_ctx.task_ctx())
            .await
            .expect("collect rows");
        let mut scanned_ids: Vec<i64> = Vec::with_capacity(expected_rows);
        for batch in &batches {
            let ids = batch
                .column(0)
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("id column");
            scanned_ids.extend(ids.values().iter().copied());
        }
        scanned_ids.sort_unstable();
        let expected_ids: Vec<i64> = (0..snapshots * ROWS_PER_SNAPSHOT).collect();
        assert_eq!(
            scanned_ids, expected_ids,
            "parallel merge must preserve exactly the inserted id set"
        );
    }

    /// Count `.vortex` files in a snapshot directory (async fs — keeps the
    /// tokio worker unblocked in async tests).
    async fn count_vortex_files(snapshot_dir: &std::path::Path) -> usize {
        let mut shard_files = 0_usize;
        let mut entries = tokio::fs::read_dir(snapshot_dir)
            .await
            .expect("read merged snapshot dir");
        while let Some(entry) = entries.next_entry().await.expect("dir entry") {
            if entry.path().extension().is_some_and(|ext| ext == "vortex") {
                shard_files += 1;
            }
        }
        shard_files
    }

    /// Deterministic pseudo-random payload (xorshift64 over a 64-symbol
    /// alphabet), near-incompressible so on-disk size tracks raw size — the
    /// subset-merge shard gate reads ON-DISK bytes, and a repetitive payload
    /// compresses far below the target-file threshold the tests must cross.
    /// Seeded per row id so payloads are unique and reproducible.
    fn entropy_payload(seed: i64, len: usize) -> String {
        const ALPHABET: &[u8; 64] =
            b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
        // Bit-preserving i64 -> u64; the splitmix-style multiply spreads
        // small sequential ids across the state space, `| 1` avoids the
        // xorshift zero fixed point.
        let mut state =
            u64::from_le_bytes(seed.to_le_bytes()).wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1;
        let mut out = String::with_capacity(len);
        while out.len() < len {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            for byte in state.to_le_bytes() {
                if out.len() >= len {
                    break;
                }
                out.push(char::from(ALPHABET[usize::from(byte & 63)]));
            }
        }
        out
    }

    /// Sum the on-disk bytes of `.vortex` files in a snapshot directory —
    /// the same quantity `list_snapshot_files_with_sizes` feeds the shard
    /// gate as `total_input_bytes`.
    async fn sum_vortex_file_bytes(snapshot_dir: &std::path::Path) -> u64 {
        let mut total = 0_u64;
        let mut entries = tokio::fs::read_dir(snapshot_dir)
            .await
            .expect("read snapshot dir");
        while let Some(entry) = entries.next_entry().await.expect("dir entry") {
            if entry.path().extension().is_some_and(|ext| ext == "vortex") {
                total += entry.metadata().await.expect("file metadata").len();
            }
        }
        total
    }

    /// Sibling of the parallel-merge engagement test: a PK table left on the
    /// DEFAULT deletion mode (`auto` resolves to `position`) must keep the
    /// serial single-file merge shape even when the tier spans multiple
    /// target files — position tombstones are file-path scoped and the
    /// rewrite's bake-in assumes one output sequence. Pins the
    /// `serialize_position_deletes || is_position_based()` gate.
    #[tokio::test]
    async fn protected_snapshot_subset_compaction_keeps_position_mode_serial() {
        use arrow::array::StringArray;
        use arrow::datatypes::{DataType, Field, Schema};

        const TRIGGER: usize = 4;
        const ROWS_PER_SNAPSHOT: i64 = 200;
        const PAYLOAD_BYTES: usize = 2048;

        let ctx = SessionContext::new();
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let metadata_dir = format!("{}/metadata", temp_dir.path().to_str().expect("str path"));
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("str path"));
        tokio::fs::create_dir_all(&metadata_dir)
            .await
            .expect("metadata dir created");
        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("payload", DataType::Utf8, false),
        ]));
        let options = CreateTableOptions {
            table_name: "compact_subset_position_serial".to_string(),
            schema: Arc::clone(&schema),
            primary_key: vec!["id".to_string()],
            on_conflict: Some(OnConflict::Upsert(
                datafusion_table_providers::util::column_reference::ColumnReference::new(vec![
                    "id".to_string(),
                ]),
            )),
            base_path: data_dir.clone(),
            partition_column: None,
            vortex_config: VortexConfig {
                inline_max_rows: 0,
                target_vortex_file_size_mb: 1,
                compaction_trigger_protected_snapshots: TRIGGER,
                compaction_background_interval_ms: 3_600_000,
                // Deliberately NOT overridden: default `auto` resolves to
                // `position` for this PK table — the case that must stay
                // serial.
                ..VortexConfig::default()
            },
        };
        let provider = CayenneTableProviderBuilder::new(Arc::clone(&catalog), ctx.runtime_env())
            .create(options)
            .await
            .expect("table created");
        assert!(
            provider.should_capture_positions(),
            "fixture must resolve to position mode or this test pins nothing"
        );

        let compaction_setup_guard = provider.compaction_lock.lock().await;
        let snapshots = i64::try_from(TRIGGER).expect("TRIGGER fits in i64") + 2;
        let mut expected_rows: usize = 0;
        for snapshot in 0..snapshots {
            let start = snapshot * ROWS_PER_SNAPSHOT;
            let ids: Vec<i64> = (start..start + ROWS_PER_SNAPSHOT).collect();
            let payloads: Vec<String> = ids
                .iter()
                .map(|id| format!("{id:08}_{}", "p".repeat(PAYLOAD_BYTES)))
                .collect();
            let batch = RecordBatch::try_new(
                Arc::clone(&schema),
                vec![
                    Arc::new(Int64Array::from(ids)),
                    Arc::new(StringArray::from(payloads)),
                ],
            )
            .expect("payload batch");
            expected_rows += batch.num_rows();
            insert_batch(&provider, batch).await;
        }
        let before: std::collections::HashSet<String> = provider
            .protected_snapshots
            .load_full()
            .keys()
            .cloned()
            .collect();
        drop(compaction_setup_guard);

        let merged = provider
            .compact_protected_snapshots_subset(usize::MAX)
            .await
            .expect("compaction should not error");
        assert!(merged, "a tier with >= {TRIGGER} runs should have merged");

        let after = provider.protected_snapshots.load_full();
        let new_snapshot = after
            .keys()
            .find(|id| !before.contains(*id))
            .expect("the merge must publish a new protected snapshot")
            .clone();
        let snapshot_dir = std::path::Path::new(&data_dir)
            .join(&provider.table_metadata.table_id)
            .join(&new_snapshot);
        // File count is NOT asserted == 1: even the serial writer rolls
        // multiple files when the merged output exceeds the target file size
        // (this payload does). The serial-shape decision itself is pinned by
        // the pure `subset_merge_write_shape` unit test; this test pins the
        // end-to-end correctness of a position-mode merge under the corrected
        // gate, with the count only bounded.
        let shard_files = count_vortex_files(&snapshot_dir).await;
        assert!(
            (1..=DEFAULT_WRITE_CONCURRENCY).contains(&shard_files),
            "position-mode merge output file count out of bounds: {shard_files}"
        );

        let scan_ctx = SessionContext::new();
        let plan = provider
            .scan(&scan_ctx.state(), Some(&vec![0]), &[], None)
            .await
            .expect("scan plan");
        let batches = datafusion::physical_plan::collect(plan, scan_ctx.task_ctx())
            .await
            .expect("collect rows");
        let scanned_rows: usize = batches.iter().map(RecordBatch::num_rows).sum();
        assert_eq!(
            scanned_rows, expected_rows,
            "position-mode merge must preserve every visible row"
        );
    }

    #[test]
    fn pk_deletion_snapshot_is_stable_after_cache_publish() {
        let deletion_snapshot =
            Arc::new(ArcSwap::from_pointee(RowConverterDeletionSnapshot::empty()));
        let strategy = PkDeletionStrategyWithCache::RowConverterBased {
            deletion_snapshot: Arc::clone(&deletion_snapshot),
            position_deletions: Arc::new(ArcSwap::from_pointee(PositionBitmap::new())),
        };

        deletion_snapshot.store(Arc::new(RowConverterDeletionSnapshot::from_index(
            KeyDeletionIndex::from_map(HashMap::from([(
                Box::<[u8]>::from([42_u8].as_slice()),
                1_i64,
            )])),
        )));

        let scan_snapshot = pk_deletion_snapshot_for_strategy(&strategy);
        assert!(scan_snapshot.has_deletions());

        deletion_snapshot.store(Arc::new(RowConverterDeletionSnapshot::from_index(
            KeyDeletionIndex::from_map(HashMap::from([(
                Box::<[u8]>::from([99_u8].as_slice()),
                2_i64,
            )])),
        )));

        let PkDeletionSnapshot::RowConverterBased { tombstones } = scan_snapshot else {
            panic!("expected row-converter deletion snapshot");
        };
        assert_eq!(
            tombstones.get(&[42_u8]).map(|t| t.delete_sequence),
            Some(1_i64)
        );
        assert_eq!(tombstones.get(&[99_u8]), None);
        assert_eq!(deletion_snapshot.load().tombstones.get(&[42_u8]), None);
        assert_eq!(
            deletion_snapshot
                .load()
                .tombstones
                .get(&[99_u8])
                .map(|t| t.delete_sequence),
            Some(2_i64)
        );
    }

    #[test]
    fn table_statistics_to_df_uses_persisted_vortex_stats() {
        let schema = Arc::new(arrow_schema::Schema::new(vec![arrow_schema::Field::new(
            "id",
            arrow_schema::DataType::Int64,
            true,
        )]));
        let column_stats = ColumnStatistics {
            null_count: datafusion_common::stats::Precision::Exact(1),
            min_value: datafusion_common::stats::Precision::Exact(ScalarValue::Int64(Some(10))),
            max_value: datafusion_common::stats::Precision::Exact(ScalarValue::Int64(Some(20))),
            sum_value: datafusion_common::stats::Precision::Absent,
            distinct_count: datafusion_common::stats::Precision::Absent,
            byte_size: datafusion_common::stats::Precision::Absent,
        };
        let stats_set = crate::stats::column_stats_to_stats_set(&column_stats);
        let file_stats = crate::stats::build_file_statistics(vec![stats_set], &schema);
        let statistics_blob =
            crate::stats::serialize_file_statistics(&file_stats).expect("stats should serialize");
        let table_stats = TableStatistics {
            table_id: "table_id".to_string(),
            statistics_blob,
            num_rows: 3,
            ndv_sketches: None,
            num_rows_exact: true,
        };

        let stats = CayenneTableProvider::table_statistics_to_df(&schema, &table_stats)
            .expect("table stats should deserialize");

        assert_eq!(
            stats.num_rows,
            datafusion_common::stats::Precision::Exact(3)
        );
        assert_eq!(stats.column_statistics[0].min_value, column_stats.min_value);
        assert_eq!(stats.column_statistics[0].max_value, column_stats.max_value);
        assert_eq!(
            stats.column_statistics[0].null_count,
            column_stats.null_count
        );
    }

