    #[tokio::test]
    async fn test_write_shard_format_uses_configured_write_concurrency_override() {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (mut provider, _temp_dir) = create_sorted_cayenne_table(
            "parallel_write_override",
            Arc::clone(&schema),
            vec![],
            ctx.runtime_env(),
        )
        .await;

        provider.context = CayenneContext::new(
            &VortexConfig {
                write_concurrency: Some(2),
                ..VortexConfig::default()
            },
            ctx.runtime_env(),
            "test",
        );

        // The explicit `write_concurrency` override wins over the default the
        // session's target-partition count would have produced, up to that
        // count as a ceiling (2 <= 4 here, so it is honored in full).
        // `estimated_bytes = None` ⇒ full fan-out, so it is unclamped by size.
        let tsb = provider.context.target_file_size_bytes();
        assert_eq!(
            provider.snapshot_shard_count(4, tsb, None, EncodeFanOut::Sized),
            2
        );
        assert_eq!(
            provider
                .write_shard_format(4, tsb, None, EncodeFanOut::Sized, None)
                .write_shard()
                .expect("override should enable write sharding")
                .write_concurrency,
            2
        );
    }

    /// `EncodeFanOut::Serial` forces one encoder however high
    /// `cayenne_write_concurrency` is set.
    ///
    /// The protected-snapshot merge needs this for position-delete tables: their
    /// tombstones are file-path scoped and the position bake-in assumes one
    /// output sequence. It cannot be expressed as a small partition hint, because
    /// an ordinary write inherits that hint from whatever session executes it.
    ///
    /// The fixture declares no sort columns on purpose: `snapshot_shard_count`
    /// returns 1 outright for a sorted table, which would mask the intent.
    #[tokio::test]
    async fn test_serial_fan_out_overrides_configured_write_concurrency() {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_cayenne_table_with_config(
            "serial_fan_out",
            Arc::clone(&schema),
            VortexConfig {
                write_concurrency: Some(8),
                ..VortexConfig::default()
            },
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let tsb = provider.context.target_file_size_bytes();
        // Both size-estimate shapes the merge can pass: `None` (its serial
        // position-delete shape) and a large estimate, which would otherwise earn
        // the full fan-out.
        let huge = Some(tsb as u64 * 64);
        for estimated in [None, huge] {
            assert_eq!(
                provider.snapshot_shard_count(8, tsb, estimated, EncodeFanOut::Serial),
                1,
                "Serial must override the configured write concurrency \
                 (estimated_bytes={estimated:?})"
            );
            assert!(
                provider
                    .write_shard_format(8, tsb, estimated, EncodeFanOut::Serial, None)
                    .write_shard()
                    .is_none(),
                "a Serial write must produce the unsharded base format \
                 (estimated_bytes={estimated:?})"
            );
        }
    }

    /// Bounds must tile the key domain, and must decline rather than produce a
    /// split that cannot spread rows.
    ///
    /// Declining is the safe direction: the caller then hashes, which is what
    /// every write did before range partitioning existed. A bad split would be
    /// worse than no split — duplicate bounds leave a shard no row can reach,
    /// and a degenerate range sends every row to one encoder while the write
    /// still pays for the fan-out.
    #[test]
    fn range_bounds_from_statistics_tiles_the_domain_or_declines() {
        use datafusion_common::stats::Precision;

        fn stats(min: Option<i64>, max: Option<i64>) -> Statistics {
            let mut column = datafusion_common::ColumnStatistics::new_unknown();
            if let Some(min) = min {
                column.min_value = Precision::Exact(ScalarValue::Int64(Some(min)));
            }
            if let Some(max) = max {
                column.max_value = Precision::Exact(ScalarValue::Int64(Some(max)));
            }
            let mut stats = Statistics::new_unknown(&Schema::new(vec![Field::new(
                "k",
                DataType::Int64,
                false,
            )]));
            stats.column_statistics = vec![column];
            stats
        }

        assert_eq!(
            range_bounds_from_statistics(&stats(Some(0), Some(100)), 0, 4),
            Some(vec![
                ScalarValue::Int64(Some(25)),
                ScalarValue::Int64(Some(50)),
                ScalarValue::Int64(Some(75)),
            ]),
            "four shards split an even domain at the quarter points"
        );

        assert!(
            range_bounds_from_statistics(&stats(Some(7), Some(7)), 0, 4).is_none(),
            "a single-valued column cannot be split, so hash instead"
        );
        assert!(
            range_bounds_from_statistics(&stats(Some(100), Some(0)), 0, 4).is_none(),
            "an inverted range is not trustworthy"
        );
        assert!(
            range_bounds_from_statistics(&stats(None, Some(100)), 0, 4).is_none(),
            "an absent statistic declines rather than guessing"
        );
        assert!(
            range_bounds_from_statistics(&stats(Some(0), Some(100)), 0, 1).is_none(),
            "one shard needs no bounds"
        );
        assert!(
            range_bounds_from_statistics(&stats(Some(0), Some(100)), 9, 4).is_none(),
            "a column index outside the statistics declines"
        );

        // A domain narrower than the shard count repeats cuts; the duplicates
        // collapse so no shard is left unreachable.
        let narrow = range_bounds_from_statistics(&stats(Some(0), Some(2)), 0, 8)
            .expect("a narrow but non-degenerate range still splits");
        let mut sorted = narrow.clone();
        sorted.dedup();
        assert_eq!(sorted, narrow, "bounds must be strictly ascending");
    }

    /// Build one merge input's statistics: the key range it covers and its rows.
    #[cfg(test)]
    fn band_stats(min: i64, max: i64, rows: usize) -> Arc<Statistics> {
        use datafusion_common::stats::Precision;

        let mut column = datafusion_common::ColumnStatistics::new_unknown();
        column.min_value = Precision::Exact(ScalarValue::Int64(Some(min)));
        column.max_value = Precision::Exact(ScalarValue::Int64(Some(max)));
        let mut stats =
            Statistics::new_unknown(&Schema::new(vec![Field::new("k", DataType::Int64, false)]));
        stats.column_statistics = vec![column];
        stats.num_rows = Precision::Exact(rows);
        Arc::new(stats)
    }

    /// Route `keys` through `bounds` the way the sink's range split does — a row
    /// lands on shard `i` when its key is greater than exactly `i` of them — and
    /// report the rows per shard.
    #[cfg(test)]
    fn route_to_shards(keys: &[i64], bounds: &[ScalarValue]) -> Vec<usize> {
        let cuts: Vec<i64> = bounds
            .iter()
            .map(|bound| match bound {
                ScalarValue::Int64(Some(value)) => *value,
                other => panic!("test bounds must be Int64, got {other:?}"),
            })
            .collect();
        let mut counts = vec![0_usize; cuts.len() + 1];
        for key in keys {
            let shard = cuts.iter().filter(|cut| key > cut).count();
            counts[shard] += 1;
        }
        counts
    }

    /// Every bound set the split produces must be usable: strictly ascending (a
    /// repeat leaves a shard no row can reach) and no wider than the shard count.
    #[cfg(test)]
    fn assert_bounds_are_sound(bounds: &[ScalarValue], shards: usize, context: &str) {
        assert!(
            bounds.len() < shards,
            "{context}: {} bounds address more than {shards} shards",
            bounds.len()
        );
        for pair in bounds.windows(2) {
            assert!(
                pair[0] < pair[1],
                "{context}: bounds must be strictly ascending, saw {:?} then {:?}",
                pair[0],
                pair[1]
            );
        }
    }

    /// An input holding a single hot key is a point, not a range, and its rows
    /// must still steer the cuts. Spreading a zero-width band over its own (zero)
    /// width would drop it entirely — and that shape is exactly the hot-key upsert
    /// this split exists to place, so dropping it would defeat the change on its
    /// own headline case.
    ///
    /// A point also cannot be divided: rows sharing one key must all reach one
    /// shard, so a point holding more than a shard's worth of mass costs the
    /// shards its duplicates would have cut.
    #[test]
    fn a_single_valued_input_contributes_its_rows_and_earns_its_own_boundary() {
        // 90% of the rows carry one key; the rest tile the domain in bands narrow
        // enough for the gate to trust them.
        let mut inputs = vec![band_stats(100, 100, 9_000)];
        inputs.extend((0..4).map(|index| band_stats(index * 50, index * 50 + 50, 250)));

        let bounds = range_bounds_from_histogram(&inputs, 0, 4)
            .expect("a point among narrow spans describes a distribution");
        assert_bounds_are_sound(&bounds, 4, "point mass");
        assert!(
            bounds.contains(&ScalarValue::Int64(Some(100))),
            "the hot key must earn a boundary of its own, got {bounds:?}"
        );

        // Every row still lands somewhere, and the rows sharing the hot key all
        // reach ONE shard — they carry the same key, so no split can divide them.
        let keys: Vec<i64> = (0_i64..200)
            .chain(std::iter::repeat_n(100, 9_000))
            .collect();
        let counts = route_to_shards(&keys, &bounds);
        assert_eq!(
            counts.iter().sum::<usize>(),
            keys.len(),
            "every row must land on exactly one shard"
        );
        assert!(
            counts.iter().any(|&count| count >= 9_000),
            "the 9,000 rows on the hot key cannot be divided, so one shard holds them all: {counts:?}"
        );
    }

    /// `Decimal128` admits bands wide enough to overflow an `i128` difference. The
    /// split must decline and let the caller fall back, never wrap into an
    /// inverted density or panic under overflow checks.
    #[test]
    fn an_unrepresentable_key_span_declines_instead_of_overflowing() {
        use datafusion_common::stats::Precision;

        fn decimal_stats(min: i128, max: i128, rows: Option<usize>) -> Statistics {
            let mut column = datafusion_common::ColumnStatistics::new_unknown();
            column.min_value = Precision::Exact(ScalarValue::Decimal128(Some(min), 38, 0));
            column.max_value = Precision::Exact(ScalarValue::Decimal128(Some(max), 38, 0));
            let mut stats = Statistics::new_unknown(&Schema::new(vec![Field::new(
                "k",
                DataType::Decimal128(38, 0),
                false,
            )]));
            stats.column_statistics = vec![column];
            if let Some(rows) = rows {
                stats.num_rows = Precision::Exact(rows);
            }
            stats
        }

        assert!(
            range_bounds_from_histogram(
                &[
                    Arc::new(decimal_stats(i128::MIN, i128::MAX, Some(1_000))),
                    Arc::new(decimal_stats(0, 1_000, Some(1_000))),
                ],
                0,
                4,
            )
            .is_none(),
            "a span that cannot be represented declines rather than wrapping"
        );
        assert!(
            range_bounds_from_statistics(&decimal_stats(i128::MIN, i128::MAX, None), 0, 4)
                .is_none(),
            "the range interpolation declines the same span"
        );
    }

    /// The shape the composite gate exists to refuse: a sparse leading column.
    ///
    /// `(tenant_id, sequence)` where `tenant_id` takes two values a million apart.
    /// Splitting on it can reach only two shards however many cuts are produced,
    /// while hashing the whole key spreads the varying `sequence` across every
    /// writer. Both ways the inputs can present that column must decline, and the
    /// bound COUNT is what carries the evidence in each: an equal-width guess over
    /// the outer range is not admitted at all, and the band walk cannot manufacture
    /// cuts where no rows are.
    #[test]
    fn a_sparse_composite_leading_column_declines_however_its_inputs_are_written() {
        const SHARDS: usize = 8;
        const FAR: i64 = 1_000_000;

        // (a) Hash-written inputs: every band reports the whole span, so there is
        // no occupancy information anywhere in the set. The walk declines on band
        // width, so the split is not offered histogram evidence at all.
        let hashed: Vec<Arc<Statistics>> = (0..8).map(|_| band_stats(1, FAR, 10_000)).collect();
        assert!(
            range_bounds_from_histogram(&hashed, 0, SHARDS).is_none(),
            "bands spanning the domain carry no distribution, so they decline"
        );
        // Equal-width over that range WOULD produce a full set of cuts — and this
        // is exactly the trap: the cuts exist, the rows to fill them do not.
        let equi_width = range_bounds_from_statistics(&hashed[0], 0, SHARDS)
            .expect("a wide range interpolates a full set of cuts");
        assert_eq!(equi_width.len(), SHARDS - 1);
        assert!(
            !range_split_is_worth_taking(equi_width.len(), SHARDS, true, false),
            "a full set of cuts over an empty range must not pass the composite gate"
        );

        // (b) Range-written inputs: each partition holds one tenant, so the bands
        // are points. They clear the width gate, but the walk can only cut where
        // mass is, so it yields one bound rather than seven.
        let clustered = vec![band_stats(1, 1, 50_000), band_stats(FAR, FAR, 50_000)];
        let bounds = range_bounds_from_histogram(&clustered, 0, SHARDS)
            .expect("two points still describe where the rows are");
        assert!(
            bounds.len() + 1 < SHARDS,
            "two occupied values cannot fill eight shards, got {bounds:?}"
        );
        assert!(
            !range_split_is_worth_taking(bounds.len(), SHARDS, true, true),
            "histogram evidence that reaches two shards must still decline"
        );

        // A single-column key keeps its shipped trade in the same situation:
        // clustering on the key it was chosen for beats scattering it.
        assert!(range_split_is_worth_taking(
            bounds.len(),
            SHARDS,
            false,
            true
        ));
    }

    /// A composite key takes its leading column only on evidence: bounds from the
    /// histogram, whose bands are gated narrow enough to reflect where rows
    /// actually are, and still filling every shard. An equal-width split over the
    /// raw range is not evidence — a leading column with five values spread across
    /// a wide domain yields a full set of cuts while the rows reach only five
    /// shards, where hashing the whole key would have used them all.
    #[test]
    fn a_composite_key_takes_its_leading_column_only_on_histogram_evidence() {
        // Composite key, bounds from the histogram, full split: take it.
        assert!(range_split_is_worth_taking(7, 8, true, true));

        // Composite key, full split, but the bounds are an equal-width guess over
        // the outer range: no occupancy evidence, so hash.
        assert!(
            !range_split_is_worth_taking(7, 8, true, false),
            "a wide range is not evidence of where the leading column's rows are"
        );

        // Composite key, histogram bounds, but too few cuts to fill the shards.
        assert!(
            !range_split_is_worth_taking(1, 8, true, true),
            "a leading column that reaches two of eight writers would idle six"
        );

        // A single-column key keeps the shipped trade either way: clustering on
        // the key it was chosen for, at the cost of some encode width.
        assert!(range_split_is_worth_taking(1, 8, false, false));
        assert!(range_split_is_worth_taking(7, 8, false, false));
        assert!(range_split_is_worth_taking(1, 8, false, true));
    }

    /// A flat density — every band spanning the whole domain, which is the shape
    /// hash-partitioned inputs have, since a hash scatters every key across every
    /// file — carries no distribution the equal-width split does not already have.
    ///
    /// It DELEGATES rather than re-deriving: equal mass over a flat density is the
    /// equal-width split, so declining hands the caller a result that is exactly
    /// right at any magnitude, where recomputing it through floating point would
    /// only introduce a way to be off by one.
    #[test]
    fn histogram_declines_a_flat_density_and_leaves_the_exact_split_to_equi_width() {
        let inputs: Vec<Arc<Statistics>> = (0..8).map(|_| band_stats(0, 1_000, 10_000)).collect();

        for shards in [2_usize, 4, 8, 16] {
            assert!(
                range_bounds_from_histogram(&inputs, 0, shards).is_none(),
                "a flat density adds nothing at {shards} shards, so it declines"
            );
            assert!(
                range_bounds_from_statistics(&inputs[0], 0, shards).is_some(),
                "and the caller's fallback still splits it"
            );
        }
    }

    /// A band says how many rows lie in a range, never where they sit inside it.
    /// Read as uniform, a band that is really two endpoint clusters sends
    /// equal-mass cuts into the empty middle — strictly worse than equal width.
    /// The band-width gate is what keeps that model from being trusted, so these
    /// are the shapes it must decline.
    ///
    /// Both cases are drawn from an adversarial review of the ungated version.
    #[test]
    fn histogram_declines_bands_too_wide_for_their_model_to_be_trusted() {
        // Endpoint-clustered bands. Uniform-model cuts would be [41,50,58] and
        // route [500,0,0,500]; equi-width's [25,50,75] routes [250,250,250,250].
        assert!(
            range_bounds_from_histogram(&[band_stats(0, 100, 500), band_stats(40, 60, 500)], 0, 4,)
                .is_none(),
            "a band spanning the whole domain cannot be modelled as uniform"
        );

        // Unequal deletion inflation. Three old snapshots report a million rows
        // each over a tenth of the domain that newer tombstones have removed; the
        // live snapshot spans the rest. Trusting the counts cuts at [3,6,9] and
        // routes [250_000,0,0,750_000].
        assert!(
            range_bounds_from_histogram(
                &[
                    band_stats(0, 10, 1_000_000),
                    band_stats(0, 10, 1_000_000),
                    band_stats(0, 10, 1_000_000),
                    band_stats(0, 100, 1_000_000),
                ],
                0,
                4,
            )
            .is_none(),
            "row-count error only cancels when it is shared, so wide bands decline"
        );

        // The gate admits bands narrower than one shard's share of the domain,
        // which is what a range-clustered input looks like.
        let clustered: Vec<Arc<Statistics>> = (0..16)
            .map(|index| band_stats(index * 100, index * 100 + 90, 1_000))
            .collect();
        assert!(
            range_bounds_from_histogram(&clustered, 0, 4).is_some(),
            "bands thinner than a shard are exactly the case the model is for"
        );
    }

    /// Once the inputs are range-clustered — narrow, disjoint bands, which is what
    /// this function's own output produces on the next merge — the histogram sees
    /// where the rows are and the equi-width interpolation does not.
    ///
    /// The distribution here is the CDC steady state: a hot-key upsert stream, so
    /// most rows sit in a small part of a wide key domain.
    #[test]
    #[expect(
        clippy::cast_precision_loss,
        reason = "the assertion is a ratio of row counts; f64 is exact far beyond \
                  the 100k rows this test routes"
    )]
    fn histogram_bounds_balance_a_skewed_key_that_equi_width_piles_onto_one_shard() {
        const SHARDS: usize = 8;

        // 90% of the rows live in the bottom tenth of the domain. Every band is
        // narrower than one shard's share (100_000), so the gate admits them.
        let mut inputs: Vec<Arc<Statistics>> = (0..36)
            .map(|index| band_stats(index * 25, index * 25 + 20, 2_500))
            .collect();
        inputs.extend(
            (0..12)
                .map(|index| band_stats(900 + index * 66_000, 900 + index * 66_000 + 60_000, 833)),
        );

        let keys: Vec<i64> = (0_i64..90_000)
            .map(|index| index % 900)
            .chain((0_i64..10_000).map(|index| 900 + index * 79))
            .collect();

        let histogram = range_bounds_from_histogram(&inputs, 0, SHARDS)
            .expect("narrow disjoint bands describe a distribution");
        assert_bounds_are_sound(&histogram, SHARDS, "histogram");

        let merged = band_stats(0, 900 + 9_999 * 79, 100_000);
        let equi_width = range_bounds_from_statistics(&merged, 0, SHARDS)
            .expect("the merged range splits by interpolation");
        assert_bounds_are_sound(&equi_width, SHARDS, "equi-width");

        let imbalance = |counts: &[usize]| {
            let ideal = keys.len() as f64 / SHARDS as f64;
            counts.iter().copied().max().unwrap_or(0) as f64 / ideal
        };
        let histogram_imbalance = imbalance(&route_to_shards(&keys, &histogram));
        let equi_width_imbalance = imbalance(&route_to_shards(&keys, &equi_width));

        assert!(
            equi_width_imbalance > 3.0,
            "equi-width is expected to pile this key onto one shard, saw {equi_width_imbalance:.2}x"
        );
        assert!(
            histogram_imbalance < equi_width_imbalance,
            "the histogram must improve on it, saw {histogram_imbalance:.2}x against \
             {equi_width_imbalance:.2}x"
        );
    }

    /// Routing must lose no row and must keep the shards in key order, whichever
    /// strategy produced the bounds — the split is a reordering of rows across
    /// files, never a filter.
    #[test]
    fn histogram_bounds_tile_the_domain_without_losing_rows() {
        const SHARDS: usize = 6;
        // Twelve bands of width 50 over [-500, 100): half a shard's share each.
        let inputs: Vec<Arc<Statistics>> = (0..12)
            .map(|index| {
                let lo = -500 + index * 50;
                band_stats(lo, lo + 50, if index % 3 == 0 { 3_000 } else { 500 })
            })
            .collect();
        let keys: Vec<i64> = (-500..100).collect();

        let bounds = range_bounds_from_histogram(&inputs, 0, SHARDS)
            .expect("narrow tiled bands describe a splittable distribution");
        assert_bounds_are_sound(&bounds, SHARDS, "histogram");

        let counts = route_to_shards(&keys, &bounds);
        assert_eq!(
            counts.iter().sum::<usize>(),
            keys.len(),
            "every row must land on exactly one shard"
        );
    }

    /// Inputs that cannot describe a distribution decline, so the caller falls
    /// back to the range interpolation and past that to hashing. Declining is
    /// always safe; a bad split is not.
    #[test]
    fn histogram_bounds_decline_when_the_inputs_describe_nothing() {
        use datafusion_common::stats::Precision;

        /// Bands narrow enough to clear the width gate, so these cases fail for
        /// the reason each one names rather than incidentally on band width.
        fn tiled(count: i64) -> Vec<Arc<Statistics>> {
            (0..count)
                .map(|index| band_stats(index * 10, index * 10 + 10, 10))
                .collect()
        }

        assert!(
            range_bounds_from_histogram(&[band_stats(0, 100, 10)], 0, 4).is_none(),
            "one input is only a range, which the interpolation already handles"
        );
        assert!(
            range_bounds_from_histogram(&tiled(4), 0, 1).is_none(),
            "one shard needs no bounds"
        );
        assert!(
            range_bounds_from_histogram(&[band_stats(7, 7, 10), band_stats(7, 7, 10)], 0, 4)
                .is_none(),
            "a single-valued domain cannot be split"
        );
        assert!(
            range_bounds_from_histogram(&tiled(4), 9, 4).is_none(),
            "a column index outside the statistics declines"
        );

        // An input whose row count is unknown declines the WHOLE histogram rather
        // than being skipped: skipping is arithmetically identical to calling it
        // empty, which drags every cut toward the inputs that did report.
        let mut unknown_rows =
            Statistics::new_unknown(&Schema::new(vec![Field::new("k", DataType::Int64, false)]));
        let mut column = datafusion_common::ColumnStatistics::new_unknown();
        column.min_value = Precision::Exact(ScalarValue::Int64(Some(0)));
        column.max_value = Precision::Exact(ScalarValue::Int64(Some(10)));
        unknown_rows.column_statistics = vec![column];
        let mut with_unknown = vec![Arc::new(unknown_rows)];
        with_unknown.extend(tiled(4));
        assert!(
            range_bounds_from_histogram(&with_unknown, 0, 4).is_none(),
            "one unreadable input declines the whole histogram, not just itself"
        );

        // Likewise an input that reports rows but no key range.
        let mut no_range =
            Statistics::new_unknown(&Schema::new(vec![Field::new("k", DataType::Int64, false)]));
        no_range.num_rows = Precision::Exact(500);
        no_range.column_statistics = vec![datafusion_common::ColumnStatistics::new_unknown()];
        let mut with_no_range = vec![Arc::new(no_range)];
        with_no_range.extend(tiled(4));
        assert!(
            range_bounds_from_histogram(&with_no_range, 0, 4).is_none(),
            "a non-empty input with no key range declines the whole histogram"
        );

        // An input that is genuinely EMPTY biases nothing, so it is passed over
        // and the remaining inputs still describe a distribution.
        let mut with_empty = vec![band_stats(0, 10, 0)];
        with_empty.extend(tiled(4));
        assert!(
            range_bounds_from_histogram(&with_empty, 0, 4).is_some(),
            "an empty input carries no mass, so it cannot bias the cuts"
        );
    }

    /// The interpolation covers every integer-backed key family, and rebuilds each
    /// bound carrying the column's own unit, timezone and scale — a bound that
    /// dropped them would not compare against the column it splits.
    #[test]
    fn range_bounds_carry_the_key_column_unit_timezone_and_scale() {
        use datafusion_common::stats::Precision;

        fn split(min: ScalarValue, max: ScalarValue) -> Option<Vec<ScalarValue>> {
            let mut column = datafusion_common::ColumnStatistics::new_unknown();
            column.min_value = Precision::Exact(min);
            column.max_value = Precision::Exact(max);
            let mut stats = Statistics::new_unknown(&Schema::new(vec![Field::new(
                "k",
                DataType::Int64,
                false,
            )]));
            stats.column_statistics = vec![column];
            range_bounds_from_statistics(&stats, 0, 2)
        }

        let utc: Option<Arc<str>> = Some(Arc::from("UTC"));
        assert_eq!(
            split(
                ScalarValue::TimestampMicrosecond(Some(0), utc.clone()),
                ScalarValue::TimestampMicrosecond(Some(2_000), utc.clone()),
            ),
            Some(vec![ScalarValue::TimestampMicrosecond(
                Some(1_000),
                utc.clone()
            )]),
            "a timestamp key splits and keeps its timezone"
        );
        assert_eq!(
            split(
                ScalarValue::Date64(Some(0)),
                ScalarValue::Date64(Some(1_000)),
            ),
            Some(vec![ScalarValue::Date64(Some(500))]),
            "a Date64 key splits, as Date32 already did"
        );
        assert_eq!(
            split(
                ScalarValue::Time64Nanosecond(Some(0)),
                ScalarValue::Time64Nanosecond(Some(400)),
            ),
            Some(vec![ScalarValue::Time64Nanosecond(Some(200))]),
            "a time-of-day key splits"
        );
        assert_eq!(
            split(
                ScalarValue::Decimal128(Some(0), 20, 4),
                ScalarValue::Decimal128(Some(1_000), 20, 4),
            ),
            Some(vec![ScalarValue::Decimal128(Some(500), 20, 4)]),
            "a decimal key splits and keeps its precision and scale"
        );

        // Ends from two different domains must not be interpolated across.
        assert!(
            !scalars_share_a_domain(
                &ScalarValue::Decimal128(Some(0), 20, 4),
                &ScalarValue::Decimal128(Some(1_000), 20, 2),
            ),
            "two scales are two different numbers"
        );
        assert!(
            !scalars_share_a_domain(
                &ScalarValue::TimestampMicrosecond(Some(0), utc),
                &ScalarValue::TimestampMicrosecond(Some(1_000), None),
            ),
            "two timezones are two different instants"
        );
        assert!(
            split(
                ScalarValue::Float64(Some(0.0)),
                ScalarValue::Float64(Some(100.0)),
            )
            .is_none(),
            "a float key is not interpolated; it hashes"
        );
    }

    /// A sorted rewrite must declare a serial fan-out; an unsorted one must not.
    ///
    /// This is the gate that keeps a globally sorted stream on one writer. If it
    /// ever returns a `Sized` policy for a sorted rewrite, the order is split
    /// across shard files and every file's zone maps span the whole range — the
    /// pruning the sort exists for is silently lost, with no failure anywhere.
    #[test]
    fn rewrite_write_policy_pins_the_fan_out_only_for_sorted_rewrites() {
        use crate::provider::delta_encoding::{WriteClass, WritePolicy};

        assert_eq!(
            rewrite_write_policy(true),
            WritePolicy::MAINTENANCE_SERIAL,
            "a sorted rewrite must pin the encode to one writer"
        );
        assert_eq!(
            rewrite_write_policy(true).fan_out,
            EncodeFanOut::Serial,
            "the pin must be the fan-out, not merely the write class"
        );
        assert_eq!(
            rewrite_write_policy(false),
            WritePolicy::MAINTENANCE,
            "an unsorted consolidation is free to fan out"
        );
        assert_eq!(rewrite_write_policy(false).fan_out, EncodeFanOut::Sized,);
        // Both are maintenance writes: only the fan-out differs, so the encoding
        // level and the encode-budget class stay the same either way.
        assert_eq!(rewrite_write_policy(true).class, WriteClass::Maintenance);
        assert_eq!(rewrite_write_policy(false).class, WriteClass::Maintenance);
    }

    /// Regression test: a sorted rewrite must stay serial even when the table
    /// raises `cayenne_write_concurrency`.
    ///
    /// `snapshot_write_concurrency` honors a configured concurrency ABOVE the
    /// caller's `session_target_partitions` (that hint bounds only the unset
    /// default), so the sorted rewrites cannot secure a single writer by passing
    /// `target_partitions = 1` — they must declare `EncodeFanOut::Serial`.
    /// Without that, a globally sorted stream is split across shard files and
    /// every file's zone maps span the whole range, silently forfeiting the
    /// pruning the sort exists for.
    #[tokio::test]
    async fn test_sorted_rewrite_stays_serial_under_write_concurrency_override() {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_cayenne_table_with_config(
            "sorted_rewrite_concurrency_override",
            Arc::clone(&schema),
            VortexConfig {
                write_concurrency: Some(8),
                sort_columns: vec!["id".to_string()],
                ..VortexConfig::default()
            },
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let tsb = provider.context.target_file_size_bytes();

        // The pin the sorted rewrites actually pass.
        assert_eq!(
            provider.snapshot_shard_count(1, tsb, None, EncodeFanOut::Serial),
            1,
            "a declared-serial write must ignore the configured write concurrency"
        );
        assert!(
            provider
                .write_shard_format(1, tsb, None, EncodeFanOut::Serial, None)
                .write_shard()
                .is_none(),
            "a declared-serial write must not carry a shard config"
        );

        // Demonstrates why the declaration is load-bearing: the hint alone does
        // not hold, so a sorted rewrite that only passed `1` would fan out.
        assert_eq!(
            provider.snapshot_shard_count(1, tsb, None, EncodeFanOut::Sized),
            8,
            "the partition hint alone does not bound a configured concurrency"
        );
    }

    /// A LOW partition hint must not serialize an ordinary write.
    ///
    /// The hint is inherited from whichever session is executing — a low
    /// `runtime.query.target_partitions`, or a cluster's executor-slot count — so
    /// treating it as a hard ceiling would silently disable a configured
    /// `cayenne_write_concurrency` on the CDC, DML, staged and overwrite paths.
    /// `write_to_snapshot` builds its own `SessionConfig::default()` session for
    /// the sink, so the sink would still have encoded at the configured width;
    /// only the accelerator's request would have collapsed.
    #[tokio::test]
    async fn test_low_partition_hint_does_not_serialize_a_sized_write() {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_cayenne_table_with_config(
            "low_partition_hint",
            Arc::clone(&schema),
            VortexConfig {
                write_concurrency: Some(8),
                ..VortexConfig::default()
            },
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let tsb = provider.context.target_file_size_bytes();
        assert_eq!(
            provider.snapshot_shard_count(1, tsb, None, EncodeFanOut::Sized),
            8,
            "a configured write concurrency must survive a low partition hint"
        );
        assert_eq!(
            provider
                .write_shard_format(1, tsb, None, EncodeFanOut::Sized, None)
                .write_shard()
                .expect("a sized write keeps its shard config")
                .write_concurrency,
            8
        );
    }

    #[tokio::test]
    async fn test_declared_sort_order_does_not_serialize_an_unsorted_write() {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_sorted_cayenne_table(
            "parallel_sorted_write",
            Arc::clone(&schema),
            vec!["id".to_string()],
            ctx.runtime_env(),
        )
        .await;

        // A sorted rewrite states its requirement with `EncodeFanOut::Serial`
        // and stays on a single writer, whatever the size estimate says.
        let tsb = provider.context.target_file_size_bytes();
        let huge = Some(tsb as u64 * 64);
        assert_eq!(
            provider.snapshot_shard_count(4, tsb, huge, EncodeFanOut::Serial),
            1
        );
        assert!(
            provider
                .write_shard_format(4, tsb, huge, EncodeFanOut::Serial, None)
                .write_shard()
                .is_none(),
            "a serial write falls back to the unsharded base format"
        );

        // The table DECLARING a sort order does not make every write it makes a
        // sorted one. Schema inference fills `sort_columns` on every
        // catalog-visible CDC table, so a table property here would serialize
        // the CDC delta write and the protected-snapshot merge, neither of which
        // sorts. A `Sized` write on the same table fans out.
        assert_eq!(
            provider.snapshot_shard_count(4, tsb, huge, EncodeFanOut::Sized),
            4,
            "a table's declared sort order must not serialize an unsorted write"
        );
        assert_eq!(
            provider
                .write_shard_format(4, tsb, huge, EncodeFanOut::Sized, None)
                .write_shard()
                .expect("an unsorted sized write keeps its shard config")
                .write_concurrency,
            4
        );
    }

    #[tokio::test]
    async fn test_shard_count_small_write_uses_single_shard() {
        // The core of the size-aware change: a delta smaller than one target
        // file must produce a single output file even though the configured
        // write concurrency is 4. Sharding a tiny CDC delta into N files buys no
        // encode parallelism and only multiplies per-scan read amplification.
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_sorted_cayenne_table(
            "shard_size_small",
            Arc::clone(&schema),
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let tsb = provider.context.target_file_size_bytes();
        // A few KiB — far below one 256 MiB target file.
        let small = Some(4 * 1024);
        assert_eq!(
            provider.snapshot_shard_count(4, tsb, small, EncodeFanOut::Sized),
            1,
            "a sub-target-file write must stay a single shard"
        );
        assert!(
            provider
                .write_shard_format(4, tsb, small, EncodeFanOut::Sized, None)
                .write_shard()
                .is_none(),
            "single-shard writes use the unsharded base format (no WriteShardConfig)"
        );
    }

    #[tokio::test]
    async fn test_shard_count_large_write_uses_full_concurrency() {
        // A write far larger than write_concurrency × target_file_size must fan
        // out to the full configured concurrency (capped there, not above).
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_sorted_cayenne_table(
            "shard_size_large",
            Arc::clone(&schema),
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let tsb = provider.context.target_file_size_bytes();
        // 100 target files' worth of data, with a write concurrency of 4 ⇒
        // clamp to 4.
        let large = Some(tsb as u64 * 100);
        assert_eq!(
            provider.snapshot_shard_count(4, tsb, large, EncodeFanOut::Sized),
            4,
            "a write much larger than write_concurrency target files clamps to write_concurrency"
        );
        let format = provider.write_shard_format(4, tsb, large, EncodeFanOut::Sized, None);
        assert_eq!(
            format
                .write_shard()
                .expect("large write should enable sharding")
                .write_concurrency,
            4
        );
    }

    #[tokio::test]
    async fn test_shard_count_boundary_scales_with_target_files() {
        // The shard count tracks the number of *encode-shard units* the write
        // fills, capped at write_concurrency. cycle-2: the unit is target/16
        // (floored at 16 MiB), not the whole target-file size — small CDC deltas
        // stay single-file while checkpoint-scale flushes fan out.
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_sorted_cayenne_table(
            "shard_size_boundary",
            Arc::clone(&schema),
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let tsb = provider.context.target_file_size_bytes();
        // Mirror the production unit formula so this is robust to the default
        // target_file_size: clamp(target/16, min(16 MiB, target), target).
        let target = tsb as u64;
        let unit = (target / 16).clamp((16 * 1024 * 1024u64).min(target), target);

        // < 1 unit ⇒ 1 shard (need to *fill* a unit to earn a second).
        assert_eq!(
            provider.snapshot_shard_count(8, tsb, Some(unit - 1), EncodeFanOut::Sized),
            1
        );
        // Exactly 1 unit ⇒ 1 shard.
        assert_eq!(
            provider.snapshot_shard_count(8, tsb, Some(unit), EncodeFanOut::Sized),
            1
        );
        // 3 units' worth ⇒ 3 shards (below the concurrency cap of 4).
        assert_eq!(
            provider.snapshot_shard_count(8, tsb, Some(unit * 3), EncodeFanOut::Sized),
            3
        );
        // 3.9 units' worth still floors to 3 shards.
        assert_eq!(
            provider.snapshot_shard_count(
                8,
                tsb,
                Some(unit * 3 + unit * 9 / 10),
                EncodeFanOut::Sized
            ),
            3
        );
        // 12 units' worth, but with no per-table override the default
        // write_concurrency is DEFAULT_WRITE_CONCURRENCY (4), so it clamps to 4.
        assert_eq!(
            provider.snapshot_shard_count(8, tsb, Some(unit * 12), EncodeFanOut::Sized),
            4
        );
    }

    #[tokio::test]
    async fn test_shard_count_unknown_size_preserves_full_concurrency() {
        // estimated_bytes == None is the explicit "unknown size" fallback: it
        // takes the full write concurrency (not a size-derived count), so opaque
        // streams (compaction-less staged appends, overwrites) shard at the
        // configured write_concurrency. With no per-table override that is the
        // default, DEFAULT_WRITE_CONCURRENCY (4), capped at the session's
        // target_partitions.
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_sorted_cayenne_table(
            "shard_size_unknown",
            Arc::clone(&schema),
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let tsb = provider.context.target_file_size_bytes();
        assert_eq!(
            provider.snapshot_shard_count(6, tsb, None, EncodeFanOut::Sized),
            4
        );
        assert_eq!(
            provider
                .write_shard_format(6, tsb, None, EncodeFanOut::Sized, None)
                .write_shard()
                .expect("unknown-size write keeps full fan-out")
                .write_concurrency,
            4
        );
    }

    #[tokio::test]
    async fn clear_cached_table_statistics_drops_optimizer_cache() {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _temp_dir) = create_sorted_cayenne_table(
            "clear_cached_stats_optimizer_test",
            schema,
            vec![],
            ctx.runtime_env(),
        )
        .await;

        {
            let mut cache = provider.table_statistics.write();
            cache.optimizer = Some(datafusion_common::Statistics::new_unknown(
                &provider.table_metadata.schema,
            ));
        }

        assert!(
            provider.table_statistics.read().optimizer.is_some(),
            "precondition: derived Statistics cache must be seeded"
        );

        provider.clear_cached_table_statistics_unlocked();

        assert!(
            provider.table_statistics.read().optimizer.is_none(),
            "clear must drop the derived Statistics cache"
        );
    }

    /// Helper to insert a `RecordBatch` into a `CayenneTableProvider`.
    async fn insert_batch_with_context(
        ctx: &SessionContext,
        provider: &CayenneTableProvider,
        batch: RecordBatch,
    ) {
        let schema = batch.schema();

        let mem_exec = MemorySourceConfig::try_new_exec(&[vec![batch]], Arc::clone(&schema), None)
            .expect("memory exec created");

        let insert_plan = provider
            .insert_into(&ctx.state(), mem_exec, InsertOp::Append)
            .await
            .expect("insert plan created");

        let _ = collect(insert_plan, ctx.task_ctx())
            .await
            .expect("insert done");
    }

    /// Helper to insert a `RecordBatch` into a `CayenneTableProvider`.
    async fn insert_batch(provider: &CayenneTableProvider, batch: RecordBatch) {
        let ctx = SessionContext::new();
        insert_batch_with_context(&ctx, provider, batch).await;
    }

    /// The schema [`make_listing_parity_batch`] builds: it hard-codes
    /// `Int64Array / StringArray / Int64Array` in this order and panics on any other
    /// shape, so the two belong together.
    fn listing_parity_schema() -> SchemaRef {
        Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("category", DataType::Utf8, false),
            Field::new("value", DataType::Int64, false),
        ]))
    }

    fn make_listing_parity_batch(schema: SchemaRef, start: i64, row_count: usize) -> RecordBatch {
        use arrow::array::StringArray;
        let row_count = i64::try_from(row_count).expect("test row count fits in i64");
        let ids = (start..start + row_count).collect::<Vec<_>>();
        let categories = ids
            .iter()
            .map(|id| format!("category_{}", id.rem_euclid(3)))
            .collect::<Vec<_>>();
        let values = ids
            .iter()
            .map(|id| id.saturating_mul(10))
            .collect::<Vec<_>>();

        RecordBatch::try_new(
            schema,
            vec![
                Arc::new(Int64Array::from(ids)),
                Arc::new(StringArray::from(categories)),
                Arc::new(Int64Array::from(values)),
            ],
        )
        .expect("listing parity test batch is valid")
    }

    fn file_group_paths(file_groups: &[FileGroup]) -> Vec<Vec<String>> {
        file_groups
            .iter()
            .map(|group| {
                group
                    .iter()
                    .map(|file| file.path().to_string())
                    .collect::<Vec<_>>()
            })
            .collect()
    }

    fn file_group_row_counts(file_groups: &[FileGroup]) -> Vec<Vec<DFPrecision<usize>>> {
        file_groups
            .iter()
            .map(|group| {
                group
                    .iter()
                    .map(|file| {
                        file.statistics
                            .as_ref()
                            .map_or(DFPrecision::Absent, |statistics| statistics.num_rows)
                    })
                    .collect::<Vec<_>>()
            })
            .collect()
    }

    /// An order-insensitive view of a resolved scan file set: a `path -> row_count`
    /// map flattened across groups. The manifest resolver returns files sorted by
    /// `file_path` (the metastore PK index order) while a directory listing returns
    /// object-store readdir order, so the two agree on the file SET and per-file
    /// row counts but NOT on the partition-split layout — which carries no
    /// query-correctness meaning (the scan unions all partitions). Compare this
    /// map, not the positional `file_group_paths`/`file_group_row_counts`, for
    /// cross-source parity.
    fn path_row_counts(file_groups: &[FileGroup]) -> BTreeMap<String, DFPrecision<usize>> {
        file_groups
            .iter()
            .flat_map(FileGroup::iter)
            .map(|file| {
                (
                    file.path().to_string(),
                    file.statistics
                        .as_ref()
                        .map_or(DFPrecision::Absent, |statistics| statistics.num_rows),
                )
            })
            .collect()
    }

    async fn collect_value_id_rows(
        ctx: &SessionContext,
        plan: Arc<dyn ExecutionPlan>,
    ) -> Vec<(i64, i64)> {
        let batches = collect(plan, ctx.task_ctx())
            .await
            .expect("scan plan should collect");
        let mut rows = Vec::new();

        for batch in batches {
            let value_col = batch
                .column(0)
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("projected value column should be Int64");
            let id_col = batch
                .column(1)
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("projected id column should be Int64");

            rows.extend((0..batch.num_rows()).map(|row| (value_col.value(row), id_col.value(row))));
        }

        rows.sort_unstable();
        rows
    }

    #[tokio::test]
    async fn direct_snapshot_scan_matches_listing_table_scan_behavior() {
        let schema = listing_parity_schema();
        let config = SessionConfig::new()
            .with_target_partitions(2)
            .set_usize("datafusion.execution.meta_fetch_concurrency", 1);
        let ctx = SessionContext::new_with_config(config);
        let (provider, _temp_dir) = create_sorted_cayenne_table(
            "listing_table_parity",
            Arc::clone(&schema),
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let rows_per_file = INLINE_MAX_ROWS + 16;
        for batch_idx in 0..3_usize {
            let start =
                i64::try_from(batch_idx * rows_per_file).expect("test batch start fits in i64");
            insert_batch_with_context(
                &ctx,
                &provider,
                make_listing_parity_batch(Arc::clone(&schema), start, rows_per_file),
            )
            .await;
        }

        let snapshot_id = provider.get_current_snapshot_id();
        let snapshot_dir_url = CayenneTableProvider::snapshot_dir_url(
            &provider.table_metadata.path,
            &provider.table_metadata.table_id,
            &snapshot_id,
        );
        let listing_table = CayenneTableProvider::create_listing_table_with_config(
            &snapshot_dir_url,
            Arc::clone(&provider.table_metadata.schema),
            provider.context.file_format(),
            &provider.pk_deletion_strategy,
            ctx.state().config(),
        )
        .expect("legacy listing table should be created");

        let table_url = ListingTableUrl::parse(&snapshot_dir_url).expect("snapshot URL parses");
        let options = CayenneTableProvider::create_listing_options(
            provider.context.file_format(),
            &provider.pk_deletion_strategy,
            ctx.state().config(),
        );
        let scan_schema =
            CayenneTableProvider::snapshot_scan_schema(&provider.table_metadata.schema, &options);
        let file_limit = Some(rows_per_file + 1);

        let direct_files = provider
            .list_files_for_snapshot_scan(&SnapshotScanListingRequest {
                state: &ctx.state(),
                table_url: &table_url,
                options: &options,
                partition_filters: &[],
                data_filters: &[],
                snapshot_id: &snapshot_id,
                limit: file_limit,
                scan_schema: Arc::clone(&scan_schema),
            })
            .await
            .expect("direct scan file listing should succeed");
        let listing_files = listing_table
            .list_files_for_scan(&ctx.state(), &[], file_limit)
            .await
            .expect("ListingTable file listing should succeed");

        assert_eq!(
            direct_files.grouped_by_partition,
            listing_files.grouped_by_partition
        );
        assert_eq!(direct_files.statistics, listing_files.statistics);
        assert_eq!(
            file_group_paths(&direct_files.file_groups),
            file_group_paths(&listing_files.file_groups),
            "direct scan planning must preserve ListingTable file grouping"
        );
        assert_eq!(
            file_group_row_counts(&direct_files.file_groups),
            file_group_row_counts(&listing_files.file_groups),
            "direct scan planning must preserve per-file row-count statistics"
        );

        let projection = vec![2, 0];
        let direct_plan = provider
            .create_snapshot_scan_plan(&ctx.state(), &snapshot_id, Some(&projection), &[], None)
            .await
            .expect("direct scan plan should be created");
        let listing_plan = listing_table
            .scan(&ctx.state(), Some(&projection), &[], None)
            .await
            .expect("ListingTable scan plan should be created");

        assert_eq!(direct_plan.schema(), listing_plan.schema());
        assert_eq!(
            direct_plan
                .partition_statistics(None)
                .expect("direct scan plan statistics should be available"),
            listing_plan
                .partition_statistics(None)
                .expect("ListingTable scan plan statistics should be available")
        );
        assert_eq!(
            direct_plan
                .properties()
                .output_partitioning()
                .partition_count(),
            listing_plan
                .properties()
                .output_partitioning()
                .partition_count()
        );
        assert_eq!(
            direct_plan.properties().output_ordering().is_some(),
            listing_plan.properties().output_ordering().is_some()
        );
        assert_eq!(
            collect_value_id_rows(&ctx, direct_plan).await,
            collect_value_id_rows(&ctx, listing_plan).await
        );
    }

    /// REGRESSION — point-lookup file-group fan-out. `is_pk_selective_scan`
    /// forces `target_partitions = 1` on the inner listing config so a 1-row PK
    /// lookup does not pay 16× Vortex footer-opens. This proves whether the
    /// override (a) is even chosen for `id = K`, and (b) SURVIVES the physical
    /// optimizer's `repartition_file_scans` rule (which runs with the OUTER
    /// session's `target_partitions`, here 16). The diagnostic
    /// `pk_lookup_file_group_fanout` bench only forced the OUTER session tp, so it
    /// never exercised this production wiring — and no test guards the final-plan
    /// group count.
    #[tokio::test]
    async fn pk_point_lookup_fast_path_survives_physical_optimizer() {
        fn max_leaf_partitions(plan: &dyn ExecutionPlan) -> usize {
            let children = plan.children();
            if children.is_empty() {
                return plan.properties().output_partitioning().partition_count();
            }
            children
                .into_iter()
                .map(|c| max_leaf_partitions(&**c))
                .max()
                .unwrap_or(0)
        }

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));

        // tp=16 + near-zero `repartition_file_min_size` reproduces the production
        // 16-group byte-range split on a small file (no 1 M-row table needed).
        let mut config = SessionConfig::new().with_target_partitions(16);
        config.options_mut().optimizer.repartition_file_min_size = 1;
        let ctx = SessionContext::new_with_config(config);

        // inline_max_rows = 0 ⇒ the insert lands as an on-disk Vortex file the scan
        // must open + can split (not an in-RAM inline batch).
        let vortex_config = VortexConfig {
            inline_max_rows: 0,
            ..VortexConfig::default()
        };
        let (provider, _temp_dir) = create_cayenne_table_with_config(
            "pk_lookup_fanout_regression",
            Arc::clone(&schema),
            vortex_config,
            vec!["id".to_string()],
            ctx.runtime_env(),
        )
        .await;

        let n: i64 = 100_000;
        let batch = RecordBatch::try_new(
            Arc::clone(&schema),
            vec![
                Arc::new(Int64Array::from_iter_values(0..n)),
                Arc::new(Int64Array::from_iter_values((0..n).map(|x| x * 10))),
            ],
        )
        .expect("batch built");
        insert_batch_with_context(&ctx, &provider, batch).await;

        let target_id = n / 2;
        let sel_filter = Expr::Column(datafusion_common::Column::new_unqualified("id")).eq(
            Expr::Literal(datafusion_common::ScalarValue::Int64(Some(target_id)), None),
        );

        // (0) Does the fast-path logic even select tp=1 for `id = K`?
        let fast_path_fires = provider.is_pk_selective_scan(std::slice::from_ref(&sel_filter));

        // BEFORE the physical optimizer: what scan() itself builds.
        let before_sel = provider
            .scan(&ctx.state(), None, std::slice::from_ref(&sel_filter), None)
            .await
            .expect("selective scan plan");
        let before_nonsel = provider
            .scan(&ctx.state(), None, &[], None)
            .await
            .expect("non-selective scan plan");
        let before_sel_groups = max_leaf_partitions(before_sel.as_ref());
        let before_nonsel_groups = max_leaf_partitions(before_nonsel.as_ref());

        // AFTER the physical optimizer: what actually executes.
        let provider = Arc::new(provider);
        ctx.register_table("t", Arc::clone(&provider) as Arc<dyn TableProvider>)
            .expect("register table");
        let after_sel = ctx
            .sql(&format!("SELECT value FROM t WHERE id = {target_id}"))
            .await
            .expect("selective sql")
            .create_physical_plan()
            .await
            .expect("selective physical plan");
        let after_nonsel = ctx
            .sql("SELECT sum(value) FROM t")
            .await
            .expect("non-selective sql")
            .create_physical_plan()
            .await
            .expect("non-selective physical plan");
        let after_sel_groups = max_leaf_partitions(after_sel.as_ref());
        let after_nonsel_groups = max_leaf_partitions(after_nonsel.as_ref());

        eprintln!(
            "[pk-fanout] is_pk_selective_scan(id=K) = {fast_path_fires}\n  \
             selective  id={target_id}: scan-build={before_sel_groups}  executed={after_sel_groups}\n  \
             non-select SUM       : scan-build={before_nonsel_groups}  executed={after_nonsel_groups}"
        );

        // Control: the config reproduces fan-out on a non-selective scan.
        assert!(
            after_nonsel_groups > 1,
            "control: non-selective scan should fan out at execution (got {after_nonsel_groups})"
        );

        // The finding: a point lookup must NOT fan out. If this fails with
        // executed > 1 while is_pk_selective_scan is true, the tp=1 override did
        // not survive repartition_file_scans.
        assert_eq!(
            after_sel_groups, 1,
            "point-lookup file scan fanned out to {after_sel_groups} groups \
             (is_pk_selective_scan={fast_path_fires}, scan-build={before_sel_groups}); \
             supports_repartitioning()=false must stop repartition_file_scans from \
             byte-range-splitting the selective scan"
        );
    }

    /// Small file groups opt the Vortex source out of `repartition_file_scans`
    /// on internal/protected-snapshot scan plans: byte-range-splitting a small
    /// snapshot into `target_partitions` scan units multiplies footer opens
    /// ~tp× for no decode parallelism
    #[tokio::test]
    async fn small_snapshot_groups_opt_out_of_repartitioning() {
        fn scan_source_allows_repartitioning(plan: &Arc<dyn ExecutionPlan>) -> Option<bool> {
            if let Some(exec) = plan.downcast_ref::<datafusion_datasource::source::DataSourceExec>()
            {
                let config = exec.data_source().downcast_ref::<FileScanConfig>()?;
                let vortex = config.file_source().downcast_ref::<VortexSource>()?;
                return Some(vortex.supports_repartitioning());
            }
            plan.children()
                .into_iter()
                .find_map(scan_source_allows_repartitioning)
        }

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let ctx = SessionContext::new();
        // inline_max_rows = 0 ⇒ the insert lands as an on-disk Vortex file.
        let vortex_config = VortexConfig {
            inline_max_rows: 0,
            ..VortexConfig::default()
        };
        let (provider, _temp_dir) = create_cayenne_table_with_config(
            "small_group_repartition_opt_out",
            Arc::clone(&schema),
            vortex_config,
            vec!["id".to_string()],
            ctx.runtime_env(),
        )
        .await;
        let batch = RecordBatch::try_new(
            Arc::clone(&schema),
            vec![
                Arc::new(Int64Array::from_iter_values(0..1000)),
                Arc::new(Int64Array::from_iter_values(0..1000)),
            ],
        )
        .expect("batch built");
        insert_batch_with_context(&ctx, &provider, batch).await;

        // Internal/protected-branch path: the tiny group opts out of splitting.
        let snapshot_id = provider.get_current_snapshot_id();
        let internal_plan = provider
            .create_snapshot_scan_plan(&ctx.state(), &snapshot_id, None, &[], None)
            .await
            .expect("internal scan plan");
        assert_eq!(
            scan_source_allows_repartitioning(&internal_plan),
            Some(false),
            "a small file group must report supports_repartitioning()==false so \
             repartition_file_scans does not byte-range-split it"
        );

        // Main-branch control: default splitting stays enabled (threshold 0).
        let main_plan = provider
            .scan(&ctx.state(), None, &[], None)
            .await
            .expect("main scan plan");
        assert_eq!(
            scan_source_allows_repartitioning(&main_plan),
            Some(true),
            "the main query branch keeps default repartitioning"
        );
    }

    /// Lever B (file-level pruning) end-to-end for a PK point lookup: with three
    /// on-disk files spanning disjoint id ranges, a `WHERE id = K` scan must prune
    /// the two non-matching files at LISTING time (footer min/max), opening only
    /// the file whose range contains K. Exercises the production wiring
    /// (`list_files_for_snapshot_scan` → `build_listing_pruning_predicate` →
    /// `should_prune_partitioned_file`), not just the `file_pruning` unit tests.
    #[tokio::test]
    async fn pk_point_lookup_prunes_disjoint_files_at_listing() {
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let ctx = SessionContext::new();
        // inline_max_rows = 0 ⇒ each insert flushes to its own on-disk Vortex file.
        let vortex_config = VortexConfig {
            inline_max_rows: 0,
            ..VortexConfig::default()
        };
        let (provider, _temp_dir) = create_cayenne_table_with_config(
            "pk_lookup_listing_prune",
            Arc::clone(&schema),
            vortex_config,
            vec!["id".to_string()],
            ctx.runtime_env(),
        )
        .await;

        // Three files with DISJOINT id ranges: [0,10k), [10k,20k), [20k,30k).
        let rows: i64 = 10_000;
        for f in 0..3_i64 {
            let start = f * rows;
            let batch = RecordBatch::try_new(
                Arc::clone(&schema),
                vec![
                    Arc::new(Int64Array::from_iter_values(start..start + rows)),
                    Arc::new(Int64Array::from_iter_values(
                        (start..start + rows).map(|x| x * 10),
                    )),
                ],
            )
            .expect("batch built");
            insert_batch_with_context(&ctx, &provider, batch).await;
        }

        let snapshot_id = provider.get_current_snapshot_id();
        let snapshot_dir_url = CayenneTableProvider::snapshot_dir_url(
            &provider.table_metadata.path,
            &provider.table_metadata.table_id,
            &snapshot_id,
        );
        let table_url = ListingTableUrl::parse(&snapshot_dir_url).expect("snapshot URL parses");
        let options = CayenneTableProvider::create_listing_options(
            provider.context.file_format(),
            &provider.pk_deletion_strategy,
            ctx.state().config(),
        );
        let scan_schema =
            CayenneTableProvider::snapshot_scan_schema(&provider.table_metadata.schema, &options);

        // K = 15_000 lands in file 1 ([10k,20k)); files 0 and 2 must be pruned.
        let target_id = 15_000_i64;
        let sel_filter = Expr::Column(datafusion_common::Column::new_unqualified("id")).eq(
            Expr::Literal(datafusion_common::ScalarValue::Int64(Some(target_id)), None),
        );

        let pruned = provider
            .list_files_for_snapshot_scan(&SnapshotScanListingRequest {
                state: &ctx.state(),
                table_url: &table_url,
                options: &options,
                partition_filters: &[],
                data_filters: std::slice::from_ref(&sel_filter),
                snapshot_id: &snapshot_id,
                limit: None,
                scan_schema: Arc::clone(&scan_schema),
            })
            .await
            .expect("listing scan with point-lookup filter");
        let pruned_files: usize = file_group_paths(&pruned.file_groups)
            .into_iter()
            .map(|g| g.len())
            .sum();

        // Control: a no-filter listing sees all three files.
        let all = provider
            .list_files_for_snapshot_scan(&SnapshotScanListingRequest {
                state: &ctx.state(),
                table_url: &table_url,
                options: &options,
                partition_filters: &[],
                data_filters: &[],
                snapshot_id: &snapshot_id,
                limit: None,
                scan_schema: Arc::clone(&scan_schema),
            })
            .await
            .expect("listing scan without filter");
        let all_files: usize = file_group_paths(&all.file_groups)
            .into_iter()
            .map(|g| g.len())
            .sum();

        eprintln!("[pk-prune] files: no-filter={all_files}  id={target_id}={pruned_files}");
        assert_eq!(
            all_files, 3,
            "control: three disjoint on-disk files expected"
        );
        assert_eq!(
            pruned_files, 1,
            "point-lookup id={target_id} must prune the 2 disjoint files at listing \
             via footer min/max, got {pruned_files}"
        );
    }

    /// Phase 2 manifest snapshot model: with `scan_from_manifest` ON, the scan's
    /// file set is resolved from `cayenne_snapshot_file` (the manifest) instead
    /// of by listing the snapshot directory — and the two must be EQUAL.
    ///
    /// The baseline is `DataFusion`'s own `ListingTable::list_files_for_scan`,
    /// which always lists the directory regardless of the flag, so it is an
    /// independent directory-built file set. The provider under test has the flag
    /// ON, so its `list_files_for_snapshot_scan` routes through the manifest. The
    /// manifest is populated deterministically via the production primitive
    /// (`upsert_snapshot_manifest_from_listing`) before the comparison. Equal
    /// file-group paths AND per-file row-count statistics prove the manifest-built
    /// listing equals the directory-built listing.
    ///
    /// Also asserts the dual-source fallback: with the manifest cleared, the
    /// manifest resolver returns `None` and the scan falls back to directory
    /// listing (so an unpopulated manifest can never make a scan miss a file).
    #[tokio::test]
    async fn scan_from_manifest_listing_equals_directory_listing() {
        let schema = listing_parity_schema();
        let config = SessionConfig::new()
            .with_target_partitions(2)
            .set_usize("datafusion.execution.meta_fetch_concurrency", 1);
        let ctx = SessionContext::new_with_config(config);

        let vortex_config = VortexConfig {
            // Route scans through the manifest (the feature under test).
            scan_from_manifest: true,
            // Disable the inline memtable so each insert lands as an on-disk
            // Vortex file in the snapshot dir (the manifest's domain) rather than
            // being absorbed inline (no file, nothing to list).
            inline_max_rows: 0,
            ..VortexConfig::default()
        };
        let (provider, _temp_dir) = create_cayenne_table_with_config(
            "scan_from_manifest_parity",
            Arc::clone(&schema),
            vortex_config,
            vec![],
            ctx.runtime_env(),
        )
        .await;

        // Two batches → a non-trivial multi-file set to resolve.
        let rows_per_file = INLINE_MAX_ROWS + 16;
        for batch_idx in 0..2_usize {
            let start =
                i64::try_from(batch_idx * rows_per_file).expect("test batch start fits in i64");
            insert_batch_with_context(
                &ctx,
                &provider,
                make_listing_parity_batch(Arc::clone(&schema), start, rows_per_file),
            )
            .await;
        }

        // Quiesce the debounced post-write maintenance the inserts scheduled. When
        // it fires (~100 ms later) it rebuilds the manifest from the directory
        // listing, which would re-populate the manifest AFTER this test clears it
        // (breaking the empty-manifest fallback assertion below) and reorder its
        // rows. Draining it now makes the manifest state fully test-controlled.
        // (Append table — 2 files, no protected snapshots — so no async compaction
        // is armed; this only stops the manifest-rebuild loop.)
        provider
            .flush_pending_maintenance()
            .await
            .expect("drain pending post-write maintenance");

        let snapshot_id = provider.get_current_snapshot_id();
        let snapshot_dir_url = CayenneTableProvider::snapshot_dir_url(
            &provider.table_metadata.path,
            &provider.table_metadata.table_id,
            &snapshot_id,
        );
        let table_url = ListingTableUrl::parse(&snapshot_dir_url).expect("snapshot URL parses");
        let options = CayenneTableProvider::create_listing_options(
            provider.context.file_format(),
            &provider.pk_deletion_strategy,
            ctx.state().config(),
        );
        let scan_schema =
            CayenneTableProvider::snapshot_scan_schema(&provider.table_metadata.schema, &options);
        let file_limit = Some(rows_per_file + 1);

        // Populate the manifest deterministically (the production write path does
        // this on a coalesced post-write maintenance pass; calling the primitive
        // directly removes the timing dependency). This is the current snapshot,
        // so use the same `PreserveOrUniform` tag `rebuild_live_snapshot_manifests`
        // uses for it (`[0, current_seq]`). The sequence tag is irrelevant to this
        // test — it asserts the resolved file SET, not the per-row sequence range.
        let sequence = provider
            .catalog
            .get_snapshot_sequence(&provider.table_metadata.table_id, &snapshot_id)
            .await
            .ok()
            .flatten()
            .unwrap_or(0);
        let listed = provider
            .upsert_snapshot_manifest_from_listing(
                &snapshot_id,
                ManifestSequenceTag::PreserveOrUniform {
                    min: 0,
                    max: sequence,
                },
            )
            .await
            .expect("manifest population should succeed");
        assert!(
            !listed.is_empty(),
            "the write should have produced at least one on-disk file to populate"
        );

        let request = SnapshotScanListingRequest {
            state: &ctx.state(),
            table_url: &table_url,
            options: &options,
            partition_filters: &[],
            data_filters: &[],
            snapshot_id: &snapshot_id,
            limit: file_limit,
            scan_schema: Arc::clone(&scan_schema),
        };

        // The manifest resolver must now return a non-empty set (flag is ON and
        // the manifest is populated), proving the manifest branch is taken.
        let manifest_only = provider
            .manifest_partitioned_files(&request)
            .await
            .expect("manifest resolver returns Some when the manifest is populated");
        assert_eq!(
            manifest_only.len(),
            listed.len(),
            "manifest resolver must surface exactly the populated file set"
        );

        // Manifest-routed scan file listing (flag ON → routes through the manifest).
        let manifest_files = provider
            .list_files_for_snapshot_scan(&request)
            .await
            .expect("manifest-routed scan file listing should succeed");

        // Directory baseline via DataFusion's ListingTable (flag-independent —
        // it always lists the snapshot directory).
        let listing_table = CayenneTableProvider::create_listing_table_with_config(
            &snapshot_dir_url,
            Arc::clone(&provider.table_metadata.schema),
            provider.context.file_format(),
            &provider.pk_deletion_strategy,
            ctx.state().config(),
        )
        .expect("listing table should be created");
        let listing_files = listing_table
            .list_files_for_scan(&ctx.state(), &[], file_limit)
            .await
            .expect("ListingTable file listing should succeed");

        // Order-insensitive: the manifest resolver returns files sorted by
        // `file_path` (metastore PK-index order) while the directory listing
        // returns object-store readdir order. They must agree on the file SET and
        // each file's row count; the partition-split order is not a correctness
        // property (the scan unions all partitions).
        assert_eq!(
            path_row_counts(&manifest_files.file_groups),
            path_row_counts(&listing_files.file_groups),
            "manifest-built scan files (paths + per-file row counts) must equal the \
             directory-built listing"
        );
        assert_eq!(
            manifest_files.grouped_by_partition,
            listing_files.grouped_by_partition
        );
        assert_eq!(manifest_files.statistics, listing_files.statistics);

        // Dual-source fallback: clear the manifest and the resolver must return
        // `None`, so the scan falls back to directory listing rather than reading
        // a short (incomplete) file set.
        provider
            .catalog
            .clear_snapshot_files(&provider.table_metadata.table_id)
            .await
            .expect("manifest cleared");
        assert!(
            provider
                .manifest_partitioned_files(&request)
                .await
                .is_none(),
            "an empty manifest must fall back to directory listing (Some -> None)"
        );
        // The end-to-end listing must still succeed (and match the directory
        // baseline) via the fallback even with the flag ON.
        let fallback_files = provider
            .list_files_for_snapshot_scan(&request)
            .await
            .expect("scan file listing should fall back to directory listing");
        assert_eq!(
            path_row_counts(&fallback_files.file_groups),
            path_row_counts(&listing_files.file_groups),
            "with an empty manifest the flag-ON scan must fall back to the directory listing"
        );
    }

    // ----------------------------------------------------------------------
    // Manifest snapshot model (phase 5): backfill `cayenne_snapshot_file` on
    // open for snapshots that predate manifest population.
    // ----------------------------------------------------------------------

    /// Append-mode (no-PK, on-disk) table over a durable `SQLite` metastore that
    /// the test can REOPEN. Mirrors `create_memory_mode_upsert_table` but for the
    /// append shape the backfill test needs: every insert lands as an on-disk
    /// `.vortex` file (`inline_max_rows: 0`) so there is a real directory listing
    /// to backfill from. Returns the catalog so the test can clear the manifest
    /// and reopen against the same durable state.
    async fn create_reopenable_append_table(
        table_name: &str,
        schema: SchemaRef,
        scan_from_manifest: bool,
        runtime_env: Arc<RuntimeEnv>,
    ) -> (
        CayenneTableProvider,
        Arc<dyn MetadataCatalog>,
        tempfile::TempDir,
    ) {
        let temp_dir = tempfile::tempdir().expect("temp dir created");
        let metadata_dir = format!(
            "{}/metadata",
            temp_dir.path().to_str().expect("should be str")
        );
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("should be str"));
        std::fs::create_dir_all(&metadata_dir).expect("metadata dir created");

        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");

        let vortex_config = VortexConfig {
            scan_from_manifest,
            // On-disk files only: no inline memtable, so each insert is a Vortex
            // object in the snapshot dir (the manifest's domain).
            inline_max_rows: 0,
            ..VortexConfig::default()
        };
        let options = CreateTableOptions {
            table_name: table_name.to_string(),
            schema,
            primary_key: vec![],
            on_conflict: None,
            base_path: data_dir,
            partition_column: None,
            vortex_config,
        };
        let provider = CayenneTableProviderBuilder::new(Arc::clone(&catalog), runtime_env)
            .create(options)
            .await
            .expect("table created");
        (provider, catalog, temp_dir)
    }

    /// Open the metastore `SQLite` file directly, bypassing the catalog. The path
    /// layout is the one `create_reopenable_append_table` and its siblings build.
    fn open_metastore_db(temp_dir: &std::path::Path) -> rusqlite::Connection {
        let conn = rusqlite::Connection::open(temp_dir.join("metadata").join("cayenne.db"))
            .expect("open metastore db directly");
        conn.busy_timeout(std::time::Duration::from_secs(5))
            .expect("busy timeout");
        conn
    }

    /// Make the statistics READ fail while leaving the write leg working.
    ///
    /// The blob column is `NOT NULL`, but it has BLOB affinity, so `SQLite` stores
    /// a text value in it unconverted — and the row mapper's blob accessor
    /// rejects a text value, so `get_table_statistics` returns `Err`. The UPSERT
    /// a merge performs afterwards still succeeds. That asymmetry is what makes a
    /// merge onto a missing baseline durable, so it is what the fixture has to
    /// reproduce: dropping the whole table would fail the write too, and prove
    /// nothing.
    fn make_table_statistics_unreadable(temp_dir: &std::path::Path, table_id: &str) {
        let conn = open_metastore_db(temp_dir);
        let updated = conn
            .execute(
                "UPDATE cayenne_table_statistics SET statistics_blob = 'unreadable'
                 WHERE table_id = ?1",
                [table_id],
            )
            .expect("store an unreadable statistics blob");
        assert_eq!(
            updated, 1,
            "the fixture must corrupt exactly the one statistics row under test"
        );
    }

    /// The durable statistics row, read directly — the catalog's own reader is
    /// the thing the fixture has broken.
    struct DurableStatsRow {
        num_rows: i64,
        num_rows_exact: bool,
        /// Whether the blob is still the fixture's text sentinel. Distinguishes
        /// "left alone" from "rewritten": only a real write replaces it with a
        /// blob.
        blob_is_text: bool,
    }

    fn read_durable_stats_row(temp_dir: &std::path::Path, table_id: &str) -> DurableStatsRow {
        let conn = open_metastore_db(temp_dir);
        conn.query_row(
            "SELECT num_rows, num_rows_exact, typeof(statistics_blob) = 'text'
             FROM cayenne_table_statistics WHERE table_id = ?1",
            [table_id],
            |row| {
                Ok(DurableStatsRow {
                    num_rows: row.get::<_, i64>(0)?,
                    num_rows_exact: row.get::<_, i64>(1)? != 0,
                    blob_is_text: row.get::<_, i64>(2)? != 0,
                })
            },
        )
        .expect("read the durable statistics row")
    }

    /// Regression for #13010: a statistics read that FAILS must not be treated as
    /// "this table has no statistics row yet".
    ///
    /// The merge reads an absent record as a zero baseline that is trusted exact,
    /// so routing a failed read into that branch rewrites the durable record to
    /// hold only the current write's rows and flags that partial total exact. An
    /// exact `num_rows` is folded straight into a distributed `COUNT(*)` answer
    /// instead of costing a scan, and the rewritten record survives restart
    /// looking like a legitimate exact baseline, so nothing later corrects it.
    #[tokio::test]
    async fn an_unreadable_stats_record_must_not_publish_a_partial_count_as_exact() {
        const BASELINE_ROWS: usize = 24;
        const SECOND_WRITE_ROWS: usize = 8;

        let runtime_env = SessionContext::new().runtime_env();
        let schema = listing_parity_schema();
        let (provider, catalog, temp_dir) = create_reopenable_append_table(
            "stats_unreadable_partial_count",
            Arc::clone(&schema),
            false,
            Arc::clone(&runtime_env),
        )
        .await;
        let table_id = provider.table_metadata.table_id.clone();

        // Baseline: a persisted, exact count describing every row written.
        let ctx = SessionContext::new();
        insert_batch_with_context(
            &ctx,
            &provider,
            make_listing_parity_batch(Arc::clone(&schema), 0, BASELINE_ROWS),
        )
        .await;
        provider
            .flush_pending_maintenance()
            .await
            .expect("persist the baseline statistics");
        let baseline = catalog
            .get_table_statistics(&table_id)
            .await
            .expect("baseline stats query")
            .expect("baseline stats row present");
        assert_eq!(
            baseline.num_rows,
            i64::try_from(BASELINE_ROWS).expect("row count fits in i64"),
            "precondition: the baseline count describes every row written"
        );
        assert!(
            baseline.num_rows_exact,
            "precondition: a pure-append table's maintained count starts exact"
        );

        make_table_statistics_unreadable(temp_dir.path(), &table_id);

        // Reopen: the in-memory `raw` blob starts cold, which is the only state
        // that reaches the catalog read on the next write (#13010's reachability).
        drop(provider);
        let reopened =
            CayenneTableProviderBuilder::new(Arc::clone(&catalog), Arc::clone(&runtime_env))
                .open("stats_unreadable_partial_count")
                .await
                .expect("reopen over an unreadable statistics record");

        insert_batch_with_context(
            &ctx,
            &reopened,
            make_listing_parity_batch(
                Arc::clone(&schema),
                i64::try_from(BASELINE_ROWS).expect("row count fits in i64"),
                SECOND_WRITE_ROWS,
            ),
        )
        .await;
        reopened
            .flush_pending_maintenance()
            .await
            .expect("the maintenance pass must succeed even when it abandons the stats update");

        // State first, so a regression names the harm rather than the mechanism.
        let durable = read_durable_stats_row(temp_dir.path(), &table_id);
        assert_eq!(
            durable.num_rows,
            i64::try_from(BASELINE_ROWS).expect("row count fits in i64"),
            "a failed statistics read must leave the durable count alone; rewriting it to this \
             write's {SECOND_WRITE_ROWS} rows publishes a partial count as the table's total"
        );
        assert!(
            durable.num_rows_exact,
            "the untouched record keeps its own exactness; the fix must not rewrite it at all"
        );
        assert!(
            durable.blob_is_text,
            "the aggregate blob must be left as-is: merging without a baseline would replace the \
             accumulated min/max and NDV with this single write's"
        );

        // Only the statistics update was abandoned. The abandoned delta stays
        // outstanding, and that is what holds the served count at `Inexact`.
        assert!(
            reopened
                .post_write_maintenance
                .has_unapplied_live_rows_delta(),
            "an abandoned statistics update must leave its live-rows delta outstanding, which is \
             what stops the count being served Exact over the gap"
        );
        assert!(
            reopened
                .optimizer_table_statistics()
                .is_none_or(|stats| !matches!(
                    stats.num_rows,
                    datafusion_common::stats::Precision::Exact(_)
                )),
            "no Exact row count may be served while a statistics update is outstanding"
        );
    }

    /// Regression for #13010, open-time half: a statistics record that cannot be
    /// read must not leave the maintained count flagged exact.
    ///
    /// On its own this is masked — the same failure also leaves `optimizer`
    /// unset, so nothing is served from it — but it is what establishes
    /// `count_exact = true` over a cold `raw` blob, which is the precondition the
    /// durable rewrite above needs.
    #[tokio::test]
    async fn reopening_over_an_unreadable_stats_record_does_not_trust_the_count_as_exact() {
        let runtime_env = SessionContext::new().runtime_env();
        let schema = listing_parity_schema();
        let (provider, catalog, temp_dir) = create_reopenable_append_table(
            "stats_unreadable_open_exactness",
            Arc::clone(&schema),
            false,
            Arc::clone(&runtime_env),
        )
        .await;
        let table_id = provider.table_metadata.table_id.clone();

        let ctx = SessionContext::new();
        insert_batch_with_context(
            &ctx,
            &provider,
            make_listing_parity_batch(Arc::clone(&schema), 0, 16),
        )
        .await;
        provider
            .flush_pending_maintenance()
            .await
            .expect("persist the baseline statistics");
        drop(provider);

        // Control: with the record intact, a reopen still trusts the persisted
        // exactness — proving the fixture reaches this gate, and that the fix
        // narrows the trust rather than removing it.
        let intact =
            CayenneTableProviderBuilder::new(Arc::clone(&catalog), Arc::clone(&runtime_env))
                .open("stats_unreadable_open_exactness")
                .await
                .expect("reopen over an intact statistics record");
        assert!(
            intact.table_statistics.read().count_exact,
            "control: a readable exact record must still reopen as exact"
        );
        drop(intact);

        make_table_statistics_unreadable(temp_dir.path(), &table_id);

        let reopened =
            CayenneTableProviderBuilder::new(Arc::clone(&catalog), Arc::clone(&runtime_env))
                .open("stats_unreadable_open_exactness")
                .await
                .expect("reopen over an unreadable statistics record");
        assert!(
            !reopened.table_statistics.read().count_exact,
            "a statistics record that could not be read says nothing about the count, so it must \
             not reopen flagged exact"
        );
    }

    /// Regression for #13010: abandoning the update must also stop the *cached*
    /// count being served exact, for the callers that discard the returned bool.
    ///
    /// The maintenance drain reads that bool and keeps its live-rows delta
    /// outstanding, which holds the count `Inexact` on its own. The mem-tier
    /// checkpoint does not: it discards the bool, the `Delta { exact: false }` it
    /// passes is the very update being abandoned, and the checkpoint clears the
    /// in-memory proxies (resident rows, tombstones) that would otherwise demote
    /// the stats. Without an explicit demotion that path serves an `Exact` count
    /// which does not describe the corpus.
    #[tokio::test]
    async fn abandoning_a_stats_update_demotes_the_cached_exactness() {
        let runtime_env = SessionContext::new().runtime_env();
        let schema = listing_parity_schema();
        let (provider, catalog, temp_dir) = create_reopenable_append_table(
            "stats_unreadable_cached_exactness",
            Arc::clone(&schema),
            false,
            Arc::clone(&runtime_env),
        )
        .await;
        let table_id = provider.table_metadata.table_id.clone();

        let ctx = SessionContext::new();
        insert_batch_with_context(
            &ctx,
            &provider,
            make_listing_parity_batch(Arc::clone(&schema), 0, 16),
        )
        .await;
        provider
            .flush_pending_maintenance()
            .await
            .expect("persist the baseline statistics");
        drop(provider);

        // Reopen over the INTACT record: `optimizer` is populated and
        // `count_exact` is true, while `raw` starts cold — the one state that
        // reaches the catalog read on the next persist.
        let reopened =
            CayenneTableProviderBuilder::new(Arc::clone(&catalog), Arc::clone(&runtime_env))
                .open("stats_unreadable_cached_exactness")
                .await
                .expect("reopen over an intact statistics record");
        assert!(
            reopened.table_statistics.read().count_exact,
            "precondition: the reopened provider serves the persisted count as exact"
        );

        // A non-empty accumulator: an empty one bails before the read, which would
        // pass this test without ever exercising the failure under test.
        let accumulator = ColumnStatsAccumulator::new(&schema);
        accumulator.update(&make_listing_parity_batch(Arc::clone(&schema), 16, 4));
        assert!(
            accumulator.row_count() > 0,
            "precondition: the accumulator must produce a blob, or the persist bails early"
        );

        // Control: with the record readable, this same call persists and the count
        // stays exact — so the demotion below is the read failure's doing, not this
        // call shape's.
        assert!(
            reopened
                .persist_table_stats(
                    &accumulator,
                    RowCountUpdate::Delta {
                        delta: 4,
                        exact: true
                    }
                )
                .await,
            "control: a readable record must let the update through"
        );
        assert!(
            reopened.table_statistics.read().count_exact,
            "control: a successful exact delta leaves the count exact"
        );

        // Now break the read, and clear the cached `raw` the successful persist
        // just populated so the next one has to reach the catalog again.
        make_table_statistics_unreadable(temp_dir.path(), &table_id);
        reopened.table_statistics.write().raw = None;

        assert!(
            !reopened
                .persist_table_stats(
                    &accumulator,
                    RowCountUpdate::Delta {
                        delta: 4,
                        exact: false
                    }
                )
                .await,
            "an unreadable record must abandon the update"
        );
        assert!(
            !reopened.table_statistics.read().count_exact,
            "an abandoned update must demote the cached exactness: its rows are already visible \
             to scans and no persisted count describes them, so a caller that discards the \
             returned bool must not go on serving an Exact count"
        );
    }

    /// Regression for #13010: the demotion must survive the *next* successful
    /// incremental persist, and clear only on an authoritative `Set`.
    ///
    /// A one-shot `count_exact = false` does not hold. The next persist derives
    /// `prev_num_rows_exact` from the record it reads — the pre-gap baseline, still
    /// flagged exact — and then writes that back over the demotion, so a mem-tier
    /// checkpoint that abandons its delta (its caller discards the bool) followed
    /// by a staged append's `Delta { exact: true }` republishes a short count as
    /// exact, durably. Only compaction/overwrite materializes the live rows and can
    /// honestly re-baseline.
    #[tokio::test]
    async fn an_abandoned_update_keeps_the_count_inexact_until_a_set_rebaselines_it() {
        let runtime_env = SessionContext::new().runtime_env();
        let schema = listing_parity_schema();
        let (provider, catalog, temp_dir) = create_reopenable_append_table(
            "stats_abandoned_gap_outlives_next_persist",
            Arc::clone(&schema),
            false,
            Arc::clone(&runtime_env),
        )
        .await;
        let table_id = provider.table_metadata.table_id.clone();

        let ctx = SessionContext::new();
        insert_batch_with_context(
            &ctx,
            &provider,
            make_listing_parity_batch(Arc::clone(&schema), 0, 16),
        )
        .await;
        provider
            .flush_pending_maintenance()
            .await
            .expect("persist the baseline statistics");
        drop(provider);

        let reopened =
            CayenneTableProviderBuilder::new(Arc::clone(&catalog), Arc::clone(&runtime_env))
                .open("stats_abandoned_gap_outlives_next_persist")
                .await
                .expect("reopen over an intact statistics record");

        let accumulator = ColumnStatsAccumulator::new(&schema);
        accumulator.update(&make_listing_parity_batch(Arc::clone(&schema), 16, 4));
        assert!(
            accumulator.row_count() > 0,
            "precondition: the accumulator must produce a blob, or the persist bails early"
        );

        // Warm the cache with an intact baseline, and keep a copy of it: the
        // steady-state path merges onto this cached blob without a catalog read, so
        // restoring it below is what makes the post-abandon persist SUCCEED. That
        // success is the whole point — a failing one proves nothing about whether
        // the demotion survives.
        assert!(
            reopened
                .persist_table_stats(
                    &accumulator,
                    RowCountUpdate::Delta {
                        delta: 4,
                        exact: true
                    }
                )
                .await,
            "precondition: an intact record persists and warms the cache"
        );
        let intact_raw = reopened.table_statistics.read().raw.clone();
        assert!(
            intact_raw.as_ref().is_some_and(|raw| raw.num_rows_exact),
            "precondition: the warmed baseline is flagged exact — that is what a later \
             delta would otherwise inherit"
        );

        // Abandon one update, exactly as a mem-tier checkpoint would: break the read
        // and force the cold-`raw` path that has to reach the catalog.
        make_table_statistics_unreadable(temp_dir.path(), &table_id);
        reopened.table_statistics.write().raw = None;
        assert!(
            !reopened
                .persist_table_stats(
                    &accumulator,
                    RowCountUpdate::Delta {
                        delta: 4,
                        exact: false
                    }
                )
                .await,
            "precondition: an unreadable record must abandon the update"
        );

        // The gap is now open: 4 rows are visible to scans that no persisted count
        // includes. Restore the warm cache and let a later exact delta through.
        reopened.table_statistics.write().raw = intact_raw;
        assert!(
            reopened
                .persist_table_stats(
                    &accumulator,
                    RowCountUpdate::Delta {
                        delta: 4,
                        exact: true
                    }
                )
                .await,
            "the later persist must succeed — the gap is carried, not the failure"
        );
        assert!(
            !reopened.table_statistics.read().count_exact,
            "a successful exact delta over a gapped baseline must NOT restore exactness: it \
             merged onto a count that is short by the abandoned update's rows"
        );
        let durable = read_durable_stats_row(temp_dir.path(), &table_id);
        assert!(
            !durable.blob_is_text,
            "precondition: the later persist really rewrote the record"
        );
        assert!(
            !durable.num_rows_exact,
            "the short count must be recorded Inexact durably, or a restart re-declares it exact"
        );

        // A full rewrite materializes exactly the live rows, so it — and only it —
        // may re-baseline.
        reopened
            .replace_table_stats_after_rewrite(&accumulator)
            .await;
        assert!(
            reopened.table_statistics.read().count_exact,
            "an authoritative Set must clear the gap, or the table is stuck Inexact forever"
        );
        assert!(
            read_durable_stats_row(temp_dir.path(), &table_id).num_rows_exact,
            "the re-baselined count must be durably exact"
        );

        // The `Set` writing `true` proves nothing on its own — it does that whether
        // or not the gap was closed. What proves it is the NEXT incremental delta:
        // a gap left open would veto it, and the table would be Inexact forever.
        assert!(
            reopened
                .persist_table_stats(
                    &accumulator,
                    RowCountUpdate::Delta {
                        delta: 4,
                        exact: true
                    }
                )
                .await,
            "the post-rebaseline delta must persist"
        );
        assert!(
            reopened.table_statistics.read().count_exact,
            "once re-baselined, an ordinary exact delta must be trusted again — a gap that \
             never clears leaves the table permanently Inexact"
        );
    }

    /// Break the statistics WRITE while leaving the read leg working, so a persist
    /// bails at the UPSERT with its cached `raw` still warm.
    ///
    /// That combination is what puts the re-derivation hole in reach: the persist
    /// fails with a warm pre-gap record still flagged exact, which is precisely
    /// what a later re-derivation of `count_exact` would read exactness back out
    /// of. Whether it can is the property under test — `arm_row_count_taint_retry`
    /// drops `raw` as part of abandoning, so that pass finds nothing to trust.
    fn hide_table_statistics_table(temp_dir: &std::path::Path) {
        open_metastore_db(temp_dir)
            .execute_batch(
                "ALTER TABLE cayenne_table_statistics RENAME TO cayenne_table_statistics_hidden;",
            )
            .expect("hide the statistics table");
    }

    fn restore_table_statistics_table(temp_dir: &std::path::Path) {
        open_metastore_db(temp_dir)
            .execute_batch(
                "ALTER TABLE cayenne_table_statistics_hidden RENAME TO cayenne_table_statistics;",
            )
            .expect("restore the statistics table");
    }

    /// Regression for #13010: a schema evolution after an abandoned persist must
    /// not resurrect the exact, short count.
    ///
    /// `evolve_schema_live`'s width pass re-derives `count_exact` from the cached
    /// `raw` record, and a persist only replaces `raw` on success — so an abandoned
    /// one would otherwise leave the pre-gap record there, still flagged exact, for
    /// the re-derivation to trust. What prevents that is `arm_row_count_taint_retry`
    /// dropping `raw` as part of abandoning: the re-derivation then has nothing to
    /// trust and yields `false`. This pins that behaviour, because the demotion is
    /// only as good as the assignment sites that cannot undo it.
    #[tokio::test]
    async fn a_schema_evolution_after_an_abandoned_persist_does_not_resurrect_exactness() {
        let runtime_env = SessionContext::new().runtime_env();
        let schema = listing_parity_schema();
        let (provider, _catalog, temp_dir) = create_reopenable_append_table(
            "stats_gap_survives_schema_evolution",
            Arc::clone(&schema),
            false,
            Arc::clone(&runtime_env),
        )
        .await;

        let ctx = SessionContext::new();
        insert_batch_with_context(
            &ctx,
            &provider,
            make_listing_parity_batch(Arc::clone(&schema), 0, 16),
        )
        .await;
        provider
            .flush_pending_maintenance()
            .await
            .expect("persist the baseline statistics");

        // An authoritative `Set`: `raw` is now an exact record and no gap is open.
        let accumulator = ColumnStatsAccumulator::new(&schema);
        accumulator.update(&make_listing_parity_batch(Arc::clone(&schema), 0, 16));
        provider
            .replace_table_stats_after_rewrite(&accumulator)
            .await;
        assert!(
            provider
                .table_statistics
                .read()
                .raw
                .as_ref()
                .is_some_and(|raw| raw.num_rows_exact),
            "precondition: the warm record is flagged exact — that is what a re-derivation reads"
        );

        // A widening that relaxes nullability: no added column and no type change, so
        // the cached blob still deserializes against the evolved schema and `optimizer`
        // stays populated. An ADDED column does not reach the hole — the blob fails to
        // deserialize at the new width, `optimizer` goes `None`, and nothing is served.
        let evolved_schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("category", DataType::Utf8, false),
            Field::new("value", DataType::Int64, true),
        ]));
        let plan = match classify(
            &schema,
            &evolved_schema,
            &EvolutionContext {
                constraint_columns: &provider.table_metadata.primary_key,
            },
        ) {
            SchemaEvolution::Widening(plan) => plan,
            other => panic!("relaxed nullability must classify as a widening, got {other:?}"),
        };

        // CONTROL: with no gap open, the same evolution leaves the count Exact.
        // Without this the assertion below could pass because nothing ever serves
        // Exact on this fixture.
        provider
            .evolve_schema_live(&plan)
            .await
            .expect("control: schema evolution succeeds");
        assert!(
            matches!(
                provider
                    .optimizer_table_statistics()
                    .expect("control: statistics are served after evolution")
                    .num_rows,
                datafusion_common::stats::Precision::Exact(_)
            ),
            "control: with no outstanding gap, a re-derived exact count IS served Exact — so the \
             assertion below is about the gap, not about this fixture never serving Exact"
        );

        // Open a gap the way a failed mem-tier persist does: the UPSERT fails while
        // the cached `raw` stays warm, so `raw` keeps its pre-gap exact record.
        hide_table_statistics_table(temp_dir.path());
        assert!(
            !provider
                .persist_table_stats(
                    &accumulator,
                    RowCountUpdate::Delta {
                        delta: 16,
                        exact: false
                    }
                )
                .await,
            "precondition: a failed write must abandon the update"
        );
        restore_table_statistics_table(temp_dir.path());
        assert!(
            provider.table_statistics.read().raw.is_none(),
            "precondition: abandoning drops the cached record, so the re-derivation below has no \
             pre-gap baseline to resurrect exactness from"
        );

        // Re-derive exactly as the schema-width pass does. With `raw` dropped by the
        // abandon there is no pre-gap record left to read exactness back out of, and
        // the armed gap must veto it independently of that.
        let widened_schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("category", DataType::Utf8, true),
            Field::new("value", DataType::Int64, true),
        ]));
        let second_plan = match classify(
            &evolved_schema,
            &widened_schema,
            &EvolutionContext {
                constraint_columns: &provider.table_metadata.primary_key,
            },
        ) {
            SchemaEvolution::Widening(plan) => plan,
            other => panic!("the second relaxation must classify as a widening, got {other:?}"),
        };
        provider
            .evolve_schema_live(&second_plan)
            .await
            .expect("schema evolution succeeds with a gap open");
        assert!(
            !provider.table_statistics.read().count_exact,
            "the re-derivation must not restore exactness after an abandoned persist"
        );
        assert!(
            provider
                .optimizer_table_statistics()
                .is_none_or(|stats| !matches!(
                    stats.num_rows,
                    datafusion_common::stats::Precision::Exact(_)
                )),
            "a schema evolution after an abandoned persist must not serve an Exact count: the \
             durable record over-claims exactness relative to what is visible to scans, so \
             handing it to the COUNT(*) fold answers short"
        );
    }

    /// Phase 5: a table whose live snapshot has on-disk data files but NO
    /// manifest rows (it predates manifest population) must have its manifest
    /// backfilled from the directory listing on open — completely, so the
    /// `scan_from_manifest`-ON scan reads the right files. The backfilled set must
    /// equal the directory listing, the backfill must be idempotent across a
    /// second reopen, and the end-to-end scan must return every row.
    #[tokio::test]
    async fn backfill_on_open_populates_empty_manifest_from_directory() {
        let runtime_env = SessionContext::new().runtime_env();
        let schema = listing_parity_schema();
        let (provider, catalog, _temp_dir) = create_reopenable_append_table(
            "manifest_backfill_on_open",
            Arc::clone(&schema),
            true, // scan_from_manifest ON: the scan must read the backfilled set
            Arc::clone(&runtime_env),
        )
        .await;

        // Two batches → a multi-file snapshot to backfill.
        let rows_per_file = INLINE_MAX_ROWS + 16;
        let total_rows = 2 * rows_per_file;
        let ctx = SessionContext::new();
        for batch_idx in 0..2_usize {
            let start =
                i64::try_from(batch_idx * rows_per_file).expect("test batch start fits in i64");
            insert_batch_with_context(
                &ctx,
                &provider,
                make_listing_parity_batch(Arc::clone(&schema), start, rows_per_file),
            )
            .await;
        }

        // Simulate a snapshot written before manifest population existed: drop
        // every manifest row the write path may have produced. The directory
        // listing is untouched (the data files stay on disk).
        let table_id = provider.table_metadata.table_id.clone();
        let snapshot_id = provider.get_current_snapshot_id();
        let expected_files = listing_file_names(&provider, &snapshot_id).await;
        assert!(
            expected_files.len() >= 2,
            "the two on-disk-file inserts must produce a multi-file snapshot to backfill"
        );
        provider
            .catalog
            .clear_snapshot_files(&table_id)
            .await
            .expect("clear manifest to simulate a pre-population snapshot");
        assert!(
            manifest_file_names(&provider.catalog, &table_id, &snapshot_id)
                .await
                .is_empty(),
            "the manifest must be empty before reopen (simulated pre-population state)"
        );

        // Reopen the SAME table from the durable metastore. `new_internal` runs
        // the phase-5 backfill synchronously before returning the provider.
        drop(provider);
        let reopened =
            CayenneTableProviderBuilder::new(Arc::clone(&catalog), Arc::clone(&runtime_env))
                .open("manifest_backfill_on_open")
                .await
                .expect("reopen table");

        // The backfilled manifest must equal the directory listing exactly — not
        // a subset (a partial manifest would silently drop files from the scan).
        let backfilled = manifest_file_names(&reopened.catalog, &table_id, &snapshot_id).await;
        assert_eq!(
            backfilled, expected_files,
            "backfill must reproduce the directory listing exactly (complete, not partial)"
        );

        // End-to-end: with `scan_from_manifest` ON the scan resolves its files
        // from the just-backfilled manifest and must return every row.
        let scanned = scan_sorted_ids(&reopened).await;
        let expected_ids =
            (0..i64::try_from(total_rows).expect("row count fits in i64")).collect::<Vec<_>>();
        assert_eq!(
            scanned, expected_ids,
            "the manifest-routed scan over the backfilled manifest must read every row"
        );

        // Idempotence: a SECOND reopen must see the manifest already populated
        // (the emptiness gate) and leave it byte-for-byte identical — no duplicate
        // rows, no churn.
        drop(reopened);
        let reopened_again = CayenneTableProviderBuilder::new(Arc::clone(&catalog), runtime_env)
            .open("manifest_backfill_on_open")
            .await
            .expect("reopen table a second time");
        assert_eq!(
            manifest_file_names(&reopened_again.catalog, &table_id, &snapshot_id).await,
            expected_files,
            "a second open must not re-list or duplicate an already-populated manifest"
        );
    }

    /// Phase 5: backfill is gated on the manifest being EMPTY. A table the write
    /// path has already populated must NOT be re-listed or perturbed on open —
    /// the live write/compaction paths own it from then on. We prove the gate by
    /// poisoning the manifest with a sentinel row that the directory listing
    /// could never produce: if open left it intact, the gate held; if open
    /// re-listed, the sentinel would be gone.
    #[tokio::test]
    async fn backfill_on_open_is_skipped_when_manifest_already_populated() {
        let runtime_env = SessionContext::new().runtime_env();
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let (provider, catalog, _temp_dir) = create_reopenable_append_table(
            "manifest_backfill_gate",
            Arc::clone(&schema),
            false,
            Arc::clone(&runtime_env),
        )
        .await;

        insert_batch(&provider, int64_id_batch(&[1, 2, 3])).await;

        // A row no directory listing could ever yield (the listing only emits
        // real `.vortex` file names under the snapshot dir).
        let table_id = provider.table_metadata.table_id.clone();
        let snapshot_id = provider.get_current_snapshot_id();
        let sentinel_path = "sentinel-not-a-real-file.vortex".to_string();
        provider
            .catalog
            .upsert_snapshot_file(&SnapshotFile {
                table_id: table_id.clone(),
                snapshot_id: snapshot_id.clone(),
                file_path: sentinel_path.clone(),
                row_count: 0,
                file_size_bytes: 1,
                min_sequence: 0,
                max_sequence: 0,
                digest: None,
            })
            .await
            .expect("seed a sentinel manifest row");

        // Reopen: the manifest is non-empty, so the emptiness gate must skip the
        // backfill entirely and leave the sentinel in place.
        drop(provider);
        let reopened = CayenneTableProviderBuilder::new(catalog, runtime_env)
            .open("manifest_backfill_gate")
            .await
            .expect("reopen table");
        assert!(
            manifest_file_names(&reopened.catalog, &table_id, &snapshot_id)
                .await
                .contains(&sentinel_path),
            "a non-empty manifest must NOT be re-listed on open (the gate must hold)"
        );
    }

    // ----------------------------------------------------------------------
    // Manifest snapshot model (phase 3): incremental seq-prefix compaction
    // planning + the surgical seq-prefix prune of the deletion index.
    // ----------------------------------------------------------------------

    /// Build a 1-column Int64-PK provider for deletion-index seq-prefix tests.
    async fn create_int64_pk_provider(
        table_name: &str,
        runtime_env: Arc<RuntimeEnv>,
    ) -> (CayenneTableProvider, tempfile::TempDir) {
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        create_cayenne_table_with_config(
            table_name,
            schema,
            VortexConfig::default(),
            vec!["id".to_string()],
            runtime_env,
        )
        .await
    }

    /// Read the current Int64 deletion index off a provider (test-only access).
    fn int64_tombstones(provider: &CayenneTableProvider) -> Arc<DeletionIndex> {
        match provider.pk_deletion_strategy() {
            PkDeletionStrategyWithCache::Int64Pk {
                deletion_snapshot, ..
            } => Arc::clone(&deletion_snapshot.load().tombstones),
            other => panic!("expected an Int64 PK strategy, got {other:?}"),
        }
    }

    /// Install a known deletion index into a provider's Int64 cache.
    fn store_int64_tombstones(provider: &CayenneTableProvider, index: DeletionIndex) {
        match provider.pk_deletion_strategy() {
            PkDeletionStrategyWithCache::Int64Pk {
                deletion_snapshot, ..
            } => deletion_snapshot.store(Arc::new(Int64PkDeletionSnapshot::from_index(index))),
            other => panic!("expected an Int64 PK strategy, got {other:?}"),
        }
    }

    /// The surgical seq-prefix prune must drop in-memory tombstones at or below
    /// `T`, retain those above it (they still apply to the referenced-in-place
    /// files), and retain upsert re-insertion records — without wiping protected
    /// snapshots or the keyset the way `clear_all_deletion_caches` does.
    #[tokio::test]
    async fn prune_deletion_index_at_or_below_drops_baked_keeps_newer() {
        let ctx = SessionContext::new();
        let (provider, _tmp) =
            create_int64_pk_provider("seq_prefix_prune", ctx.runtime_env()).await;

        // Deletes at seqs 1,2,3,4 and an upsert conflict on key 50 (delete @2,
        // re-insert @9). Bake everything <= 2 (the seq-prefix cutoff T).
        let index = DeletionIndex::from_map(HashMap::from([(10, 1), (20, 2), (30, 3), (40, 4)]))
            .extend_max_conflicts([50_i64], 2, 9);
        store_int64_tombstones(&provider, index);
        // T is the max DELETE sequence (4), not the fused insert seq (9): insert
        // records are not deletions and never raise the seq-prefix cutoff.
        assert_eq!(
            provider.deletion_index_max_sequence(),
            Some(4),
            "T tracks the max delete sequence, ignoring re-insertion seqs"
        );

        provider.prune_deletion_index_at_or_below(2);

        let pruned = int64_tombstones(&provider);
        assert_eq!(
            pruned.get(10).map(|t| t.delete_sequence),
            None,
            "seq 1 baked"
        );
        assert_eq!(
            pruned.get(20).map(|t| t.delete_sequence),
            None,
            "seq 2 baked (boundary <=)"
        );
        assert_eq!(
            pruned.get(30).map(|t| t.delete_sequence),
            Some(3),
            "seq 3 > T survives"
        );
        assert_eq!(
            pruned.get(40).map(|t| t.delete_sequence),
            Some(4),
            "seq 4 > T survives"
        );
        // Key 50's delete (2) is baked, but its re-insertion (9 > 2) is retained,
        // so the row stays visible — the prune must not lose the insert record.
        assert_eq!(
            pruned.get(50).map(|t| t.delete_sequence),
            None,
            "delete baked"
        );
        assert_eq!(pruned.insert_len(), 1, "re-insertion record retained");
        assert_eq!(pruned.delete_len(), 2, "only the > T deletes remain");
    }

    /// On a position-based table the seq-prefix prune is a no-op (position
    /// deletions are file-scoped, not sequence-tagged) and must not panic.
    #[tokio::test]
    async fn prune_deletion_index_at_or_below_is_noop_for_position_based() {
        let ctx = SessionContext::new();
        // No primary key → position-based strategy.
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let (provider, _tmp) = create_cayenne_table_with_config(
            "seq_prefix_prune_position",
            schema,
            VortexConfig::default(),
            vec![],
            ctx.runtime_env(),
        )
        .await;
        assert!(matches!(
            provider.pk_deletion_strategy(),
            PkDeletionStrategyWithCache::PositionBased { .. }
        ));
        assert_eq!(provider.deletion_index_max_sequence(), None);
        provider.prune_deletion_index_at_or_below(5); // must not panic
    }

    /// `partition_manifest_by_sequence` splits the manifest at `T`: single-commit
    /// files (`min == max`) with sequence `<= T` are bake-eligible, files above
    /// are referenced in place. An empty (unpopulated) manifest returns `None` so
    /// the caller falls back to the full-snapshot rewrite. (The straddling
    /// merged-file case — where the `min_sequence` predicate diverges from
    /// `max_sequence` — is covered by
    /// `partition_manifest_by_sequence_bakes_straddling_merged_file`.)
    #[tokio::test]
    async fn partition_manifest_by_sequence_splits_at_cutoff() {
        let ctx = SessionContext::new();
        let (provider, _tmp) =
            create_int64_pk_provider("seq_prefix_partition", ctx.runtime_env()).await;
        let table_id = provider.table_metadata.table_id.clone();
        let snapshot_id = provider.get_current_snapshot_id();

        // Unpopulated manifest → None (full-rewrite fallback).
        assert!(
            provider
                .partition_manifest_by_sequence(&snapshot_id, 5)
                .await
                .expect("manifest read")
                .is_none(),
            "an empty manifest must yield None (no seq-prefix split is defined)"
        );

        // Populate three single-commit files (min == max) straddling T=5.
        for (name, seq) in [("a.vortex", 3_i64), ("b.vortex", 5), ("c.vortex", 8)] {
            provider
                .catalog
                .upsert_snapshot_file(&SnapshotFile {
                    table_id: table_id.clone(),
                    snapshot_id: snapshot_id.clone(),
                    file_path: name.to_string(),
                    row_count: 1,
                    file_size_bytes: 100,
                    min_sequence: seq,
                    max_sequence: seq,
                    digest: None,
                })
                .await
                .expect("upsert manifest row");
        }

        let plan = provider
            .partition_manifest_by_sequence(&snapshot_id, 5)
            .await
            .expect("manifest read")
            .expect("populated manifest yields a plan");

        let mut bake: Vec<&str> = plan.bake.iter().map(|f| f.file_path.as_str()).collect();
        let mut reference: Vec<&str> = plan
            .reference
            .iter()
            .map(|f| f.file_path.as_str())
            .collect();
        bake.sort_unstable();
        reference.sort_unstable();
        assert_eq!(
            bake,
            vec!["a.vortex", "b.vortex"],
            "min_seq <= T bakes (incl. boundary)"
        );
        assert_eq!(
            reference,
            vec!["c.vortex"],
            "min_seq > T referenced in place"
        );
    }

    /// STAGE-1 DELIVERABLE TEST (2). The corrected `min_sequence` predicate: a
    /// merged file that STRADDLES the cutoff (`min_sequence <= T < max_sequence`)
    /// MUST be BAKED, never referenced in place. It holds rows at or below `T`,
    /// so referencing it would let the post-commit
    /// `prune_deletion_index_at_or_below(T)` drop a `<= T` tombstone that still
    /// applies to those rows — resurrecting deleted rows. The prior
    /// `max_sequence <= T` predicate put this file in `reference` (the bug).
    #[tokio::test]
    async fn partition_manifest_by_sequence_bakes_straddling_merged_file() {
        let ctx = SessionContext::new();
        let (provider, _tmp) =
            create_int64_pk_provider("seq_prefix_straddle", ctx.runtime_env()).await;
        let table_id = provider.table_metadata.table_id.clone();
        let snapshot_id = provider.get_current_snapshot_id();

        // T = 5. Three files:
        //   merged_straddle: [2, 8]  — min <= 5 < max  ⇒ MUST bake
        //   below:           [1, 4]  — entirely <= 5    ⇒ bake
        //   above:           [6, 9]  — entirely  > 5    ⇒ reference
        for (name, min_seq, max_seq) in [
            ("merged_straddle.vortex", 2_i64, 8_i64),
            ("below.vortex", 1, 4),
            ("above.vortex", 6, 9),
        ] {
            provider
                .catalog
                .upsert_snapshot_file(&SnapshotFile {
                    table_id: table_id.clone(),
                    snapshot_id: snapshot_id.clone(),
                    file_path: name.to_string(),
                    row_count: 1,
                    file_size_bytes: 100,
                    min_sequence: min_seq,
                    max_sequence: max_seq,
                    digest: None,
                })
                .await
                .expect("upsert manifest row");
        }

        let plan = provider
            .partition_manifest_by_sequence(&snapshot_id, 5)
            .await
            .expect("manifest read")
            .expect("populated manifest yields a plan");

        let mut bake: Vec<&str> = plan.bake.iter().map(|f| f.file_path.as_str()).collect();
        let reference: Vec<&str> = plan
            .reference
            .iter()
            .map(|f| f.file_path.as_str())
            .collect();
        bake.sort_unstable();

        assert_eq!(
            bake,
            vec!["below.vortex", "merged_straddle.vortex"],
            "a file straddling T (min_sequence <= T < max_sequence) MUST bake — \
             the resurrect-rows-critical fix vs the old max_sequence predicate"
        );
        assert_eq!(
            reference,
            vec!["above.vortex"],
            "only a file entirely above T (min_sequence > T) is referenced in place"
        );
    }

    // ========================================================================
    // STAGE 2 — seq-prefix BAKE (resurrect-rows-critical). These five tests
    // exercise `bake_seq_prefix_protected_snapshots` end-to-end on a key-mode
    // upsert table: real protected snapshots backed by real Vortex files, with
    // each snapshot's per-file manifest sequence range PINNED via
    // `upsert_snapshot_file` so the seq-prefix cutoff `T` is deterministic
    // (independent of the write path's auto-assigned reservation sequences).
    // ========================================================================

    /// Build a key-mode (`deletion_mode: Key`) file-backed upsert table holding
    /// `n` protected snapshots, one row each (id = 0..n), and PIN each protected
    /// snapshot's manifest file range to `[seq_i, seq_i]` where `seq_i` is the
    /// i-th value of `seqs` (creation order = ascending protected-snapshot id).
    /// Returns the provider, the temp dir (kept alive), and the protected
    /// snapshot ids in creation (sequence) order.
    ///
    /// The pin keeps the seq-prefix cutoff deterministic: selection reads these
    /// manifest `max_sequence` values, not the write path's reserved sequences.
    async fn build_seq_prefix_fixture(
        table_name: &str,
        runtime_env: Arc<RuntimeEnv>,
        seqs: &[i64],
    ) -> (CayenneTableProvider, TempDir, Vec<String>) {
        build_seq_prefix_fixture_with_config(
            table_name,
            runtime_env,
            seqs,
            VortexConfig {
                inline_max_rows: 0,
                deletion_mode: crate::metadata::DeletionMode::Key,
                ..VortexConfig::default()
            },
        )
        .await
    }

    /// Like [`build_seq_prefix_fixture`] but with a caller-supplied `VortexConfig`,
    /// so a test can floor the trigger thresholds and drive the bake AND the
    /// size-tier leveler from a single `run_compaction_trigger` tick.
    async fn build_seq_prefix_fixture_with_config(
        table_name: &str,
        runtime_env: Arc<RuntimeEnv>,
        seqs: &[i64],
        vortex_config: VortexConfig,
    ) -> (CayenneTableProvider, TempDir, Vec<String>) {
        use arrow::datatypes::{DataType, Field, Schema};
        let (provider, _catalog, tmp) =
            create_cdc_upsert_table_with_vortex_config(table_name, runtime_env, vortex_config)
                .await;
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));

        // Hold the compaction lock across the WHOLE fixture (inserts → pin) so the
        // async write-driven lanes can never corrupt the synthetic state. Each CDC
        // insert schedules a debounced (~100 ms) post-write maintenance pass; when
        // it fires it (a) rebuilds every live snapshot's manifest from the
        // directory listing — overwriting the synthetic `[seq, seq]` ranges pinned
        // below with the reserved sequences — and (b) when the protected-snapshot
        // trigger is armed (the low-trigger fixtures), schedules an async size-tier
        // compaction that MERGES the very snapshots the test sets up. Under
        // parallel test load that pass fires mid-fixture/mid-test: the merge holds
        // this lock (so the test's own bake/leveler `try_lock` returns false) or
        // reduces the protected count — the observed flakiness. Both the rebuild
        // and the merge `try_lock` this lock, so holding it across the fixture
        // makes every such pass a no-op skip, and `flush_pending_maintenance` below
        // drains the loop so it exits rather than firing after we release. (The
        // write path never takes this lock, so holding it across the inserts is
        // safe.)
        let compaction_guard = provider.compaction_lock.lock().await;

        // Each distinct-key insert publishes its own file-backed protected
        // snapshot (inline disabled in the fixture).
        for (i, _) in seqs.iter().enumerate() {
            let id = i64::try_from(i).expect("row index fits i64");
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[id], &[id * 10]),
            )
            .await;
        }

        // Drain the debounced maintenance loop the inserts spawned: it skips its
        // manifest rebuild and any compaction it scheduled (we hold the lock), then
        // exits — so nothing fires against the pinned manifest after we release the
        // guard on return.
        provider
            .flush_pending_maintenance()
            .await
            .expect("drain pending post-write maintenance");

        // Protected-snapshot registration can lag behind the awaited inserts under heavy
        // parallel load (seen in CI: 6 expected, only 2 registered on an immediate read;
        // always all N locally). The snapshots are never coalesced away — they all appear
        // given a moment — so poll until the expected count is reached (bounded ~5s) before
        // asserting, keeping the fixture deterministic under load instead of racing the
        // background registration.
        let mut ids: Vec<String> = Vec::new();
        for _ in 0..100 {
            ids = provider
                .protected_snapshots
                .load_full()
                .keys()
                .cloned()
                .collect();
            if ids.len() >= seqs.len() {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        ids.sort();
        assert_eq!(
            ids.len(),
            seqs.len(),
            "fixture must produce one protected snapshot per seq ({} expected, got {})",
            seqs.len(),
            ids.len()
        );

        // Populate every live snapshot's manifest (we hold the compaction lock the
        // real post-write lane takes), then OVERWRITE with the pinned ranges.
        provider.rebuild_live_snapshot_manifests().await;

        let table_id = provider.table_metadata.table_id.clone();
        for (id, &seq) in ids.iter().zip(seqs.iter()) {
            let files = provider
                .list_snapshot_files_with_sizes(id)
                .await
                .expect("list snapshot files");
            assert!(
                !files.is_empty(),
                "protected snapshot {id} must have a data file to pin"
            );
            for (file_name, size) in files {
                provider
                    .catalog
                    .upsert_snapshot_file(&SnapshotFile {
                        table_id: table_id.clone(),
                        snapshot_id: id.clone(),
                        file_path: file_name,
                        row_count: 1,
                        file_size_bytes: i64::try_from(size).unwrap_or(0),
                        min_sequence: seq,
                        max_sequence: seq,
                        digest: None,
                    })
                    .await
                    .expect("pin manifest sequence");
            }
        }

        // Release the compaction lock now that the manifest is pinned. The async
        // lanes are drained (the maintenance loop exited; any compaction it
        // scheduled `try_lock`-skipped while we held the lock), so the pinned state
        // is stable for the test's own bake/leveler calls.
        drop(compaction_guard);
        (provider, tmp, ids)
    }

    /// Install a known Int64 deletion index (delete-only entries) onto a provider.
    fn install_int64_deletes(provider: &CayenneTableProvider, deletes: &[(i64, i64)]) {
        let index = DeletionIndex::from_map(deletes.iter().copied().collect::<HashMap<i64, i64>>());
        store_int64_tombstones(provider, index);
    }

    /// STAGE-2 DELIVERABLE TEST (1). After a bake, a tombstone with
    /// `delete_seq <= T` is GONE from the index AND the deleted row stays deleted
    /// on scan. Five snapshots (ids 0..5) pinned at seqs 10,20,30,40,50; K = 3 is
    /// kept unbaked, so the older prefix is {0,1} with `T = 20`. Key 0 (written at
    /// 10) is deleted at `delete_seq` 15 (<= T) — the bake must physically remove it
    /// and drop the tombstone; key 1 (written at 20) is NOT deleted and survives.
    #[tokio::test]
    async fn seq_prefix_bake_drops_baked_tombstone_and_keeps_row_deleted() {
        let ctx = SessionContext::new();
        let (provider, _tmp, _ids) = build_seq_prefix_fixture(
            "bake_drops_tombstone",
            ctx.runtime_env(),
            &[10, 20, 30, 40, 50],
        )
        .await;

        // Delete key 0 at delete_seq 15 (<= T=20, in the older prefix's snapshot).
        install_int64_deletes(&provider, &[(0, 15)]);
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "bake_drops_tombstone").await,
            vec![(1, 10), (2, 20), (3, 30), (4, 40)],
            "precondition: key 0 hidden by its tombstone before the bake"
        );

        let baked = provider
            .bake_seq_prefix_protected_snapshots()
            .await
            .expect("bake should not error");
        assert!(baked, "the older prefix {{0,1}} must bake (>= 2 snapshots)");

        // The tombstone for key 0 (delete_seq 15 <= T=20) is gone from the index.
        let tombstones = int64_tombstones(&provider);
        assert_eq!(
            tombstones.get(0).map(|t| t.delete_sequence),
            None,
            "the <= T tombstone must be pruned after the bake"
        );
        assert_eq!(
            tombstones.delete_len(),
            0,
            "no live tombstones remain (the only delete was <= T)"
        );

        // Key 0's row stays physically deleted (the merge applied the delete);
        // every other row is still present.
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "bake_drops_tombstone").await,
            vec![(1, 10), (2, 20), (3, 30), (4, 40)],
            "key 0 stays deleted after the bake (no resurrection), others preserved"
        );
    }

    /// OVERWRITE-GUARD regression (issue #11823), bake flavor — sibling of
    /// `subset_compaction_discards_output_when_snapshot_replaced_mid_pass`: an
    /// overwrite committing between the bake's catalog CAS and its fenced
    /// in-memory publish must make the bake discard its merged output (and skip
    /// the deletion-index prune) instead of resurrecting the pre-overwrite rows
    /// into the emptied protected map.
    #[tokio::test]
    async fn seq_prefix_bake_discards_output_when_snapshot_replaced_mid_pass() {
        let ctx = SessionContext::new();
        let (provider, _tmp, _ids) = build_seq_prefix_fixture(
            "bake_mid_pass_overwrite",
            ctx.runtime_env(),
            &[10, 20, 30, 40, 50],
        )
        .await;
        // A `<= T` tombstone so the bake has prune work it must then abandon.
        install_int64_deletes(&provider, &[(0, 15)]);

        let overwrite_snapshot_id = uuid::Uuid::now_v7().to_string();
        std::fs::create_dir_all(provider.snapshot_dir_path_for(&overwrite_snapshot_id))
            .expect("create empty overwrite snapshot dir");
        let hook_fired = Arc::new(std::sync::atomic::AtomicBool::new(false));
        {
            let provider_in_hook = provider.clone_for_write();
            let overwrite_id = overwrite_snapshot_id.clone();
            let fired = Arc::clone(&hook_fired);
            *provider.test_pre_publish_hook.lock() = Some(Box::new(move || {
                Box::pin(async move {
                    provider_in_hook
                        .publish_overwrite_snapshot(&overwrite_id, None)
                        .await
                        .expect("mid-pass overwrite publish");
                    fired.store(true, Ordering::SeqCst);
                })
            }));
        }

        let baked = provider
            .bake_seq_prefix_protected_snapshots()
            .await
            .expect("bake must not error when the guard fires");
        assert!(
            hook_fired.load(Ordering::SeqCst),
            "the bake must reach the post-CAS window (mid-pass hook consumed)"
        );
        assert!(
            !baked,
            "the guard must report no bake when the snapshot was replaced mid-pass"
        );

        assert!(
            provider.protected_snapshots.load_full().is_empty(),
            "guard must not publish the baked snapshot into the overwrite-emptied protected map"
        );
        assert_eq!(
            provider.get_current_snapshot_id(),
            overwrite_snapshot_id,
            "the overwrite's snapshot flip must stand"
        );
        // Resurrection check: only the overwrite's (empty) data is visible — a
        // broken guard would surface the pre-overwrite fixture rows here.
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "bake_mid_pass_overwrite").await,
            Vec::<(i64, i64)>::new(),
            "no pre-overwrite rows may survive the mid-pass overwrite"
        );
    }

    /// STAGE-2 DELIVERABLE TEST (2). A row written `<= T`, deleted `<= T`, then
    /// RE-INSERTED at `> T` is PRESENT after the bake — the `> T` version must
    /// survive (not dropped as part of the bake, not resurrected-as-deleted).
    ///
    /// End-to-end through the real upsert path (no synthetic state), so the
    /// re-insert lands in a genuine newer protected snapshot whose deletion
    /// threshold the engine itself assigns `>= ` the old row's delete sequence —
    /// the production mechanism by which the re-inserted copy stays visible while
    /// the old copy is hidden (protected-snapshot scans IGNORE the re-insert
    /// marker; visibility comes from the newer snapshot's threshold).
    ///
    /// Sequence of events:
    /// 1. Insert key 100 (value 1) — the OLD copy, in the OLDEST snapshot.
    /// 2. Insert keys 1,2,3,4 — four more snapshots.
    /// 3. Re-insert key 100 (value 999) — a real upsert: writes a tombstone for
    ///    key 100 at some `delete_seq D` and publishes a NEW snapshot (the
    ///    SURVIVOR) whose threshold the engine assigns `>= D`.
    ///
    /// Six protected snapshots; K = 3 kept. The older prefix is the OLDEST three
    /// (the OLD-100 snapshot + keys 1,2). We pin the older prefix's manifest so
    /// `T = D` and pin the kept snapshots `> D`, so the SURVIVOR (newest) is
    /// referenced in place. After the bake: the OLD-100 copy is physically removed
    /// (the merge applied the `D > old-snapshot-threshold` delete), the `<= T = D`
    /// tombstone is pruned, and the SURVIVOR (999) still scans — key 100 present
    /// exactly once at its re-inserted value.
    #[tokio::test]
    async fn seq_prefix_bake_keeps_reinserted_row_above_cutoff() {
        let ctx = SessionContext::new();
        let (provider, _catalog, _tmp) =
            create_cdc_upsert_table("bake_keeps_reinsert", ctx.runtime_env()).await;
        let schema = Arc::clone(&provider.table_metadata.schema);
        let table_id = provider.table_metadata.table_id.clone();

        // (1) OLD copy of key 100 (value 1) → oldest snapshot.
        insert_batch(&provider, id_value_batch(Arc::clone(&schema), &[100], &[1])).await;
        // (2) four more distinct-key snapshots.
        for id in 1..=4_i64 {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[id], &[id * 10]),
            )
            .await;
        }
        // (3) Re-insert key 100 (value 999): a real upsert → tombstone for key 100
        // + a new SURVIVOR snapshot whose threshold the engine assigns >= delete.
        insert_batch(
            &provider,
            id_value_batch(Arc::clone(&schema), &[100], &[999]),
        )
        .await;

        // The engine assigned the tombstone a delete sequence; T must be >= it.
        let delete_seq = provider
            .deletion_index_max_sequence()
            .expect("the re-insert recorded a tombstone with a delete sequence");

        // Precondition: exactly the re-inserted copy (999) of key 100 is visible.
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "bake_keeps_reinsert")
                .await
                .into_iter()
                .filter(|(id, _)| *id == 100)
                .collect::<Vec<_>>(),
            vec![(100, 999)],
            "precondition: re-insert hides the old copy, only value 999 visible"
        );

        // Quiesce the detached post-write maintenance the inserts above scheduled
        // (the manifest rebuild grabs `compaction_lock` — see the post-write path)
        // BEFORE we pin manifests, so it cannot (a) hold the lock out from under the
        // bake's best-effort `try_lock` nor (b) run a listing rebuild that overwrites
        // the pins we set below. Drain must precede pinning — never inside the retry.
        provider
            .drain_in_flight_maintenance()
            .await
            .expect("drain in-flight maintenance before pinning manifests");

        // Populate manifests, then PIN them: older prefix (oldest 3) at `T = D`,
        // kept snapshots (newest 3, incl. the SURVIVOR) strictly above `D`, so the
        // SURVIVOR is referenced in place and the OLD-100 snapshot is baked.
        {
            let _guard = provider.compaction_lock.lock().await;
            provider.rebuild_live_snapshot_manifests().await;
        }
        let mut ids: Vec<String> = provider
            .protected_snapshots
            .load_full()
            .keys()
            .cloned()
            .collect();
        ids.sort();
        assert_eq!(
            ids.len(),
            6,
            "5 distinct inserts + 1 re-insert = 6 snapshots"
        );
        // Older prefix = oldest 3 → pin max_sequence = D (so T = D >= delete_seq).
        // Kept = newest 3 → pin min_sequence = D + 10 (> T).
        for (i, id) in ids.iter().enumerate() {
            let seq = if i < 3 { delete_seq } else { delete_seq + 10 };
            let files = provider
                .list_snapshot_files_with_sizes(id)
                .await
                .expect("list snapshot files");
            for (file_name, size) in files {
                provider
                    .catalog
                    .upsert_snapshot_file(&SnapshotFile {
                        table_id: table_id.clone(),
                        snapshot_id: id.clone(),
                        file_path: file_name,
                        row_count: 1,
                        file_size_bytes: i64::try_from(size).unwrap_or(0),
                        min_sequence: seq,
                        max_sequence: seq,
                        digest: None,
                    })
                    .await
                    .expect("pin manifest sequence");
            }
        }

        // Best-effort bake, driven the way the production maintenance tick drives
        // it: `bake_seq_prefix_protected_snapshots` `try_lock`s `compaction_lock` and
        // returns `Ok(false)` when it loses (a straggler pass still releasing after
        // the drain), which the tick simply retries next time. Mirror that with a
        // bounded retry — yielding (not sleeping) so any lock holder makes progress —
        // rather than asserting a single call wins the race. We do NOT re-drain in
        // the loop: a second drain would run a listing rebuild that clobbers the pins.
        let mut baked = false;
        for _ in 0..5 {
            if provider
                .bake_seq_prefix_protected_snapshots()
                .await
                .expect("bake should not error")
            {
                baked = true;
                break;
            }
            tokio::task::yield_now().await;
        }
        assert!(baked, "older prefix must bake within the bounded retry");

        // The <= T (= D) delete of key 100 is pruned from the index.
        let tombstones = int64_tombstones(&provider);
        assert_eq!(
            tombstones.get(100).map(|t| t.delete_sequence),
            None,
            "the <= T delete of key 100 is pruned after the bake"
        );

        // Key 100 present exactly once, as its re-inserted (> T) value 999 —
        // neither dropped (the > T survivor was referenced in place) nor
        // resurrected-as-deleted (the prune did not change the survivor's
        // visibility, and the old copy stays physically gone).
        let key100: Vec<(i64, i64)> =
            collect_id_value_pairs(&ctx, &provider, "bake_keeps_reinsert")
                .await
                .into_iter()
                .filter(|(id, _)| *id == 100)
                .collect();
        assert_eq!(
            key100,
            vec![(100, 999)],
            "key 100 present exactly once as its re-inserted > T value 999, got {key100:?}"
        );
    }

    /// #12013 companion for the other path that unions protected snapshots: the
    /// seq-prefix bake selects an entire older prefix with no size tiers, so an
    /// unbounded prefix of large runs is the same OOM. Under a finite pool the prefix
    /// is truncated to what fits the per-pass budget; here nothing fits, so the bake
    /// declines. `seq_prefix_bake_leaves_above_cutoff_snapshots_readable` is the
    /// unbounded-pool control on the same fixture.
    #[tokio::test]
    async fn seq_prefix_bake_declines_when_the_prefix_exceeds_the_pass_memory_budget() {
        use datafusion::execution::memory_pool::GreedyMemoryPool;
        use datafusion_execution::runtime_env::RuntimeEnvBuilder;

        // 4× this is the per-pass budget: far below one Vortex snapshot, checked as a
        // precondition below.
        const POOL_BYTES: usize = 512;

        let ctx = SessionContext::new();
        let finite_rt = Arc::new(
            RuntimeEnvBuilder::new()
                .with_memory_pool(Arc::new(GreedyMemoryPool::new(POOL_BYTES)))
                .build()
                .expect("finite-pool runtime env"),
        );
        let (provider, _tmp, _ids) =
            build_seq_prefix_fixture("bake_budget_finite", finite_rt, &[10, 20, 30, 40, 50]).await;
        let before = provider.protected_snapshots.load_full();

        let budget = provider
            .protected_merge_input_budget_bytes()
            .expect("a finite pool must yield a budget");
        let mut smallest = u64::MAX;
        for id in before.keys() {
            let bytes: u64 = provider
                .list_snapshot_files_with_sizes(id)
                .await
                .expect("list snapshot files")
                .iter()
                .map(|(_, sz)| *sz)
                .sum();
            smallest = smallest.min(bytes);
        }
        assert!(
            smallest > budget,
            "precondition: the smallest run ({smallest} B) must exceed the {budget} B \
             pass budget; lower POOL_BYTES"
        );

        assert!(
            !provider
                .bake_seq_prefix_protected_snapshots()
                .await
                .expect("a declined bake is a no-op, never an error"),
            "the bake must decline: no two prefix snapshots fit the {budget} B budget"
        );
        assert_eq!(
            provider.protected_snapshots.load_full().len(),
            before.len(),
            "a declined bake must leave the protected set untouched"
        );
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "bake_budget_finite").await,
            vec![(0, 0), (1, 10), (2, 20), (3, 30), (4, 40)],
            "declining must never lose rows"
        );
    }

    /// STAGE-2 DELIVERABLE TEST (3). A `> T` snapshot's rows remain readable after
    /// the bake — the scan union still reads the untouched (referenced-in-place)
    /// snapshots. Five snapshots 0..5 at 10,20,30,40,50; older prefix {0,1}
    /// (T=20) bakes; snapshots 2,3,4 (seqs 30,40,50 > T) are left untouched and
    /// their rows (ids 2,3,4) must still scan.
    #[tokio::test]
    async fn seq_prefix_bake_leaves_above_cutoff_snapshots_readable() {
        let ctx = SessionContext::new();
        let (provider, _tmp, ids) =
            build_seq_prefix_fixture("bake_keeps_above", ctx.runtime_env(), &[10, 20, 30, 40, 50])
                .await;
        let before: std::collections::HashSet<String> = provider
            .protected_snapshots
            .load_full()
            .keys()
            .cloned()
            .collect();

        // No deletes at all — pure structural check that the bake merges the
        // older prefix and the > T snapshots survive untouched.
        let baked = provider
            .bake_seq_prefix_protected_snapshots()
            .await
            .expect("bake should not error");
        assert!(baked, "older prefix {{0,1}} bakes");

        // The newest K=3 snapshots (ids[2..5]) are still present (untouched).
        let after = provider.protected_snapshots.load_full();
        for kept in &ids[2..] {
            assert!(
                after.contains_key(kept),
                "referenced-in-place snapshot {kept} (min_sequence > T) must be untouched"
            );
        }
        // The two baked inputs are gone, replaced by one merged snapshot.
        assert!(
            !after.contains_key(&ids[0]) && !after.contains_key(&ids[1]),
            "the baked inputs must be retired from the protected set"
        );
        assert!(
            after.len() < before.len(),
            "the bake reduces the protected-snapshot count: {} -> {}",
            before.len(),
            after.len()
        );

        // Every row still scans (the union reads M ∪ the untouched > T snapshots).
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "bake_keeps_above").await,
            vec![(0, 0), (1, 10), (2, 20), (3, 30), (4, 40)],
            "all rows readable after the bake — untouched > T snapshots included"
        );
    }

    /// STAGE-2 DELIVERABLE TEST (4). The bake is a NO-OP on a position-delete
    /// table: `should_capture_positions()` is true (default `auto` resolves to
    /// position for a PK table), so the seq-prefix bake returns `Ok(false)`
    /// without merging — even with enough protected snapshots to otherwise bake.
    #[tokio::test]
    async fn seq_prefix_bake_is_noop_on_position_delete_table() {
        use arrow::datatypes::{DataType, Field, Schema};
        let ctx = SessionContext::new();
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let metadata_dir = format!("{}/metadata", temp_dir.path().to_str().expect("str path"));
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("str path"));
        std::fs::create_dir_all(&metadata_dir).expect("metadata dir created");
        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let options = CreateTableOptions {
            table_name: "bake_noop_position".to_string(),
            schema: Arc::clone(&schema),
            primary_key: vec!["id".to_string()],
            on_conflict: Some(OnConflict::Upsert(
                datafusion_table_providers::util::column_reference::ColumnReference::new(vec![
                    "id".to_string(),
                ]),
            )),
            base_path: data_dir,
            partition_column: None,
            vortex_config: VortexConfig {
                inline_max_rows: 0,
                // Default deletion mode left as auto → resolves to POSITION for a
                // PK table, which the bake gate must skip.
                compaction_background_interval_ms: 3_600_000,
                ..VortexConfig::default()
            },
        };
        let provider = CayenneTableProviderBuilder::new(Arc::clone(&catalog), ctx.runtime_env())
            .create(options)
            .await
            .expect("table created");
        assert!(
            provider.should_capture_positions(),
            "fixture must resolve to position mode or this test pins nothing"
        );

        // Enough distinct-key inserts to clear the K+2 floor if it were key-mode.
        for id in 0..6_i64 {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[id], &[id * 10]),
            )
            .await;
        }
        {
            let _guard = provider.compaction_lock.lock().await;
            provider.rebuild_live_snapshot_manifests().await;
        }
        let before = provider.protected_snapshots.load_full().len();

        let baked = provider
            .bake_seq_prefix_protected_snapshots()
            .await
            .expect("bake should not error");
        assert!(
            !baked,
            "the seq-prefix bake must be a no-op on a position-delete table"
        );
        assert_eq!(
            provider.protected_snapshots.load_full().len(),
            before,
            "a position-mode bake must not touch the protected set"
        );
    }

    /// STAGE-2 DELIVERABLE TEST (5). The clean-prefix gate SKIPS THE WHOLE BAKE
    /// (no merge, no prune, no write-amp) when a genuinely-dirty `<= T` snapshot
    /// would be left unmerged. We pin the OLDER prefix to bake at `T`, but pin one
    /// of the KEPT (newest-K) snapshots with `min_sequence <= T` AND a delete-
    /// watermark `< T` — so it is neither write-range-clean nor watermark-exempt, a
    /// true violation. The PRE-merge gate detects it and returns early: no merge
    /// write-amp is paid for a prune that would be withheld, and the `<= T`
    /// tombstone is retained (resurrect-safe).
    #[tokio::test]
    async fn seq_prefix_bake_skips_prune_when_clean_prefix_violated() {
        let ctx = SessionContext::new();
        // Older prefix {0,1} pinned at 10,20 ⇒ T=20. Kept snapshots {2,3,4}:
        // pin id-2 at seq 5 (< T=20) to VIOLATE the clean prefix; ids 3,4 are
        // above T (30,40). The violating kept snapshot id-2 makes the post-swap
        // live set contain a min_sequence (5) <= T.
        let (provider, _tmp, ids) =
            build_seq_prefix_fixture("bake_skips_prune", ctx.runtime_env(), &[10, 20, 5, 30, 40])
                .await;

        // Pin kept id-2's delete-watermark to 5 (< T=20) so it is genuinely dirty:
        // neither write-range-clean (min_sequence 5 <= T) nor watermark-exempt
        // (5 < T). This makes the violation deterministic regardless of the small
        // real sequence the fixture's inserts happened to allocate.
        let dirty_kept = ids[2].clone();
        provider.protected_snapshots.rcu(|cur| {
            let mut m = (**cur).clone();
            m.insert(dirty_kept.clone(), 5);
            Arc::new(m)
        });

        // A tombstone at delete_seq 12 (<= T=20). Were the prune to run it would
        // be dropped, but key 2 (written at 5 <= 12) physically survives in the
        // unmerged kept snapshot id-2 → dropping the tombstone would resurrect it.
        install_int64_deletes(&provider, &[(2, 12)]);

        let before = provider.protected_snapshots.load_full().len();
        let baked = provider
            .bake_seq_prefix_protected_snapshots()
            .await
            .expect("bake should not error");
        assert!(
            !baked,
            "the bake skips ENTIRELY (no merge, no write-amp) when the prune would be withheld"
        );
        assert_eq!(
            provider.protected_snapshots.load_full().len(),
            before,
            "the violated bake must not merge/swap (the older prefix stays live)"
        );

        // The tombstone MUST survive (prune skipped) — clean-prefix violated.
        let tombstones = int64_tombstones(&provider);
        assert_eq!(
            tombstones.get(2).map(|t| t.delete_sequence),
            Some(12),
            "the <= T tombstone must be RETAINED when a kept snapshot still has min_sequence <= T"
        );
        assert_eq!(
            tombstones.delete_len(),
            1,
            "no tombstone was pruned under the violated clean-prefix invariant"
        );
        // Key 2 stays hidden (its surviving tombstone still applies) — no
        // resurrection despite the kept <= T snapshot.
        let pairs = collect_id_value_pairs(&ctx, &provider, "bake_skips_prune").await;
        assert!(
            !pairs.iter().any(|(id, _)| *id == 2),
            "key 2 stays deleted (tombstone retained) — no resurrection, got {pairs:?}"
        );
    }

    /// Regression (SF-100 tuned-memory bootstrap over-count). The SCAN-side DUAL of
    /// `seq_prefix_bake_skips_prune_when_clean_prefix_violated`: that test proves the
    /// PRUNE must RETAIN a `<= T` tombstone when a kept snapshot physically holds the
    /// row; this proves the protected-snapshot SCAN must likewise APPLY it.
    ///
    /// A protected snapshot pinned at a HIGH threshold (40) still references a row
    /// written at a LOW real sequence — the un-rewritten base/bootstrap file whose
    /// deletions were never physically baked out. A tombstone at `delete_seq=20`
    /// genuinely deletes that row (20 > its insert seq), but the protected-snapshot
    /// scan's `tombstone_visible` first branch SKIPS it because `20 <= 40` (it
    /// assumes every `<= threshold` deletion is already baked into the snapshot's
    /// files). It is NOT baked, so skipping RESURRECTS the deleted row — the exact
    /// durable over-count seen in production (the bootstrap row surviving its first
    /// update: instrumented run showed `delete_seq=30 min=32 handling=Ignore`). A
    /// correct scan keeps the deleted key hidden.
    #[ignore = "known-failing guard: reproduces the unfixed SF-100 protected-snapshot \
                scan-skip over-count (a delete_seq <= threshold tombstone is skipped on a \
                file whose rows were never baked out to that threshold). Un-ignore with the fix."]
    #[tokio::test]
    async fn protected_snapshot_scan_applies_unbaked_le_threshold_tombstone_no_resurrect() {
        let ctx = SessionContext::new();
        let (provider, _tmp, ids) =
            build_seq_prefix_fixture("scan_skip_leak", ctx.runtime_env(), &[10, 10, 10]).await;

        // Pin id-0 at threshold 40. Its row was inserted at a small real sequence and
        // is NOT physically removed — the snapshot merely CLAIMS "all deletions <= 40
        // are baked in".
        let pinned = ids[0].clone();
        provider.protected_snapshots.rcu(|cur| {
            let mut m = (**cur).clone();
            m.insert(pinned.clone(), 40);
            Arc::new(m)
        });

        // (0,20): the leak — delete_seq 20 is ABOVE key 0's insert seq (a genuine
        //         delete of the physically-present row) but `<= 40`, so the
        //         protected-snapshot scan skips it.
        // (2,50): raises the deletion index's max_sequence above 40 so the filter is
        //         actually APPLIED to id-0's scan (otherwise it short-circuits at
        //         `max_sequence <= min_delete_seq`), forcing the per-row
        //         `tombstone_visible` skip the production run exhibited.
        install_int64_deletes(&provider, &[(0, 20), (2, 50)]);

        let pairs = collect_id_value_pairs(&ctx, &provider, "scan_skip_leak").await;
        assert!(
            !pairs.iter().any(|(id, _)| *id == 0),
            "key 0 (deleted at seq 20 > its insert seq) was RESURRECTED by the \
             protected-snapshot scan skip (delete_seq 20 <= threshold 40); the row is \
             not baked out of the snapshot's file: {pairs:?}"
        );
    }

    /// A protected-snapshot merge fence is CAPPED strictly below the smallest
    /// still-pending mem-tier delete, so a delete that reordered below the durable
    /// index max (a later apply folded ahead of it) is never tagged as
    /// already-baked — the SF-100 N=4 `order_line` +14.9M over-count. The uncapped
    /// durable max would skip such a delete at scan forever and resurrect the row.
    /// No under-count: the pending `(delete, data)` pair is one atomic apply, so
    /// the reinsert is also pending (never in the merged durable files) — lowering
    /// the fence only applies more deletes to old rows.
    #[tokio::test]
    async fn protected_snapshot_merge_fence_caps_below_pending_mem_tier_delete() {
        let ctx = SessionContext::new();
        let (provider, _tmp, _ids) =
            build_seq_prefix_fixture("merge_fence_cap", ctx.runtime_env(), &[10, 20]).await;

        // No pending mem-tier delete yet: the fence is the durable max unchanged.
        assert_eq!(provider.min_pending_mem_tier_delete_sequence(), None);
        assert_eq!(
            provider.protected_snapshot_merge_fence_and_floor(32),
            (32, None)
        );

        // Durable deletion index max = 32 (a later apply's delete folded ahead).
        install_int64_deletes(&provider, &[(999, 32)]);
        assert_eq!(provider.deletion_index_max_sequence(), Some(32));

        // A delete for key 0 (its reinsert row is data@31) is STILL PENDING in the
        // mem tier at delete_seq 30 — reordered below the durable max. Append it as
        // one atomic apply segment (empty batches: only the tombstone matters here).
        let mut seg = crate::provider::mem_tier::SegmentTombstones::from_int64_keys([0_i64]);
        seg.stamp(30);
        let cur = provider.mem_tier.shard(0).load();
        let next = cur.append_segment(Arc::new(vec![]), 31, seg, 0, 0, 0);
        provider.mem_tier.shard(0).store(Arc::new(next));

        assert_eq!(
            provider.min_pending_mem_tier_delete_sequence(),
            Some(30),
            "the pending floor is the mem-tier delete, below the durable max"
        );
        // The fence must NOT reach the durable max (32) — that would skip delete@30
        // forever. It caps strictly below the pending floor.
        assert_eq!(
            provider.protected_snapshot_merge_fence_and_floor(32),
            (29, Some(30)),
            "fence caps strictly below the pending mem-tier delete (30), not the durable max (32)"
        );
        // When the durable max is already below the pending floor there is no
        // reorder gap, so the fence stays the durable max (no needless re-apply).
        assert_eq!(
            provider.protected_snapshot_merge_fence_and_floor(10),
            (10, Some(30))
        );
    }

    /// REGRESSION (hot-key live-row vanish): the fast subset compaction must not
    /// fold a protected snapshot whose merge-on-read threshold exceeds the pass's
    /// delete fence. When a pending mem-tier delete caps the fence below
    /// already-durable supersede tombstones (the steady state for a CDC table
    /// between checkpoints), folding the NEWEST snapshot — the only live version
    /// of a hot upsert key — retags its rows at the fence; scans then re-apply
    /// the `(fence, tombstone]` supersede deletes to the merged output and the
    /// live row vanishes until the next commit publishes a fresher snapshot.
    /// Observed end-to-end as transiently-empty point reads on a write-back CDC
    /// table, which the durable write-back delivery worker escalated into
    /// source-row DELETEs.
    #[tokio::test]
    async fn subset_compaction_excludes_inputs_above_delete_fence() {
        use arrow::datatypes::{DataType, Field, Schema};

        let ctx = SessionContext::new();
        let (provider, _catalog, _tmp) = create_cdc_upsert_table_with_vortex_config(
            "subset_fence_exclusion",
            ctx.runtime_env(),
            VortexConfig {
                inline_max_rows: 0,
                deletion_mode: crate::metadata::DeletionMode::Key,
                compaction_trigger_protected_snapshots: 2,
                ..VortexConfig::default()
            },
        )
        .await;
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));

        // Hold the compaction lock across setup so the debounced post-write pass
        // cannot merge the snapshots this test arranges (same rationale as
        // `build_seq_prefix_fixture`).
        let setup_guard = provider.compaction_lock.lock().await;
        // Three upserts of ONE key: each publishes its own protected snapshot,
        // and the second/third durably record a supersede key-delete for the
        // prior version — the hot-key shape of a CDC write-back counter.
        for value in [10_i64, 20, 30] {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[1], &[value]),
            )
            .await;
        }
        provider
            .flush_pending_maintenance()
            .await
            .expect("drain pending post-write maintenance");
        drop(setup_guard);

        // Bounded poll: protected-snapshot registration can lag the awaited
        // inserts under parallel test load (see `build_seq_prefix_fixture`).
        let mut protected_count = 0;
        for _ in 0..100 {
            protected_count = provider.protected_snapshots.load_full().len();
            if protected_count >= 3 {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        assert_eq!(protected_count, 3, "one protected snapshot per upsert");

        let durable_max = provider
            .deletion_index_max_sequence()
            .expect("the supersede deletes are durable");

        // Plant a PENDING mem-tier tombstone (unrelated key) at the durable max:
        // the merge fence caps strictly below it, i.e. below the newest durable
        // supersede delete — the steady state for a CDC table between
        // checkpoints (echo applies keep un-checkpointed deletes in RAM).
        let mut seg = crate::provider::mem_tier::SegmentTombstones::from_int64_keys([999_i64]);
        seg.stamp(durable_max);
        let cur = provider.mem_tier.shard(0).load();
        let next = cur.append_segment(Arc::new(vec![]), durable_max, seg, 0, 0, 0);
        provider.mem_tier.shard(0).store(Arc::new(next));
        assert_eq!(
            provider.min_pending_mem_tier_delete_sequence(),
            Some(durable_max),
            "the pending floor must cap the fence below the newest supersede delete"
        );

        let merged = provider
            .compact_protected_snapshots_subset(8)
            .await
            .expect("subset compaction pass");

        // THE INVARIANT: the live row stays visible across the pass. Folding the
        // newest snapshot under the capped fence made this scan come back EMPTY.
        let pairs = collect_id_value_pairs(&ctx, &provider, "subset_fence_exclusion").await;
        assert_eq!(
            pairs,
            vec![(1, 30)],
            "live row must survive a subset compaction whose fence is capped by a \
             pending mem-tier delete (merged={merged})"
        );

        // The pass must still merge the at-or-below-fence inputs rather than
        // declining outright: two eligible inputs fold into one output while the
        // above-fence snapshot stays live untouched.
        assert!(merged, "the at-or-below-fence snapshots must still merge");
        assert_eq!(
            provider.protected_snapshots.load_full().len(),
            2,
            "eligible inputs merge into one output; the above-fence snapshot stays live"
        );
    }

    /// REGRESSION: the seq-prefix bake has the same above-fence hazard as the
    /// size-tier subset pass — its older prefix can contain a snapshot whose
    /// merge-on-read threshold exceeds the capped fence (a key updated at least
    /// `BAKE_KEEP_RECENT_SNAPSHOTS` snapshots ago), and folding it retags that
    /// key's live row at the fence, so scans re-apply the `(fence, threshold]`
    /// supersede deletes and the row vanishes. The bake must stop its prefix at
    /// the first above-fence input while a pending mem-tier delete caps the
    /// fence, and still bake the eligible below-fence prefix.
    #[tokio::test]
    async fn bake_stops_prefix_at_first_input_above_delete_fence() {
        use arrow::datatypes::{DataType, Field, Schema};

        let ctx = SessionContext::new();
        let (provider, _catalog, _tmp) = create_cdc_upsert_table_with_vortex_config(
            "bake_fence_exclusion",
            ctx.runtime_env(),
            VortexConfig {
                inline_max_rows: 0,
                deletion_mode: crate::metadata::DeletionMode::Key,
                compaction_trigger_protected_snapshots: 2,
                ..VortexConfig::default()
            },
        )
        .await;
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));

        // Bake prefix = all but the newest K. Arrange: an untouched key (10) in
        // the oldest snapshot, key 1 superseded once so its LIVE version sits in
        // the prefix's newest snapshot, then K filler snapshots on key 2 so the
        // key-1 snapshots all land in the bake prefix.
        let setup_guard = provider.compaction_lock.lock().await;
        insert_batch(
            &provider,
            id_value_batch(Arc::clone(&schema), &[10], &[111]),
        )
        .await;
        for value in [10_i64, 20] {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[1], &[value]),
            )
            .await;
        }
        for value in [100_i64, 200, 300] {
            insert_batch(
                &provider,
                id_value_batch(Arc::clone(&schema), &[2], &[value]),
            )
            .await;
        }
        provider
            .flush_pending_maintenance()
            .await
            .expect("drain pending post-write maintenance");
        drop(setup_guard);

        let expected_snapshots = BAKE_KEEP_RECENT_SNAPSHOTS + 3;
        let mut protected_count = 0;
        for _ in 0..100 {
            protected_count = provider.protected_snapshots.load_full().len();
            if protected_count >= expected_snapshots {
                break;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        assert_eq!(
            protected_count, expected_snapshots,
            "one protected snapshot per insert"
        );

        // Cap the fence at the second-oldest snapshot's threshold: a pending
        // mem-tier tombstone (unrelated key) one above it makes the fence land
        // exactly there — below key 1's supersede delete, so key 1's live
        // snapshot is the first above-fence prefix input.
        let mut thresholds: Vec<i64> = provider
            .protected_snapshots
            .load_full()
            .values()
            .copied()
            .collect();
        thresholds.sort_unstable();
        let pending_floor = thresholds[1] + 1;
        let mut seg = crate::provider::mem_tier::SegmentTombstones::from_int64_keys([999_i64]);
        seg.stamp(pending_floor);
        let cur = provider.mem_tier.shard(0).load();
        let next = cur.append_segment(Arc::new(vec![]), pending_floor, seg, 0, 0, 0);
        provider.mem_tier.shard(0).store(Arc::new(next));
        assert_eq!(
            provider.min_pending_mem_tier_delete_sequence(),
            Some(pending_floor),
            "the pending floor must cap the fence below key 1's supersede delete"
        );

        let baked = provider
            .bake_seq_prefix_protected_snapshots()
            .await
            .expect("seq-prefix bake pass");

        // THE INVARIANT: every live row stays visible. Folding key 1's live
        // snapshot under the capped fence made key 1 vanish (its supersede
        // delete sits above the fence the output is retagged with).
        let pairs = collect_id_value_pairs(&ctx, &provider, "bake_fence_exclusion").await;
        assert_eq!(
            pairs,
            vec![(1, 20), (2, 300), (10, 111)],
            "live rows must survive a seq-prefix bake whose fence is capped by a \
             pending mem-tier delete (baked={baked})"
        );

        // The bake must still fold the eligible below-fence prefix rather than
        // declining outright.
        assert!(baked, "the below-fence prefix must still bake");
        assert_eq!(
            provider.protected_snapshots.load_full().len(),
            expected_snapshots - 1,
            "the two below-fence inputs fold into one output; the above-fence \
             snapshot stays live"
        );
    }

    /// STAGE-2 DELIVERABLE TEST (6) — REGRESSION FIX. An OLDER-prefix candidate
    /// with an EMPTY manifest (its async population has not landed) is BAKED via its
    /// protected-set watermark (its single allocated commit-sequence — the seq of
    /// every row it holds), NOT skipped. The old behavior skipped it, leaving it a
    /// LIVE empty-manifest blocker so the post-swap prune was withheld forever — the
    /// bake paid merge write-amp with zero index shrink (the production regression).
    /// Baking it retires it into the merge (deletions applied → survivors only), so
    /// the `<= T` prune runs and resurrects nothing.
    ///
    /// Six protected snapshots; the older prefix is the oldest three (ids 0,1,2).
    /// We EMPTY id-2's manifest; it is now baked via its watermark alongside {0,1}.
    /// Key 2 is deleted at `delete_seq` 12 (above id-2's small watermark, so the merge
    /// applies it), so id-2's copy is removed and the tombstone is pruned. The newest
    /// K=3 ({3,4,5}) stay live and `> T`.
    #[tokio::test]
    async fn seq_prefix_bake_bakes_empty_manifest_candidate_and_prunes() {
        let ctx = SessionContext::new();
        // Pin all six initially; we then empty exactly one older-prefix snapshot.
        let (provider, _tmp, ids) = build_seq_prefix_fixture(
            "bake_skips_prune_empty",
            ctx.runtime_env(),
            &[10, 20, 30, 40, 50, 60],
        )
        .await;

        // Empty the manifest of one OLDER-prefix snapshot (the 3rd oldest, id-2):
        // there is no per-snapshot manifest delete, so clear ALL rows and re-pin
        // every snapshot EXCEPT id-2 (re-listing each file exactly as the fixture
        // does). That leaves id-2 with an empty manifest while the others keep
        // their pinned [seq, seq] ranges.
        let table_id = provider.table_metadata.table_id.clone();
        let empty_id = ids[2].clone();
        provider
            .catalog
            .clear_snapshot_files(&table_id)
            .await
            .expect("clear all manifests");
        let seqs = [10_i64, 20, 30, 40, 50, 60];
        for (id, &seq) in ids.iter().zip(seqs.iter()) {
            if id == &empty_id {
                continue; // leave id-2's manifest empty (range unknown)
            }
            let files = provider
                .list_snapshot_files_with_sizes(id)
                .await
                .expect("list snapshot files");
            assert!(!files.is_empty(), "snapshot {id} must have a data file");
            for (file_name, size) in files {
                provider
                    .catalog
                    .upsert_snapshot_file(&SnapshotFile {
                        table_id: table_id.clone(),
                        snapshot_id: id.clone(),
                        file_path: file_name,
                        row_count: 1,
                        file_size_bytes: i64::try_from(size).unwrap_or(0),
                        min_sequence: seq,
                        max_sequence: seq,
                        digest: None,
                    })
                    .await
                    .expect("re-pin manifest sequence");
            }
        }
        // Sanity: id-2's manifest is genuinely empty; a populated peer is not.
        assert!(
            provider
                .catalog
                .get_snapshot_files(&table_id, &empty_id)
                .await
                .expect("get manifest")
                .is_empty(),
            "the older snapshot id-2 must have an empty manifest for this test"
        );

        // Tombstone at delete_seq 12 (<= T=20). Key 2 physically lives in the
        // empty-manifest snapshot id-2, which is NOT merged (skipped) and stays
        // live — so dropping this tombstone would resurrect it.
        install_int64_deletes(&provider, &[(2, 12)]);

        let baked = provider
            .bake_seq_prefix_protected_snapshots()
            .await
            .expect("bake should not error");
        assert!(
            baked,
            "the older prefix (incl the empty-manifest id-2) must bake"
        );

        // FIX: an empty-manifest CANDIDATE is now BAKED via its protected-set
        // watermark (its single commit-sequence), not skipped — so it is retired
        // into the merge and is no longer a live blocker.
        assert!(
            !provider
                .protected_snapshots
                .load_full()
                .contains_key(&empty_id),
            "the empty-manifest older candidate must be baked away (merged into M)"
        );

        // The `<= T` tombstone for key 2 is PRUNED: id-2 was baked with its watermark
        // as its merge threshold, so the merge applied delete_seq 12 (above that
        // small watermark) and key 2 is physically removed from M — pruning the
        // tombstone resurrects nothing.
        let tombstones = int64_tombstones(&provider);
        assert_eq!(
            tombstones.delete_len(),
            0,
            "the <= T tombstone is pruned once the empty-manifest candidate is baked"
        );

        // Key 2 stays deleted (removed by the merge) — no resurrection.
        let pairs = collect_id_value_pairs(&ctx, &provider, "bake_skips_prune_empty").await;
        assert!(
            !pairs.iter().any(|(id, _)| *id == 2),
            "key 2 stays deleted (baked out by the merge) — no resurrection, got {pairs:?}"
        );
    }

    /// THRESHOLD-EXEMPTION (resurrect-rows-critical). A KEPT live snapshot whose
    /// manifest write-range dips `<= T` is STILL clean past T when its protected-set
    /// value (its merge-on-read delete-watermark) is `>= T`: deletions `<= T` are
    /// already physically applied to it (survivors only), so pruning them resurrects
    /// nothing and the prune must RUN, not be withheld on the write-range alone.
    /// This mirrors a compaction output that consolidated old survivors (low
    /// `min_sequence`) but baked deletes to a high watermark — the case that, left
    /// unexempted, makes the bake re-merge without ever pruning.
    ///
    /// Older prefix {0,1} at 10,20 ⇒ T=20. Kept id-2 is given a manifest
    /// `min_sequence = 5` (`<= T`, the write-range trap the old gate blocked on) but
    /// a watermark = 25 (`>= T`), so it is exempt; ids 3,4 stay `> T`. The only
    /// delete targets key 0 (in the baked prefix), so the prune drops it and key 0
    /// stays deleted — key 2 (untouched, the watermark's survivor) is irrelevant.
    #[tokio::test]
    async fn seq_prefix_bake_prunes_when_kept_snapshot_clean_past_cutoff_by_watermark() {
        let ctx = SessionContext::new();
        let (provider, _tmp, ids) = build_seq_prefix_fixture(
            "bake_watermark_exempt",
            ctx.runtime_env(),
            &[10, 20, 30, 40, 50],
        )
        .await;

        // Kept id-2: overwrite its manifest write-range to dip `<= T` (min_sequence
        // 5 — the exact shape the old write-range-only gate blocked on), then set its
        // delete-watermark (protected-set value) to 25 (`>= T=20`), the production
        // signal that its `<= T` deletions are already applied (survivors only).
        let table_id = provider.table_metadata.table_id.clone();
        let kept_id = ids[2].clone();
        let files = provider
            .list_snapshot_files_with_sizes(&kept_id)
            .await
            .expect("list kept files");
        for (file_name, size) in files {
            provider
                .catalog
                .upsert_snapshot_file(&SnapshotFile {
                    table_id: table_id.clone(),
                    snapshot_id: kept_id.clone(),
                    file_path: file_name,
                    row_count: 1,
                    file_size_bytes: i64::try_from(size).unwrap_or(0),
                    min_sequence: 5, // <= T=20: the write-range trap
                    max_sequence: 5,
                    digest: None,
                })
                .await
                .expect("pin low write-range");
        }
        provider.protected_snapshots.rcu(|cur| {
            let mut m = (**cur).clone();
            m.insert(kept_id.clone(), 25); // delete-watermark >= T=20 ⇒ clean past T
            Arc::new(m)
        });

        // Delete key 0 (written at 10, in the baked prefix; delete_seq 15 <= T=20).
        install_int64_deletes(&provider, &[(0, 15)]);

        let baked = provider
            .bake_seq_prefix_protected_snapshots()
            .await
            .expect("bake should not error");
        assert!(baked, "the {{0,1}} prefix bakes");

        // The watermark exemption let the prune RUN despite id-2's min_sequence <= T.
        let tombstones = int64_tombstones(&provider);
        assert_eq!(
            tombstones.delete_len(),
            0,
            "the <= T tombstone is pruned: kept id-2 is clean past T via its watermark"
        );
        let pairs = collect_id_value_pairs(&ctx, &provider, "bake_watermark_exempt").await;
        assert!(
            !pairs.iter().any(|(id, _)| *id == 0),
            "key 0 stays deleted after the bake — no resurrection, got {pairs:?}"
        );
    }

    /// REGRESSION GUARD for the footprint blow-up. On a delete-heavy table the
    /// seq-prefix bake fires every maintenance tick; it must NOT short-circuit the
    /// tick. After baking, `run_compaction_trigger` has to fall through to the
    /// size-tier leveler the SAME pass — otherwise the carried-forward runs
    /// (full-copy data files) never get leveled/reclaimed and protected snapshots
    /// pile up on disk (the regression that sank the original bake). We assert one
    /// `run_compaction_trigger` leaves the protected set strictly smaller than the
    /// bake alone leaves it, proving the leveler ran after the bake.
    #[tokio::test]
    async fn run_compaction_trigger_levels_after_bake_not_short_circuit() {
        // Six file-backed protected snapshots; K=3 kept unbaked ⇒ the older prefix
        // {0,1,2} (seqs 10,20,30) bakes with T=30. Triggers floored so one tick
        // fires BOTH the bake (any tombstone) and the leveler (>=2 snapshots).
        let low_triggers = || VortexConfig {
            inline_max_rows: 0,
            deletion_mode: crate::metadata::DeletionMode::Key,
            bake_deletion_index_trigger: 1,
            compaction_trigger_protected_snapshots: 2,
            compaction_background_interval_ms: 3_600_000,
            ..VortexConfig::default()
        };
        let ctx = SessionContext::new();

        // Bake-only (the pre-fix short-circuit): protected count when the leveler
        // is skipped.
        let (bake_only, _t1, _ids1) = build_seq_prefix_fixture_with_config(
            "bake_then_level_bakeonly",
            ctx.runtime_env(),
            &[10, 20, 30, 40, 50, 60],
            low_triggers(),
        )
        .await;
        install_int64_deletes(&bake_only, &[(0, 15)]);
        assert!(
            bake_only
                .bake_seq_prefix_protected_snapshots()
                .await
                .expect("bake runs"),
            "the {{0,1,2}} prefix bakes"
        );
        let after_bake_only = bake_only.protected_snapshots.load_full().len();

        // Full trigger (the fix): bake THEN level in the same tick.
        let (full, _t2, _ids2) = build_seq_prefix_fixture_with_config(
            "bake_then_level_full",
            ctx.runtime_env(),
            &[10, 20, 30, 40, 50, 60],
            low_triggers(),
        )
        .await;
        install_int64_deletes(&full, &[(0, 15)]);
        assert!(
            full.run_compaction_trigger().await.expect("trigger runs"),
            "the trigger reports work"
        );
        let after_full = full.protected_snapshots.load_full().len();

        assert!(
            after_full < after_bake_only,
            "run_compaction_trigger must fall through to the size-tier leveler after the \
             bake and reclaim more than the bake alone leaves: after_full={after_full} \
             should be < after_bake_only={after_bake_only}"
        );
    }

    // ------------------------------------------------------------------
    // P0 OOM backstop: the deletion-index memory ceiling forces the bake.
    // ------------------------------------------------------------------

    /// Unit test for the pure ceiling predicate. The load-bearing property is the
    /// last two asserts: on an UNBOUNDED pool the backstop must NEVER engage, so it
    /// can't change behavior where there is no `memory_limit` to honor.
    #[test]
    fn deletion_bytes_over_ceiling_binds_only_on_a_finite_pool() {
        use datafusion::execution::memory_pool::MemoryLimit;
        // 25% of 1000 = 250; the check is strictly-greater-than.
        assert!(
            !deletion_bytes_over_ceiling(250, &MemoryLimit::Finite(1000)),
            "exactly at the ceiling is not over"
        );
        assert!(
            !deletion_bytes_over_ceiling(249, &MemoryLimit::Finite(1000)),
            "below the ceiling is not over"
        );
        assert!(
            deletion_bytes_over_ceiling(251, &MemoryLimit::Finite(1000)),
            "above the ceiling is over"
        );
        assert!(
            deletion_bytes_over_ceiling(1000, &MemoryLimit::Finite(1000)),
            "far above the ceiling is over"
        );
        assert!(
            !deletion_bytes_over_ceiling(usize::MAX, &MemoryLimit::Infinite),
            "unbounded pool: the backstop must never engage"
        );
        assert!(
            !deletion_bytes_over_ceiling(usize::MAX, &MemoryLimit::Unknown),
            "unknown pool: the backstop must never engage"
        );
    }

    /// END-TO-END regression for the P0 OOM exposure: under a finite pool, a
    /// key-deletion index over the memory ceiling must FORCE the seq-prefix bake
    /// even when (a) the count trigger is unmet and (b) the apply-back-pressure
    /// defer is active. On trunk there is no memory trigger, so with the count
    /// trigger set high the bake never fires here — this test is trunk-failing by
    /// construction. The infinite-pool control proves the backstop is gated on a
    /// finite pool (no behavior change on an unbounded pool).
    #[tokio::test]
    async fn deletion_index_memory_ceiling_forces_bake_over_count_trigger_and_defer() {
        use datafusion::execution::memory_pool::GreedyMemoryPool;
        use datafusion_execution::runtime_env::RuntimeEnvBuilder;
        use std::time::Duration;

        // ~32 bytes/tombstone (DeletionIndex::approx_bytes). 1M tombstones ≈ 32 MiB,
        // far over 25% of a 16 MiB pool (4 MiB ceiling). The fixture's six one-row
        // writes happen BEFORE the deletes are installed, so they fit the pool; the
        // deletion reservation then over-commits it infallibly (the bug's design).
        const POOL_BYTES: usize = 16 * 1024 * 1024;
        const DELETES: i64 = 1_000_000;

        // Count trigger set absurdly high so it never fires (only the memory
        // backstop can); leveler floor raised so only the bake does work this tick.
        let config = || VortexConfig {
            inline_max_rows: 0,
            deletion_mode: crate::metadata::DeletionMode::Key,
            bake_deletion_index_trigger: 100_000_000,
            compaction_trigger_protected_snapshots: 1_000,
            compaction_background_interval_ms: 3_600_000,
            ..VortexConfig::default()
        };

        // delete_seq 15 sits in the bakeable older prefix {0,1,2} (seqs 10,20,30 ⇒
        // T=30) of the six-snapshot fixture, so the bake prunes every tombstone.
        let deletes: Vec<(i64, i64)> = (0..DELETES).map(|key| (key, 15)).collect();

        // ---- FINITE pool: the ceiling binds and the bake is forced. ----
        let finite_rt = Arc::new(
            RuntimeEnvBuilder::new()
                .with_memory_pool(Arc::new(GreedyMemoryPool::new(POOL_BYTES)))
                .build()
                .expect("finite-pool runtime env"),
        );
        let (finite, _tmp_f, _ids_f) = build_seq_prefix_fixture_with_config(
            "deletion_ceiling_finite",
            finite_rt,
            &[10, 20, 30, 40, 50, 60],
            config(),
        )
        .await;
        install_int64_deletes(&finite, &deletes);

        // Preconditions: over the memory ceiling AND below the count trigger, so
        // ONLY the new memory backstop can fire the bake.
        assert!(
            finite.deletion_index_over_memory_ceiling(),
            "precondition: {DELETES} tombstones must exceed 25% of the {POOL_BYTES}-byte pool"
        );
        let before = finite.pk_deletion_snapshot().delete_len();
        assert!(
            before < 100_000_000,
            "precondition: index len {before} must be below the count trigger"
        );

        // Force the apply-back-pressure defer ON (a healthy bake would yield): a
        // tight loop of 200 ms-apply samples vs ~µs arrival gaps drives
        // apply_vs_arrival ≫ 1 once past warmup. The backstop must override it.
        for _ in 0..(crate::provider::tuning::WARMUP_BATCHES * 3) {
            finite
                .context
                .record_ingest(100, 1, 10_000, Duration::from_millis(200), None);
        }

        let worked = finite
            .run_compaction_trigger()
            .await
            .expect("compaction trigger runs");
        let after = finite.pk_deletion_snapshot().delete_len();
        assert!(
            worked,
            "the memory backstop must force the bake despite the unmet count trigger and active defer"
        );
        assert!(
            after < before,
            "the forced bake must prune the over-ceiling tombstones: before={before} after={after}"
        );

        // ---- INFINITE pool (control): no host ceiling ⇒ no behavior change. ----
        let (infinite, _tmp_i, _ids_i) = build_seq_prefix_fixture_with_config(
            "deletion_ceiling_infinite",
            SessionContext::new().runtime_env(),
            &[10, 20, 30, 40, 50, 60],
            config(),
        )
        .await;
        install_int64_deletes(&infinite, &deletes);
        assert!(
            !infinite.deletion_index_over_memory_ceiling(),
            "an unbounded pool has no host ceiling, so the backstop must never engage"
        );
        let before_inf = infinite.pk_deletion_snapshot().delete_len();
        let worked_inf = infinite
            .run_compaction_trigger()
            .await
            .expect("compaction trigger runs");
        let after_inf = infinite.pk_deletion_snapshot().delete_len();
        assert!(
            !worked_inf && after_inf == before_inf,
            "unbounded pool + unmet count trigger ⇒ the bake must NOT fire: \
             worked={worked_inf} before={before_inf} after={after_inf}"
        );
    }

    /// STAGE-1 DELIVERABLE TEST (1). Two appends published at distinct sequences
    /// `S1 < S2` (each lands in its own file-backed protected snapshot) must
    /// yield manifest rows tagged with that snapshot's OWN sequence — snapshot 1
    /// `[S1, S1]`, snapshot 2 `[S2, S2]` — NOT both stamped the latest watermark.
    /// This is the central defect Stage 1 fixes: the prior per-snapshot watermark
    /// tagged every file in the live set with one sequence, degenerating the
    /// seq-prefix split.
    #[tokio::test]
    async fn rebuild_manifest_tags_each_protected_snapshot_with_its_own_sequence() {
        use arrow::datatypes::{DataType, Field, Schema};
        use datafusion_table_providers::util::column_reference::ColumnReference;

        let ctx = SessionContext::new();
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let metadata_dir = format!("{}/metadata", temp_dir.path().to_str().expect("str path"));
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("str path"));
        std::fs::create_dir_all(&metadata_dir).expect("metadata dir created");
        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let options = CreateTableOptions {
            table_name: "manifest_per_snapshot_seq".to_string(),
            schema: Arc::clone(&schema),
            primary_key: vec!["id".to_string()],
            // Upsert table: each insert publishes a new protected snapshot at its
            // own reserved sequence.
            on_conflict: Some(OnConflict::Upsert(ColumnReference::new(vec![
                "id".to_string(),
            ]))),
            base_path: data_dir,
            partition_column: None,
            vortex_config: VortexConfig {
                // Inline disabled so each insert lands as an on-disk file in its
                // protected snapshot dir (the manifest's domain).
                inline_max_rows: 0,
                // Pin the background compactor far out so it can't merge the two
                // protected snapshots out from under the assertion.
                compaction_background_interval_ms: 3_600_000,
                ..VortexConfig::default()
            },
        };
        let provider = CayenneTableProviderBuilder::new(Arc::clone(&catalog), ctx.runtime_env())
            .create(options)
            .await
            .expect("table created");

        // Two appends with DISTINCT keys → two live protected snapshots (neither
        // supersedes the other), each at its own reserved sequence S1 < S2.
        insert_batch(&provider, id_value_batch(Arc::clone(&schema), &[1], &[10])).await;
        insert_batch(&provider, id_value_batch(Arc::clone(&schema), &[2], &[20])).await;

        // The protected set maps each snapshot id -> its reserved sequence.
        let protected = provider.protected_snapshots.load_full();
        assert_eq!(
            protected.len(),
            2,
            "two distinct-key upserts should leave two live protected snapshots, got {}",
            protected.len()
        );
        let mut seqs: Vec<i64> = protected.values().copied().collect();
        seqs.sort_unstable();
        assert!(
            seqs[0] < seqs[1],
            "the two appends must have distinct, increasing sequences (S1 < S2): {seqs:?}"
        );

        // Run the production manifest rebuild (under the compaction lock the real
        // post-write maintenance lane holds).
        {
            let _guard = provider.compaction_lock.lock().await;
            provider.rebuild_live_snapshot_manifests().await;
        }

        // Each protected snapshot's manifest rows must carry ITS OWN sequence as
        // BOTH min and max — never the other snapshot's (the watermark bug).
        for (snapshot_id, &expected_seq) in protected.iter() {
            let rows = provider
                .catalog
                .get_snapshot_files(&provider.table_metadata.table_id, snapshot_id)
                .await
                .expect("manifest rows");
            assert!(
                !rows.is_empty(),
                "protected snapshot {snapshot_id} should have at least one manifest row"
            );
            for row in &rows {
                assert_eq!(
                    (row.min_sequence, row.max_sequence),
                    (expected_seq, expected_seq),
                    "file {} in snapshot {snapshot_id} must be tagged [S, S] = [{expected_seq}, \
                     {expected_seq}] (its own reservation), not a shared watermark",
                    row.file_path,
                );
            }
        }
    }

    /// Phase 4 (physical-file GC ref-counting): the relative-path key combines
    /// the snapshot id and the file name, so the SAME bare file name under two
    /// different snapshots maps to two distinct physical files.
    #[test]
    fn manifest_file_relative_path_is_snapshot_scoped() {
        assert_eq!(
            CayenneTableProvider::manifest_file_relative_path("snapA", "0001.vortex"),
            "snapA/0001.vortex"
        );
        assert_ne!(
            CayenneTableProvider::manifest_file_relative_path("snapA", "0001.vortex"),
            CayenneTableProvider::manifest_file_relative_path("snapB", "0001.vortex"),
            "the same bare name under two snapshots is two different physical files"
        );
    }

    /// Phase 4: the live-referenced set is built only from rows whose snapshot is
    /// in the live set (current + protected); rows belonging to already-retired
    /// snapshots are excluded so a dying snapshot cannot keep its own files
    /// alive. A live snapshot that references a file physically located in
    /// another snapshot's dir (an in-place compaction reference) IS included.
    #[test]
    fn live_referenced_relative_paths_filters_to_live_set() {
        let row = |snap: &str, file: &str| SnapshotFile {
            table_id: "t".to_string(),
            snapshot_id: snap.to_string(),
            file_path: file.to_string(),
            row_count: 1,
            file_size_bytes: 100,
            min_sequence: 1,
            max_sequence: 1,
            digest: None,
        };
        let all_rows = vec![
            // current snapshot owns one file...
            row("current", "c0.vortex"),
            // ...and references a file that physically lives in old1's dir.
            row("current", "old1_baked.vortex"),
            // protected snapshot owns a file.
            row("protected", "p0.vortex"),
            // old1 (already retired) still has a stale manifest row of its own.
            row("old1", "old1_dead.vortex"),
        ];
        let live: HashSet<String> = ["current".to_string(), "protected".to_string()]
            .into_iter()
            .collect();

        let referenced = CayenneTableProvider::live_referenced_relative_paths(&all_rows, &live);

        assert!(referenced.contains("current/c0.vortex"));
        assert!(referenced.contains("protected/p0.vortex"));
        assert!(
            referenced.contains("current/old1_baked.vortex"),
            "an in-place reference is keyed by the REFERENCING snapshot's id"
        );
        assert!(
            !referenced.contains("old1/old1_dead.vortex"),
            "a retired snapshot's own rows must not keep its files alive"
        );
        assert_eq!(referenced.len(), 3);
    }

    /// Phase 4: `get_all_snapshot_files` returns every manifest row for a table
    /// across all snapshots (the GC ref-count source), unlike
    /// `get_snapshot_files` which is scoped to one snapshot.
    #[tokio::test]
    async fn get_all_snapshot_files_spans_snapshots() {
        let ctx = SessionContext::new();
        let (provider, _tmp) =
            create_int64_pk_provider("gc_all_manifest_rows", ctx.runtime_env()).await;
        let table_id = provider.table_metadata.table_id.clone();

        let mk = |snap: &str, file: &str| SnapshotFile {
            table_id: table_id.clone(),
            snapshot_id: snap.to_string(),
            file_path: file.to_string(),
            row_count: 1,
            file_size_bytes: 100,
            min_sequence: 1,
            max_sequence: 1,
            digest: None,
        };
        for row in [
            mk("snapA", "a0.vortex"),
            mk("snapA", "a1.vortex"),
            mk("snapB", "b0.vortex"),
        ] {
            provider
                .catalog
                .upsert_snapshot_file(&row)
                .await
                .expect("upsert manifest row");
        }

        let all = provider
            .catalog
            .get_all_snapshot_files(&table_id)
            .await
            .expect("get_all_snapshot_files");
        assert_eq!(all.len(), 3, "all rows across both snapshots are returned");

        // A different table id must see none of these rows.
        let other = provider
            .catalog
            .get_all_snapshot_files("some-other-table")
            .await
            .expect("get_all_snapshot_files (other table)");
        assert!(
            other.is_empty(),
            "rows are scoped to the requested table id"
        );
    }

    /// Phase 4: ref-counted retired-dir deletion keeps a data file that a live
    /// snapshot references in place (even when an identically-named file in a
    /// LIVE dir exists), deletes the genuinely orphaned files, and reports the
    /// dir as NOT fully removed while a referenced file survives.
    #[test]
    fn delete_retired_snapshot_dir_refcounted_keeps_referenced_files() {
        use std::cell::RefCell;

        let tmp = TempDir::new().expect("temp dir");
        let table_root = tmp.path().join("table-id");
        let retired_dir = table_root.join("retired-snap");
        std::fs::create_dir_all(&retired_dir).expect("create retired dir");

        // Two data files in the retired dir, a non-data sidecar, and a hidden file.
        std::fs::write(retired_dir.join("kept.vortex"), b"x").expect("write kept");
        std::fs::write(retired_dir.join("orphan.vortex"), b"x").expect("write orphan");
        std::fs::write(retired_dir.join("notes.txt"), b"x").expect("write sidecar");
        std::fs::write(retired_dir.join(".hidden"), b"x").expect("write hidden");

        // A LIVE snapshot references `retired-snap/kept.vortex` in place. It does
        // NOT reference `retired-snap/orphan.vortex`. Note `kept.vortex` as a
        // bare name is ambiguous; only the snapshot-scoped relative path is.
        let referenced: HashSet<String> = ["retired-snap/kept.vortex".to_string()]
            .into_iter()
            .collect();
        let orphan_cache_path =
            CayenneTableProvider::local_segment_cache_path(&retired_dir.join("orphan.vortex"))
                .expect("orphan path should convert before deletion");
        let referenced_cache_path =
            CayenneTableProvider::local_segment_cache_path(&retired_dir.join("kept.vortex"))
                .expect("referenced path should convert before deletion");

        let invalidated = RefCell::new(HashSet::new());
        let fully_removed = CayenneTableProvider::delete_retired_snapshot_dir_refcounted(
            &retired_dir,
            "retired-snap",
            &referenced,
            |paths| *invalidated.borrow_mut() = paths,
        )
        .expect("refcounted delete");

        assert!(
            !fully_removed,
            "dir is kept while a referenced file (and the non-data sidecar) survive"
        );
        assert!(
            retired_dir.join("kept.vortex").exists(),
            "a file referenced in place by a live snapshot must survive"
        );
        assert!(
            !retired_dir.join("orphan.vortex").exists(),
            "an unreferenced data file must be deleted"
        );
        assert!(
            retired_dir.join("notes.txt").exists(),
            "a non-data sidecar is conservatively kept (never a manifest target)"
        );
        assert_eq!(invalidated.borrow().len(), 1);
        assert!(
            invalidated.borrow().contains(&orphan_cache_path),
            "the orphan's exact cache path must be invalidated"
        );
        assert!(
            !invalidated.borrow().contains(&referenced_cache_path),
            "a path referenced in place by a live snapshot must remain cached"
        );
    }

    /// Phase 4: when NO file in the retired dir is referenced, every data file
    /// is deleted and the (now-empty) dir is removed, reported as fully removed.
    #[test]
    fn delete_retired_snapshot_dir_refcounted_removes_fully_orphaned_dir() {
        let tmp = TempDir::new().expect("temp dir");
        let table_root = tmp.path().join("table-id");
        let retired_dir = table_root.join("dead-snap");
        std::fs::create_dir_all(&retired_dir).expect("create retired dir");
        std::fs::write(retired_dir.join("a.vortex"), b"x").expect("write a");
        std::fs::write(retired_dir.join("b.vortex"), b"x").expect("write b");

        // The live set references a same-named file but under a DIFFERENT
        // snapshot id, so nothing in `dead-snap` is protected.
        let referenced: HashSet<String> = ["other-snap/a.vortex".to_string()].into_iter().collect();

        let fully_removed = CayenneTableProvider::delete_retired_snapshot_dir_refcounted(
            &retired_dir,
            "dead-snap",
            &referenced,
            |_| {},
        )
        .expect("refcounted delete");

        assert!(fully_removed, "a fully-orphaned dir is removed");
        assert!(
            !retired_dir.exists(),
            "the empty dir itself is removed once all data files are gone"
        );
    }

    /// Phase 4: a missing (already-reaped) retired dir is reported as fully
    /// removed rather than erroring — the sweep is idempotent across retries.
    #[test]
    fn delete_retired_snapshot_dir_refcounted_missing_dir_is_ok() {
        let tmp = TempDir::new().expect("temp dir");
        let missing = tmp.path().join("table-id").join("never-existed");
        let fully_removed = CayenneTableProvider::delete_retired_snapshot_dir_refcounted(
            &missing,
            "never-existed",
            &HashSet::new(),
            |_| {},
        )
        .expect("missing dir is not an error");
        assert!(fully_removed, "a NotFound dir counts as fully removed");
    }

    #[test]
    fn local_segment_cache_path_matches_relative_listing_path() {
        let tmp = TempDir::new_in(".").expect("relative temp dir");
        let nested = tmp.path().join("space % # ü");
        std::fs::create_dir_all(&nested).expect("create special-character directory");
        let file = nested.join("data # %.vortex");
        std::fs::write(&file, b"data").expect("write listed file");

        let listing = ListingTableUrl::parse(file.to_string_lossy())
            .expect("relative file path should parse as a listing URL");
        assert_eq!(
            CayenneTableProvider::local_segment_cache_path(&file)
                .expect("relative cache path should convert"),
            listing.prefix().clone(),
            "cache retirement must reconstruct the exact LocalFileSystem key"
        );
    }

    #[tokio::test]
    async fn object_store_refcounted_cleanup_invalidates_only_retired_cached_path() {
        use crate::metadata::ObjectStoreConfig;
        use crate::provider::delta_encoding::WritePolicy;
        use object_store::memory::InMemory;

        let temp_dir = tempfile::tempdir().expect("temp dir created");
        let metadata_dir = temp_dir.path().join("metadata");
        std::fs::create_dir_all(&metadata_dir).expect("metadata dir created");
        let connection_string = format!(
            "sqlite://{}/cayenne.db",
            metadata_dir
                .to_str()
                .expect("metadata path should be UTF-8")
        );
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");

        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let store = Arc::new(InMemory::new()) as Arc<dyn ObjectStore>;
        let store_url = url::Url::parse("s3://segment-cache-retirement")
            .expect("object-store URL should be valid");
        let provider = CayenneTableProviderBuilder::new(
            Arc::clone(&catalog),
            SessionContext::new().runtime_env(),
        )
        .with_object_store(ObjectStoreConfig {
            url: store_url,
            store: Arc::clone(&store),
        })
        .create(CreateTableOptions {
            table_name: "object_store_segment_cache_retirement".to_string(),
            schema: Arc::clone(&schema),
            primary_key: vec![],
            on_conflict: None,
            base_path: "s3://segment-cache-retirement/cayenne".to_string(),
            partition_column: None,
            vortex_config: VortexConfig {
                inline_max_rows: 0,
                ..VortexConfig::default()
            },
        })
        .await
        .expect("object-store table created");

        let snapshot_id = provider.get_current_snapshot_id();
        provider
            .write_to_snapshot(
                single_batch_stream(
                    RecordBatch::try_new(
                        Arc::clone(&schema),
                        vec![Arc::new(Int64Array::from_iter_values(0..2_000))],
                    )
                    .expect("input batch"),
                ),
                provider.target_file_size_bytes(),
                &snapshot_id,
                1,
                None,
                WritePolicy::DELTA,
            )
            .await
            .expect("write source Vortex object");

        let prefix = provider
            .snapshot_object_store_prefix(&snapshot_id)
            .expect("snapshot prefix should resolve")
            .expect("S3 table should have an object-store prefix");
        let source_objects: Vec<_> = store
            .list(Some(&prefix))
            .try_collect()
            .await
            .expect("list written objects");
        let source_data_paths: Vec<_> = source_objects
            .iter()
            .filter(|meta| {
                meta.location.parts().next_back().is_some_and(|name| {
                    CayenneTableProvider::is_compactable_data_file(name.as_ref())
                })
            })
            .map(|meta| meta.location.clone())
            .collect();
        assert_eq!(
            source_data_paths.len(),
            1,
            "the single-shard write should create one Vortex object: {source_data_paths:?}"
        );
        let source_path = source_data_paths[0].clone();
        let retired_path =
            ObjectStorePath::from(format!("{}/retired-copy.vortex", prefix.as_ref()));
        store
            .copy(&source_path, &retired_path)
            .await
            .expect("copy source object to the retiring path");

        provider
            .refresh_listing_table()
            .await
            .expect("refresh listing after copied object");
        let ctx = SessionContext::new();
        CayenneTableProvider::register_object_store_if_needed(
            &ctx.runtime_env(),
            provider
                .object_store_config
                .as_ref()
                .expect("object-store config should be retained"),
        );
        let snapshot_url = CayenneTableProvider::snapshot_dir_url(
            provider.table_path(),
            provider.table_id(),
            &snapshot_id,
        );
        let listing_table = CayenneTableProvider::create_listing_table(
            &snapshot_url,
            Arc::clone(&schema),
            provider.context().file_format(),
            &provider.pk_deletion_strategy,
        )
        .expect("create direct snapshot listing");
        let listed_files = listing_table
            .list_files_for_scan(&ctx.state(), &[], None)
            .await
            .expect("list direct snapshot files");
        let listed_paths: HashSet<_> = listed_files
            .file_groups
            .iter()
            .flat_map(FileGroup::iter)
            .map(|file| file.path().clone())
            .collect();
        assert_eq!(
            listed_paths,
            HashSet::from([source_path.clone(), retired_path.clone()]),
            "the direct snapshot listing must include both object paths"
        );
        let scan = listing_table
            .scan(&ctx.state(), None, &[], None)
            .await
            .expect("plan direct snapshot scan");
        let rows: usize = collect(scan, ctx.task_ctx())
            .await
            .expect("scan both snapshot objects")
            .iter()
            .map(RecordBatch::num_rows)
            .sum();
        assert_eq!(rows, 4_000, "the scan must read both identical objects");
        let entries_before = provider
            .context()
            .file_format()
            .segment_cache_entry_count()
            .await
            .expect("the segment cache should be enabled");
        assert!(entries_before > 1, "both object paths must be cached");

        let source_file_name = source_path
            .parts()
            .next_back()
            .expect("source path should have a file name");
        let live_referenced = HashSet::from([CayenneTableProvider::manifest_file_relative_path(
            &snapshot_id,
            source_file_name.as_ref(),
        )]);
        provider
            .delete_prefix_refcounted(&prefix, &snapshot_id, &live_referenced)
            .await
            .expect("ref-counted object-store cleanup");

        let remaining_data_paths: HashSet<_> = store
            .list(Some(&prefix))
            .try_collect::<Vec<_>>()
            .await
            .expect("list objects after cleanup")
            .into_iter()
            .filter(|meta| {
                meta.location.parts().next_back().is_some_and(|name| {
                    CayenneTableProvider::is_compactable_data_file(name.as_ref())
                })
            })
            .map(|meta| meta.location)
            .collect();
        assert_eq!(
            remaining_data_paths,
            HashSet::from([source_path]),
            "cleanup must preserve the referenced object and delete only the retired object"
        );
        let entries_after = provider
            .context()
            .file_format()
            .segment_cache_entry_count()
            .await
            .expect("the segment cache should remain enabled");
        assert_eq!(
            entries_after.saturating_mul(2),
            entries_before,
            "identical objects cache equal segment counts, so cleanup must evict only the retired path"
        );
    }

    /// Helper to read all data from a `CayenneTableProvider` as `RecordBatch`es.
    async fn read_all(
        ctx: &SessionContext,
        provider: &CayenneTableProvider,
        table_name: &str,
    ) -> Vec<RecordBatch> {
        ctx.deregister_table(table_name).ok();
        ctx.register_table(table_name, Arc::new(provider.clone_for_write()))
            .expect("table registered");
        let df = ctx
            .sql(&format!("SELECT * FROM {table_name}"))
            .await
            .expect("query created");
        df.collect().await.expect("collect succeeded")
    }

    /// [sound `output_ordering`] `sort_columns_to_file_sort_order` must reproduce
    /// `sort_stream`'s exact per-entry resolution (Copilot review): the
    /// exact-column-name match comes FIRST (so a column whose literal name contains
    /// whitespace or a direction keyword is matched as a whole, NOT mis-split by the
    /// parser), then the `column [ASC|DESC] [NULLS …]` parse, else advertise nothing.
    /// A divergence here would advertise an order the file was NOT written in.
    #[test]
    fn test_sort_columns_to_file_sort_order_mirrors_sort_stream() {
        use datafusion::logical_expr::Expr;
        fn col_of(e: &Expr) -> &str {
            match e {
                Expr::Column(c) => c.name(),
                other => panic!("expected a column expr, got {other:?}"),
            }
        }
        let schema = Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            // A column whose LITERAL name contains a space and a direction keyword.
            Field::new("id DESC", DataType::Int64, true),
        ]);

        // (1) plain column → exact-match → ASC, NULLs-last.
        let o = CayenneTableProvider::sort_columns_to_file_sort_order(&["id".to_string()], &schema)
            .expect("`id` is a column");
        assert_eq!(o.len(), 1);
        assert_eq!(o[0].len(), 1);
        assert!(o[0][0].asc && !o[0][0].nulls_first);
        assert_eq!(col_of(&o[0][0].expr), "id");

        // (2) exact-match WINS over the parser: a column literally named `id DESC`
        //     advertises that exact column ASC — NOT column `id` descending (which
        //     is the silently-wrong order the parser-only path would have produced).
        let o = CayenneTableProvider::sort_columns_to_file_sort_order(
            &["id DESC".to_string()],
            &schema,
        )
        .expect("`id DESC` is a column");
        assert!(o[0][0].asc, "exact-matched column sorts ascending");
        assert!(!o[0][0].nulls_first, "exact-matched column is NULLs-last");
        assert_eq!(
            col_of(&o[0][0].expr),
            "id DESC",
            "must advertise the exact column, not the mis-split `id`"
        );

        // (3) parsed `DESC NULLS FIRST` on a column reachable only via parsing.
        let schema2 = Schema::new(vec![Field::new("ts", DataType::Int64, true)]);
        let o = CayenneTableProvider::sort_columns_to_file_sort_order(
            &["ts DESC NULLS FIRST".to_string()],
            &schema2,
        )
        .expect("`ts` parses and exists");
        assert!(!o[0][0].asc && o[0][0].nulls_first);
        assert_eq!(col_of(&o[0][0].expr), "ts");

        // (4) parsed, but the resolved column is absent from the schema → nothing.
        assert!(
            CayenneTableProvider::sort_columns_to_file_sort_order(
                &["missing DESC".to_string()],
                &schema2,
            )
            .is_none(),
            "a sort column absent from the scan schema must drop ordering"
        );

        // (5) unparseable entry (`sort_stream` abandons the sort) → advertise nothing.
        assert!(
            CayenneTableProvider::sort_columns_to_file_sort_order(
                &["a b c d".to_string()],
                &schema2,
            )
            .is_none(),
            "an unparseable entry leaves the file unsorted → advertise nothing"
        );

        // (6) empty sort_columns → nothing.
        assert!(CayenneTableProvider::sort_columns_to_file_sort_order(&[], &schema2).is_none());
    }

    /// [sound `output_ordering`] A snapshot freshly produced by the sorted compaction
    /// rewrite, with no unsorted union branches, advertises `output_ordering` by the
    /// sort columns; a subsequent append delta-adds an UNSORTED file in place and
    /// MUST clear the attestation so ordering is no longer advertised. Also locks the
    /// bare-column `SortOptions` (ascending, NULLs-last) the writer sorted by.
    #[tokio::test]
    async fn test_sorted_rewrite_advertises_output_ordering_then_append_clears_it() {
        use arrow::array::Int64Array;
        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        // Statistics-based file grouping must be on for the sorted file set to be
        // grouped into a non-overlapping run (the soundness precondition).
        let mut config = datafusion::prelude::SessionConfig::new();
        config
            .options_mut()
            .execution
            .split_file_groups_by_statistics = true;
        let ctx = SessionContext::new_with_config(config);
        // `inline_max_rows: 0` forces writes to files (not the inline memtable), so
        // the rewrite actually sorts them and the inline-branch gate stays clear.
        let (provider, _tmp) = create_cayenne_table_with_config(
            "ordering_lifecycle",
            Arc::clone(&schema),
            VortexConfig {
                sort_columns: vec!["id".to_string()],
                inline_max_rows: 0,
                ..VortexConfig::default()
            },
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let batch = RecordBatch::try_new(
            Arc::clone(&schema),
            vec![
                Arc::new(Int64Array::from(vec![5_i64, 1, 4, 2, 3])),
                Arc::new(Int64Array::from(vec![50_i64, 10, 40, 20, 30])),
            ],
        )
        .expect("batch");
        insert_batch(&provider, batch).await;
        provider
            .rewrite_current_snapshot_for_compaction()
            .await
            .expect("sorted rewrite");

        let plan = provider
            .scan(&ctx.state(), None, &[], None)
            .await
            .expect("scan plan");
        let ordering = plan.properties().output_ordering().expect(
            "a sorted-rewritten snapshot with no unsorted branches must advertise output_ordering",
        );
        let first = ordering.first();
        // Bare "id" ⇒ ascending, NULLs-last — must match what `sort_stream` wrote.
        assert!(!first.options.descending, "bare sort column is ascending");
        assert!(!first.options.nulls_first, "bare sort column is NULLs-last");

        // A subsequent append delta-adds an UNSORTED file into the same snapshot in
        // place; the attestation must clear so ordering is no longer advertised.
        let more = RecordBatch::try_new(
            Arc::clone(&schema),
            vec![
                Arc::new(Int64Array::from(vec![0_i64, 9])),
                Arc::new(Int64Array::from(vec![0_i64, 90])),
            ],
        )
        .expect("batch");
        insert_batch(&provider, more).await;
        let plan_after = provider
            .scan(&ctx.state(), None, &[], None)
            .await
            .expect("scan plan after append");
        assert!(
            plan_after.properties().output_ordering().is_none(),
            "after an append delta-adds an unsorted file, output_ordering must NOT be advertised"
        );
    }

    /// Retirement releases both of the caches a Vortex file occupies, in one
    /// call: its decoded segments and its footer. The footer cache has no TTL
    /// and no invalidation of its own — an entry leaves only when another `put`
    /// pushes it out under capacity pressure — and every Cayenne file is written
    /// once under a fresh uuid7 directory, so a footer that outlives its file
    /// can never be looked up again yet keeps a share of a budget that live
    /// metadata for every other table on the same environment, Parquet
    /// included, competes for.
    ///
    /// "on the same environment" is the sharing boundary, and it is narrower
    /// than the process: the cache hangs off the `RuntimeEnv`. This test runs
    /// against one environment, so it covers what a deployment without a
    /// dedicated Cayenne compaction environment sees; the second cache such a
    /// deployment has is spiceai/spiceai#13497.
    #[tokio::test]
    async fn committed_compaction_invalidates_retired_segments_and_footers_after_cleanup() {
        use arrow::array::Int64Array;

        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let ctx = SessionContext::new();
        let (provider, _tmp) = create_cayenne_table_with_config(
            "compaction_segment_cache_retirement",
            Arc::clone(&schema),
            VortexConfig {
                inline_max_rows: 0,
                ..VortexConfig::default()
            },
            vec![],
            ctx.runtime_env(),
        )
        .await;
        // Footer-cache keys are the files' object-store locations, and a Cayenne
        // file's location carries the id of the snapshot that wrote it, so the
        // resident footers can be attributed to a snapshot by name.
        let footers_under = |snapshot: &str| {
            ctx.runtime_env()
                .cache_manager
                .get_file_metadata_cache()
                .list_entries()
                .into_keys()
                .filter(|path| path.as_ref().contains(snapshot))
                .count()
        };
        insert_batch(
            &provider,
            RecordBatch::try_new(
                Arc::clone(&schema),
                vec![Arc::new(Int64Array::from_iter_values(0..2_000))],
            )
            .expect("input batch"),
        )
        .await;
        assert_eq!(
            read_all(&ctx, &provider, "compaction_segment_cache_retirement")
                .await
                .iter()
                .map(RecordBatch::num_rows)
                .sum::<usize>(),
            2_000
        );
        let old_cache_entries = provider
            .context()
            .file_format()
            .segment_cache_entry_count()
            .await
            .expect("the file-backed test enables the segment cache");
        assert!(
            old_cache_entries > 0,
            "the source scan must populate the cache"
        );
        let old_snapshot = provider.get_current_snapshot_id();
        assert!(
            footers_under(&old_snapshot) > 0,
            "the source scan must cache the written snapshot's footers"
        );

        assert!(
            provider
                .rewrite_current_snapshot_for_compaction()
                .await
                .expect("compaction rewrite"),
            "the compaction must publish a replacement snapshot"
        );
        provider
            .drain_in_flight_maintenance()
            .await
            .expect("drain post-compaction maintenance");
        assert_eq!(
            read_all(&ctx, &provider, "compaction_segment_cache_retirement")
                .await
                .iter()
                .map(RecordBatch::num_rows)
                .sum::<usize>(),
            2_000
        );
        let entries_before_cleanup = provider
            .context()
            .file_format()
            .segment_cache_entry_count()
            .await
            .expect("segment cache remains enabled");
        assert!(
            entries_before_cleanup > old_cache_entries,
            "the replacement scan must cache live segments alongside retired inputs"
        );

        let current_snapshot = provider.get_current_snapshot_id();
        let retired_footers_before = footers_under(&old_snapshot);
        assert!(
            retired_footers_before > 0,
            "the compaction inputs' footers are still resident before cleanup"
        );
        assert!(
            footers_under(&current_snapshot) > 0,
            "the replacement scan must cache the live snapshot's footers"
        );

        provider.protected_snapshots.store(Arc::new(HashMap::new()));
        provider
            .snapshot_scan_refs
            .lock()
            .insert(old_snapshot.clone(), 1);
        provider
            .cleanup_old_snapshots_now_for_test(&current_snapshot)
            .await
            .expect("in-flight cleanup pass");
        assert_eq!(
            provider
                .context()
                .file_format()
                .segment_cache_entry_count()
                .await,
            Some(entries_before_cleanup),
            "in-flight compaction inputs must remain cached"
        );
        assert_eq!(
            footers_under(&old_snapshot),
            retired_footers_before,
            "a snapshot an in-flight scan still holds is not retired, so its footers must stay"
        );
        assert_eq!(
            provider.snapshot_scan_refs.lock().remove(&old_snapshot),
            Some(1),
            "the test must release the old snapshot's in-flight guard"
        );
        provider
            .cleanup_old_snapshots_now_for_test(&current_snapshot)
            .await
            .expect("cleanup committed compaction inputs after the scan guard is released");
        let entries_after_cleanup = provider
            .context()
            .file_format()
            .segment_cache_entry_count()
            .await
            .expect("segment cache remains enabled");
        assert!(
            entries_after_cleanup > 0 && entries_after_cleanup < entries_before_cleanup,
            "cleanup must remove retired compaction inputs while preserving the output cache"
        );
        assert_eq!(
            footers_under(&old_snapshot),
            0,
            "retiring a file must drop its footer: the deleted snapshot's {retired_footers_before} footers are still pinned in the shared cache, and nothing else will ever release them"
        );
        assert!(
            footers_under(&current_snapshot) > 0,
            "the live snapshot's footers must survive cleanup"
        );
    }

    /// [sound `output_ordering`] The advertised `SortOptions` (direction + NULLs
    /// placement) MUST be byte-identical to what the writer sorted by — both built
    /// from the same `parse_sort_entry`. A `DESC NULLS FIRST` sort column must
    /// advertise descending + NULLs-first; a mismatch = silently wrong results.
    #[tokio::test]
    async fn test_output_ordering_sort_options_match_desc_nulls_first() {
        use arrow::array::Int64Array;
        let schema = Arc::new(Schema::new(vec![Field::new("id", DataType::Int64, false)]));
        let mut config = datafusion::prelude::SessionConfig::new();
        config
            .options_mut()
            .execution
            .split_file_groups_by_statistics = true;
        let ctx = SessionContext::new_with_config(config);
        let (provider, _tmp) = create_cayenne_table_with_config(
            "ordering_desc_nf",
            Arc::clone(&schema),
            VortexConfig {
                sort_columns: vec!["id DESC NULLS FIRST".to_string()],
                inline_max_rows: 0,
                ..VortexConfig::default()
            },
            vec![],
            ctx.runtime_env(),
        )
        .await;

        let batch = RecordBatch::try_new(
            Arc::clone(&schema),
            vec![Arc::new(Int64Array::from(vec![1_i64, 5, 3, 2, 4]))],
        )
        .expect("batch");
        insert_batch(&provider, batch).await;
        provider
            .rewrite_current_snapshot_for_compaction()
            .await
            .expect("sorted rewrite");

        let plan = provider
            .scan(&ctx.state(), None, &[], None)
            .await
            .expect("scan plan");
        let ordering = plan
            .properties()
            .output_ordering()
            .expect("descending sorted snapshot must advertise ordering");
        let first = ordering.first();
        assert!(
            first.options.descending,
            "`id DESC NULLS FIRST` must advertise a descending ordering"
        );
        assert!(
            first.options.nulls_first,
            "`id DESC NULLS FIRST` must advertise NULLs-first"
        );
    }

    /// Phase 2 (bloom fallback) helper: create an int64-PK upsert table with an
    /// explicit keyset-cache budget (MB). `pk_keyset_cache_mb = 0` forces the
    /// bounded-bloom existence path once any key is recorded, exercising the
    /// over-budget fallback deterministically without needing millions of rows.
    async fn create_budgeted_upsert_table(
        table_name: &str,
        pk_keyset_cache_mb: usize,
        runtime_env: Arc<RuntimeEnv>,
    ) -> (CayenneTableProvider, TempDir) {
        use arrow::datatypes::{DataType, Field, Schema};

        let temp_dir = tempfile::tempdir().expect("temp dir");
        let metadata_dir = format!("{}/metadata", temp_dir.path().to_str().expect("str path"));
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("str path"));
        std::fs::create_dir_all(&metadata_dir).expect("metadata dir created");

        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));

        let options = CreateTableOptions {
            table_name: table_name.to_string(),
            schema,
            primary_key: vec!["id".to_string()],
            on_conflict: Some(OnConflict::Upsert(
                datafusion_table_providers::util::column_reference::ColumnReference::new(vec![
                    "id".to_string(),
                ]),
            )),
            base_path: data_dir,
            partition_column: None,
            vortex_config: VortexConfig {
                pk_keyset_cache_mb: Some(pk_keyset_cache_mb),
                ..VortexConfig::default()
            },
        };

        let provider = CayenneTableProviderBuilder::new(catalog, runtime_env)
            .create(options)
            .await
            .expect("table created");
        (provider, temp_dir)
    }

