    /// Build an upsert table keyed by `pk_columns` (name, type), in key order.
    async fn create_table_with_pk_columns(
        table_name: &str,
        pk_columns: &[(&str, DataType)],
        runtime_env: Arc<RuntimeEnv>,
    ) -> (CayenneTableProvider, TempDir) {
        let key_names: Vec<String> = pk_columns
            .iter()
            .map(|(name, _)| (*name).to_string())
            .collect();
        let mut fields: Vec<Field> = pk_columns
            .iter()
            .map(|(name, data_type)| Field::new(*name, data_type.clone(), false))
            .collect();
        fields.push(Field::new("value", DataType::Int64, false));

        let on_conflict = OnConflict::Upsert(
            datafusion_table_providers::util::column_reference::ColumnReference::new(
                key_names.clone(),
            ),
        );
        let (provider, _catalog, temp_dir) = create_cdc_table_with_schema(
            table_name,
            runtime_env,
            Arc::new(Schema::new(fields)),
            key_names,
            VortexConfig::default(),
            on_conflict,
        )
        .await;
        (provider, temp_dir)
    }

    /// Whether `pk_row_converter` is cached is the deletion-vector key-encoding
    /// discriminator: an `Int64Pk` table's tombstone keys are raw big-endian,
    /// every other shape's are `RowConverter` `OwnedRow` encodings (see
    /// `partition_cold_manifest_for_promotion`). Caching a converter for a
    /// single-`Int64` primary key would decode those raw-BE keys through a
    /// `RowConverter`, corrupting carry-forward classification and cold-file
    /// partitioning — so pin which shape caches one.
    #[tokio::test]
    async fn pk_row_converter_is_none_exactly_for_the_int64_pk_strategy() {
        let ctx = SessionContext::new();

        let (int64_pk, _tmp_int64) = create_table_with_pk_columns(
            "pk_guard_int64",
            &[("id", DataType::Int64)],
            ctx.runtime_env(),
        )
        .await;
        assert!(
            matches!(
                int64_pk.pk_deletion_strategy,
                PkDeletionStrategyWithCache::Int64Pk { .. }
            ),
            "a single-Int64 primary key selects the Int64Pk deletion strategy"
        );
        assert!(
            int64_pk.pk_row_converter.is_none(),
            "the Int64Pk strategy must cache no RowConverter: its deletion-vector \
             tombstone keys are raw big-endian, not OwnedRow encodings"
        );

        let (int32_pk, _tmp_int32) = create_table_with_pk_columns(
            "pk_guard_int32",
            &[("id", DataType::Int32)],
            ctx.runtime_env(),
        )
        .await;
        assert!(
            matches!(
                int32_pk.pk_deletion_strategy,
                PkDeletionStrategyWithCache::RowConverterBased { .. }
            ),
            "an Int32 primary key selects the RowConverterBased deletion strategy"
        );
        assert!(
            int32_pk.pk_row_converter.is_some(),
            "the RowConverterBased strategy must cache its RowConverter"
        );

        // `Int64Pk` is selected only for one Int64 column; a composite of two
        // uses `RowConverterBased` and caches a converter.
        let (composite_pk, _tmp_composite) = create_table_with_pk_columns(
            "pk_guard_composite",
            &[("id", DataType::Int64), ("part", DataType::Int64)],
            ctx.runtime_env(),
        )
        .await;
        assert!(
            matches!(
                composite_pk.pk_deletion_strategy,
                PkDeletionStrategyWithCache::RowConverterBased { .. }
            ),
            "a composite primary key selects the RowConverterBased deletion strategy \
             even when every column is Int64"
        );
        assert!(
            composite_pk.pk_row_converter.is_some(),
            "a composite Int64 primary key must cache its RowConverter"
        );
    }

    fn id_value_batch(schema: SchemaRef, ids: &[i64], values: &[i64]) -> RecordBatch {
        use arrow::array::Int64Array;
        RecordBatch::try_new(
            schema,
            vec![
                Arc::new(Int64Array::from(ids.to_vec())),
                Arc::new(Int64Array::from(values.to_vec())),
            ],
        )
        .expect("id/value batch is valid")
    }

    fn id_value_batch_for_range(schema: SchemaRef, start_id: i64, rows: i64) -> RecordBatch {
        let ids: Vec<i64> = (start_id..start_id + rows).collect();
        let values: Vec<i64> = ids.iter().map(|id| id * 10).collect();
        id_value_batch(schema, &ids, &values)
    }

    /// Read back all `(id, value)` pairs, sorted by id, for assertion.
    async fn collect_id_value_pairs(
        ctx: &SessionContext,
        provider: &CayenneTableProvider,
        table_name: &str,
    ) -> Vec<(i64, i64)> {
        use arrow::array::Int64Array;
        let batches = read_all(ctx, provider, table_name).await;
        let mut pairs = Vec::new();
        for batch in &batches {
            let id_idx = batch.schema().index_of("id").expect("id column");
            let value_idx = batch.schema().index_of("value").expect("value column");
            let ids = batch
                .column(id_idx)
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("id is Int64");
            let values = batch
                .column(value_idx)
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("value is Int64");
            for row in 0..batch.num_rows() {
                pairs.push((ids.value(row), values.value(row)));
            }
        }
        pairs.sort_unstable();
        pairs
    }

    // `AggregateExec` is referenced in the signatures below (return type /
    // `&AggregateExec` param); table.rs's top level does not import it.
    use datafusion::physical_plan::aggregates::AggregateExec;

    // ----------------------------------------------------------------------
    // Staged-disk CDC path → maintained-aggregate (IVM) feed.
    //
    // These tests gate the reorder-fix invariant: the STAGED publish path now
    // feeds the maintained-aggregate registry (previously only the in-mem path
    // did), and epoch-assign + applier-enqueue MUST be atomic under the held
    // listing fence. Pipelined/detached staged finish() tasks would otherwise
    // enqueue epochs out of order and `begin_maintenance_pass` would PERMANENTLY
    // stale the registry on a +1 gap.
    // ----------------------------------------------------------------------

    /// Mirror of `create_cdc_upsert_table_with_vortex_config` (id Int64, value
    /// Int64, PK=id, `on_conflict` `Upsert(id)`) but registers maintained-aggregate
    /// views on the BUILDER and pins the table to the STAGED-disk CDC path
    /// (`cdc_durability: File`, `inline_max_rows: 0`, `deletion_mode: Key`) so
    /// every write exercises `feed_staged_ivm_under_fence`, not the in-mem feed.
    async fn create_cdc_upsert_table_with_maintained_aggregates(
        table_name: &str,
        runtime_env: Arc<RuntimeEnv>,
        specs: Vec<MaintainedAggregateSpec>,
    ) -> (CayenneTableProvider, Arc<dyn MetadataCatalog>, TempDir) {
        use arrow::datatypes::{DataType, Field, Schema};

        let temp_dir = tempfile::tempdir().expect("temp dir");
        let metadata_dir = format!("{}/metadata", temp_dir.path().to_str().expect("str path"));
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("str path"));
        std::fs::create_dir_all(&metadata_dir).expect("metadata dir created");

        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog created"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("catalog initialized");

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));

        let options = CreateTableOptions {
            table_name: table_name.to_string(),
            schema,
            primary_key: vec!["id".to_string()],
            on_conflict: Some(OnConflict::Upsert(
                datafusion_table_providers::util::column_reference::ColumnReference::new(vec![
                    "id".to_string(),
                ]),
            )),
            base_path: data_dir,
            partition_column: None,
            // Force the staged-disk path: File (not the default Memory), no inline
            // memtable, key-mode deletes (so the PK retraction index is built =>
            // `supports_retraction()` => `should_capture_staged_ivm_feed()` true).
            vortex_config: VortexConfig {
                cdc_durability: crate::metadata::CdcDurability::File,
                inline_max_rows: 0,
                deletion_mode: crate::metadata::DeletionMode::Key,
                ..VortexConfig::default()
            },
        };

        let provider = CayenneTableProviderBuilder::new(Arc::clone(&catalog), runtime_env)
            .with_maintained_aggregates(specs)
            .create(options)
            .await
            .expect("table created");
        (provider, catalog, temp_dir)
    }

    /// A maintained-aggregate spec over the (id, value) table: GROUP BY id,
    /// COUNT(*), SUM(value). Both outputs are Int64 (supported).
    fn id_count_sum_spec() -> MaintainedAggregateSpec {
        use crate::maintained_aggregate::{MaintainedAggregateExpr, MaintainedAggregateFunction};
        MaintainedAggregateSpec {
            filter: None,
            group_by: vec!["id".to_string()],
            aggregates: vec![
                MaintainedAggregateExpr {
                    function: MaintainedAggregateFunction::Count,
                    column: None, // COUNT(*)
                },
                MaintainedAggregateExpr {
                    function: MaintainedAggregateFunction::Sum,
                    column: Some("value".to_string()),
                },
            ],
        }
    }

    /// Build an `AggregateExec` for `GROUP BY id, COUNT(*), SUM(value)` over the
    /// (id Int64, value Int64) schema. The exec never runs — the registry only
    /// reads its SHAPE (group-by + aggregate functions/columns) to match a view
    /// and its OUTPUT SCHEMA to materialize the served batch. Modeled on
    /// `maintained_aggregate::tests::aggregate_exec_for`: a `MemorySourceConfig`
    /// input over the table schema, `count(*)` via a non-null literal (=>
    /// `CountQueryColumn::AllRows`), `sum(value)` over the column, `AggregateMode::Single`.
    fn build_id_count_sum_aggregate_exec() -> AggregateExec {
        use arrow::datatypes::{DataType, Field, Schema};
        use datafusion::physical_expr::aggregate::AggregateExprBuilder;
        use datafusion::physical_expr::expressions::{col, lit};
        use datafusion::physical_plan::aggregates::{AggregateMode, PhysicalGroupBy};
        use datafusion_functions_aggregate::count::count_udaf;
        use datafusion_functions_aggregate::sum::sum_udaf;

        let schema: SchemaRef = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let input = MemorySourceConfig::try_new_exec(&[vec![]], Arc::clone(&schema), None)
            .expect("memory source exec for aggregate input");

        let group_by = PhysicalGroupBy::new_single(vec![(
            col("id", schema.as_ref()).expect("id column"),
            "id".to_string(),
        )]);

        // ORDER MATTERS: the view match is order-sensitive, so this must be
        // [count(*), sum(value)] to mirror `id_count_sum_spec`.
        let count_expr = AggregateExprBuilder::new(count_udaf(), vec![lit(1_i8)])
            .schema(Arc::clone(&schema))
            .alias("count(*)".to_string())
            .build()
            .map(Arc::new)
            .expect("count(*) aggregate expr");
        let sum_expr = AggregateExprBuilder::new(
            sum_udaf(),
            vec![col("value", schema.as_ref()).expect("value column")],
        )
        .schema(Arc::clone(&schema))
        .alias("sum(value)".to_string())
        .build()
        .map(Arc::new)
        .expect("sum(value) aggregate expr");

        let aggr_exprs = vec![count_expr, sum_expr];
        let filters = vec![None; aggr_exprs.len()];
        AggregateExec::try_new(
            AggregateMode::Single,
            group_by,
            aggr_exprs,
            filters,
            input,
            schema,
        )
        .expect("id/count/sum AggregateExec")
    }

    /// Poll the maintained-aggregate registry until it serves a fresh batch at
    /// the table's current scan epoch (the value `scan()` would capture), or fail
    /// after ~5s. The staged feed enqueues to a BACKGROUND applier with no sync
    /// drain, so a serve right after `finish()` legitimately returns `None`
    /// (registry epoch still trails the just-assigned epoch) until the applier
    /// catches up. A timeout here is a real failure: under the off-fence (buggy)
    /// design an out-of-order enqueue PERMANENTLY stales the registry, so the
    /// serve never becomes `Some` and this helper times out — which is exactly
    /// what makes TEST 2 a regression gate for the reorder fix.
    async fn poll_maintained_serve(
        provider: &CayenneTableProvider,
        aggregate_exec: &AggregateExec,
    ) -> RecordBatch {
        use std::sync::atomic::Ordering;
        for _ in 0..50 {
            let epoch = provider.maintained_aggregate_epoch.load(Ordering::Acquire);
            let served = provider
                .maintained_aggregates
                .batch_for_aggregate(aggregate_exec, epoch)
                .expect("maintained serve must not error");
            if let Some(batch) = served
                && batch.num_rows() > 0
            {
                return batch;
            }
            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        }
        panic!(
            "maintained aggregate never served a fresh non-empty batch within ~5s \
             (applier never caught up, or the registry was permanently staled by an \
             out-of-order staged epoch enqueue)"
        );
    }

    /// Read the served (id, count, sum) rows out of a maintained-aggregate batch
    /// sorted by id. Column layout: [0]=id (group key), [1]=`count(*)`, [2]=`sum(value)`,
    /// all Int64 (see `build_id_count_sum_aggregate_exec` / `id_count_sum_spec`).
    fn collect_id_count_sum(batch: &RecordBatch) -> Vec<(i64, i64, i64)> {
        use arrow::array::Int64Array;
        let ids = batch
            .column(0)
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("id is Int64");
        let counts = batch
            .column(1)
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("count(*) is Int64");
        let sums = batch
            .column(2)
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("sum(value) is Int64");
        let mut rows: Vec<(i64, i64, i64)> = (0..batch.num_rows())
            .map(|r| (ids.value(r), counts.value(r), sums.value(r)))
            .collect();
        rows.sort_unstable();
        rows
    }

    /// A scan racing a mem-tier visibility publish must keep its base aggregate
    /// plan rather than attach an epoch to a potentially torn shard capture.
    /// Once the publish completes, a stable capture may use the new epoch.
    #[tokio::test]
    async fn test_mem_tier_scan_capture_declines_maintained_aggregate_during_visibility_publish() {
        let ctx = SessionContext::new();
        let (provider, _catalog, _tmp) = create_cdc_upsert_table_with_maintained_aggregates(
            "ivm_scan_capture",
            ctx.runtime_env(),
            vec![id_count_sum_spec()],
        )
        .await;
        let visibility_guard = provider
            .begin_maintained_aggregate_visibility_write()
            .expect("configured IVM must create a visibility guard");
        let (_, racing_epoch) = provider.capture_mem_tier_aggregate_scan_state();
        assert_eq!(
            racing_epoch, None,
            "a racing scan must keep the base aggregate plan"
        );

        let published_epoch = provider.next_maintained_aggregate_epoch();
        drop(visibility_guard);
        let (_, stable_epoch) = provider.capture_mem_tier_aggregate_scan_state();
        assert_eq!(stable_epoch, Some(published_epoch));
    }

    /// TEST 1 — the staged-disk CDC path feeds the maintained-aggregate registry.
    ///
    /// The table starts EMPTY, so the open-time rebuild initializes the registry
    /// with ZERO groups at epoch 0. A served result with groups can therefore only
    /// have come from the staged feed. One staged write (two new keys) is published
    /// via `write_cdc_append_stream` + `finish()`; we then poll the registry and
    /// assert it serves the correct per-id count/sum.
    #[tokio::test]
    async fn test_staged_write_feeds_maintained_aggregate() {
        let ctx = SessionContext::new();
        let (provider, _catalog, _tmp) = create_cdc_upsert_table_with_maintained_aggregates(
            "staged_ivm_feed",
            ctx.runtime_env(),
            vec![id_count_sum_spec()],
        )
        .await;
        let schema = Arc::clone(&provider.table_metadata.schema);

        // Sanity: the staged-disk path is active (not the in-mem tier), so the
        // write returns a pending finalize and routes through
        // `apply_under_barrier` -> `feed_staged_ivm_under_fence`.
        assert!(
            !provider.is_cdc_memory_mode(),
            "must use the staged File path"
        );

        let write = provider
            .write_cdc_append_stream(
                single_batch_stream(id_value_batch(Arc::clone(&schema), &[1, 2], &[10, 20])),
                &ctx.task_ctx(),
            )
            .await
            .expect("staged CDC write should prepare");
        assert!(
            write.has_pending_finalize(),
            "staged File-mode write must defer to a finalize publish"
        );
        write.finish().await.expect("finalize staged write");

        // The published rows are visible to a normal scan...
        assert_eq!(
            collect_id_value_pairs(&ctx, &provider, "staged_ivm_feed").await,
            vec![(1, 10), (2, 20)],
        );

        // ...and the maintained-aggregate registry, fed under the fence, serves
        // the same relation incrementally once the background applier catches up.
        let aggregate_exec = build_id_count_sum_aggregate_exec();
        let served = poll_maintained_serve(&provider, &aggregate_exec).await;
        assert_eq!(
            collect_id_count_sum(&served),
            vec![(1, 1, 10), (2, 1, 20)],
            "staged feed must populate count(*)=1 and sum(value)=value per key"
        );
    }

    /// N>1 mem-tier CDC: DELETE retracts maintained aggregates (pre-bump epoch +
    /// serial post-join feed). Before this fix, `append_delete_intents_sharded`
    /// passed `None` for retract rows, so a Fresh registry kept counting deleted
    /// keys under sharding.
    #[tokio::test]
    async fn test_n_gt_1_mem_tier_delete_retracts_maintained_aggregate() {
        use arrow::datatypes::{DataType, Field, Schema};
        use std::sync::atomic::Ordering;

        let ctx = SessionContext::new();
        let runtime_env = ctx.runtime_env();
        let temp_dir = tempfile::tempdir().expect("temp dir");
        let metadata_dir = format!("{}/metadata", temp_dir.path().to_str().expect("str"));
        let data_dir = format!("{}/data", temp_dir.path().to_str().expect("str"));
        tokio::fs::create_dir_all(&metadata_dir)
            .await
            .expect("metadata dir");
        let connection_string = format!("sqlite://{metadata_dir}/cayenne.db");
        let catalog = Arc::new(CayenneCatalog::new(connection_string).expect("catalog"))
            as Arc<dyn MetadataCatalog>;
        catalog.init().await.expect("init catalog");

        let schema = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let options = CreateTableOptions {
            table_name: "n_gt_1_ivm_delete".to_string(),
            schema: Arc::clone(&schema),
            primary_key: vec!["id".to_string()],
            on_conflict: Some(OnConflict::Upsert(
                datafusion_table_providers::util::column_reference::ColumnReference::new(vec![
                    "id".to_string(),
                ]),
            )),
            base_path: data_dir,
            partition_column: None,
            vortex_config: VortexConfig {
                cdc_durability: crate::metadata::CdcDurability::Memory,
                cdc_mem_tier_shards: 4,
                cdc_mem_tier_min_flush_bytes: 0,
                deletion_mode: crate::metadata::DeletionMode::Key,
                inline_max_rows: 1024,
                ..VortexConfig::default()
            },
        };
        let provider = CayenneTableProviderBuilder::new(catalog, runtime_env)
            .with_maintained_aggregates(vec![id_count_sum_spec()])
            .create(options)
            .await
            .expect("table created");
        // Slot advancer required for in-memory CDC delete absorption + N>1 path.
        provider.install_slot_advancer(Arc::new(NoopSlotAdvancer));
        assert!(provider.is_cdc_memory_mode());
        assert!(
            provider.mem_tier_shard_count() > 1,
            "test requires N>1 sharding"
        );
        assert!(
            provider.supports_in_memory_cdc_deletes(),
            "upsert + memory mode must absorb deletes"
        );

        // Insert via the real sharded CDC path so keys fan out across shards.
        let ids: Vec<i64> = (1..=16).collect();
        let values: Vec<i64> = ids.iter().map(|i| i * 10).collect();
        let write = provider
            .write_cdc_append_stream(
                single_batch_stream(id_value_batch(Arc::clone(&schema), &ids, &values)),
                &ctx.task_ctx(),
            )
            .await
            .expect("sharded CDC insert");
        assert!(
            write.in_memory_epoch().is_some(),
            "insert must land in the mem tier"
        );

        let aggregate_exec = build_id_count_sum_aggregate_exec();
        let served_before = poll_maintained_serve(&provider, &aggregate_exec).await;
        assert_eq!(
            collect_id_count_sum(&served_before).len(),
            16,
            "all 16 keys should be in the maintained view after insert"
        );

        // Delete a subset via the N>1 sharded delete path (takes write_lock internally).
        let delete_ids = [1_i64, 5, 9, 13];
        let delete_batch = int64_id_batch(&delete_ids);
        let absorbed = provider
            .write_cdc_delete_keys_in_memory(&delete_batch)
            .await
            .expect("sharded N>1 delete")
            .expect("delete absorbed into mem tier");
        assert!(absorbed > 0, "delete must advance a mem-tier epoch");

        // After delete, maintained serve must drop those keys.
        let expected_remaining: Vec<(i64, i64, i64)> = ids
            .iter()
            .filter(|id| !delete_ids.contains(id))
            .map(|&id| (id, 1_i64, id * 10))
            .collect();
        let mut last = Vec::new();
        for _ in 0..50 {
            let epoch = provider.maintained_aggregate_epoch.load(Ordering::Acquire);
            if let Ok(Some(batch)) = provider
                .maintained_aggregates
                .batch_for_aggregate(&aggregate_exec, epoch)
            {
                last = collect_id_count_sum(&batch);
                if last == expected_remaining {
                    return;
                }
            }
            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        }
        panic!(
            "N>1 delete did not retract maintained aggregate within ~5s; \
             last served={last:?}, expected={expected_remaining:?} \
             (registry likely Fresh-but-stale or permanently Stale)"
        );
    }

    /// GROUP BY id, MIN(value), MAX(value) — used by the N>1 min/max retract test.
    fn id_min_max_spec() -> MaintainedAggregateSpec {
        use crate::maintained_aggregate::{MaintainedAggregateExpr, MaintainedAggregateFunction};
        MaintainedAggregateSpec {
            filter: None,
            group_by: vec!["id".to_string()],
            aggregates: vec![
                MaintainedAggregateExpr {
                    function: MaintainedAggregateFunction::Min,
                    column: Some("value".to_string()),
                },
                MaintainedAggregateExpr {
                    function: MaintainedAggregateFunction::Max,
                    column: Some("value".to_string()),
                },
            ],
        }
    }

    fn build_id_min_max_aggregate_exec() -> AggregateExec {
        use arrow::datatypes::{DataType, Field, Schema};
        use datafusion::physical_expr::aggregate::AggregateExprBuilder;
        use datafusion::physical_expr::expressions::col;
        use datafusion::physical_plan::aggregates::{AggregateMode, PhysicalGroupBy};
        use datafusion_functions_aggregate::min_max::{max_udaf, min_udaf};

        let schema: SchemaRef = Arc::new(Schema::new(vec![
            Field::new("id", DataType::Int64, false),
            Field::new("value", DataType::Int64, false),
        ]));
        let input = MemorySourceConfig::try_new_exec(&[vec![]], Arc::clone(&schema), None)
            .expect("memory source exec for aggregate input");

        let group_by = PhysicalGroupBy::new_single(vec![(
            col("id", schema.as_ref()).expect("id column"),
            "id".to_string(),
        )]);

        let min_expr = AggregateExprBuilder::new(
            min_udaf(),
            vec![col("value", schema.as_ref()).expect("value column")],
        )
        .schema(Arc::clone(&schema))
        .alias("min(value)".to_string())
        .build()
        .map(Arc::new)
        .expect("min(value) aggregate expr");
        let max_expr = AggregateExprBuilder::new(
            max_udaf(),
            vec![col("value", schema.as_ref()).expect("value column")],
        )
        .schema(Arc::clone(&schema))
        .alias("max(value)".to_string())
        .build()
        .map(Arc::new)
        .expect("max(value) aggregate expr");

        let aggr_exprs = vec![min_expr, max_expr];
        let filters = vec![None; aggr_exprs.len()];
        AggregateExec::try_new(
            AggregateMode::Single,
            group_by,
            aggr_exprs,
            filters,
            input,
            schema,
        )
        .expect("id/min/max AggregateExec")
    }

    fn collect_id_min_max(batch: &RecordBatch) -> Vec<(i64, i64, i64)> {
        use arrow::array::Int64Array;
        let ids = batch
            .column(0)
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("id is Int64");
        let mins = batch
            .column(1)
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("min(value) is Int64");
        let maxs = batch
            .column(2)
            .as_any()
            .downcast_ref::<Int64Array>()
            .expect("max(value) is Int64");
        let mut rows = Vec::with_capacity(batch.num_rows());
        for i in 0..batch.num_rows() {
            rows.push((ids.value(i), mins.value(i), maxs.value(i)));
        }
        rows.sort_by_key(|r| r.0);
        rows
    }

    /// N>1 mem-tier CDC delete must retract MIN/MAX maintained aggregates (the
